function readLLMConfig(prefix: string) {
  return {
    provider: process.env[`${prefix}PROVIDER`] || (prefix ? '' : 'openai'),
    openaiApiKey: process.env[`${prefix}OPENAI_API_KEY`] ? '***set***' : '',
    openaiBaseUrl: process.env[`${prefix}OPENAI_BASE_URL`] || '',
    openaiModel: process.env[`${prefix}OPENAI_MODEL`] || '',
    anthropicApiKey: process.env[`${prefix}ANTHROPIC_API_KEY`] ? '***set***' : '',
    anthropicModel: process.env[`${prefix}ANTHROPIC_MODEL`] || '',
  };
}

function buildLLMConfig(body: any, prefix: string): any {
  const { provider, apiKey, model, baseUrl } = body;
  if (!provider) return {};
  const normalizedProvider = provider === 'ollama' ? 'openai' : provider;
  if (normalizedProvider === 'anthropic') {
    return { provider: 'anthropic', apiKey, model };
  }
  return { provider: 'openai', apiKey, model, baseUrl };
}

