import { Router } from 'express';
import { AITranslator } from '../ai/translator.js';

class LRUCache {
  private map = new Map<string, string>();
  constructor(private max: number) {}
  get(key: string): string | undefined {
    const val = this.map.get(key);
    if (val !== undefined) { this.map.delete(key); this.map.set(key, val); }
    return val;
  }
  set(key: string, val: string) {
    if (this.map.has(key)) this.map.delete(key);
    else if (this.map.size >= this.max) { const first = this.map.keys().next().value; if (first !== undefined) this.map.delete(first); }
    this.map.set(key, val);
  }
}

export const reasoningRoutes = Router();
const translator = new AITranslator();
const cache = new LRUCache(50);

reasoningRoutes.post('/', async (req, res) => {
  try {
    const { prompt, system, codeContext, maxTokens } = req.body;
    if (!prompt) {
      return res.status(400).json({ error: 'Prompt is required' });
    }

    const fullPrompt = codeContext
      ? `Context from generated code:\n\`\`\`\n${codeContext}\n\`\`\`\n\n${prompt}`
      : prompt;

    const cacheKey = `${system || ''}|${fullPrompt}|${maxTokens || 1024}`;
    const cached = cache.get(cacheKey);
    if (cached) return res.json({ success: true, response: cached, cached: true });

    const response = await translator.reason(fullPrompt, system, { maxTokens: maxTokens || 1024 });
    cache.set(cacheKey, response);
    res.json({ success: true, response });
  } catch (error) {
    res.status(500).json({
      error: error instanceof Error ? error.message : 'Reasoning failed',
    });
  }
});

import { Router, Request, Response } from 'express';
import { exec, execSync } from 'child_process';
import path from 'path';

const router = Router();

const PROJECT_ROOT = path.resolve(import.meta.dirname, '..', '..', '..');
const TRAINING_APP_DIR = path.join(PROJECT_ROOT, 'llm-training-app');
const RUN_SCRIPT = path.join(TRAINING_APP_DIR, 'run.sh');

router.post('/open', (_req: Request, res: Response) => {
  try {
    // Ensure run.sh is executable
    try {
      execSync(`chmod +x "${RUN_SCRIPT}"`, { timeout: 2000 });
    } catch { /* ignore */ }

    const proc = exec(`"${RUN_SCRIPT}"`, { cwd: TRAINING_APP_DIR, env: { ...process.env } });

    let started = false;
    proc.stdout?.on('data', (data: string) => {
      if (!started) {
        started = true;
        res.json({ status: 'launched', path: TRAINING_APP_DIR });
      }
    });

    proc.stderr?.on('data', (data: string) => {
      console.error('[training]', data.toString());
    });

    proc.on('error', (err) => {
      if (!started) {
        started = true;
        res.status(500).json({ error: err.message });
      }
    });

    proc.on('exit', (code) => {
      if (!started) {
        started = true;
        if (code === 0) {
          res.json({ status: 'launched', path: TRAINING_APP_DIR });
        } else {
          res.status(500).json({ error: `run.sh exited with code ${code}` });
        }
      }
    });

    // Safety timeout
    setTimeout(() => {
      if (!started) {
        started = true;
        res.json({ status: 'launched', path: TRAINING_APP_DIR });
      }
    }, 5000);
  } catch (err: any) {
    res.status(500).json({ error: err.message });
  }
});

router.get('/status', (_req: Request, res: Response) => {
  res.json({ status: 'standalone', path: TRAINING_APP_DIR });
});

