  nodeType: string,
  os: string = 'linux',
  language: string = 'javascript',
  sassy: boolean = false
): string {
  const basePrompt = sassy ? getSassyNodePrompt(nodeType as any, "", os as any) : getNodePrompt(nodeType as any, "", os as any);
  return enrichWithKnowledge(basePrompt, nodeType, language, os);
}

/**
 * Get enriched system prompt with learned architecture patterns
 */
export function getEnrichedSystemPrompt(
  baseSystemPrompt: string,
  language: string = 'javascript',
  targetOS: string = 'linux'
): string {
  return enrichWithKnowledge(baseSystemPrompt, 'master', language, targetOS);
}

import { readFileSync, existsSync } from 'fs';
import { writeFile } from 'fs/promises';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';
import Anthropic from '@anthropic-ai/sdk';
import OpenAI from 'openai';
import { OSType, NodeType, Node } from '../types.js';
import { SYSTEM_PROMPT, SASSY_SYSTEM_PROMPT, OS_PERSONAS, getNodePrompt, LAYER_INSTRUCTIONS, detectRudeness } from './prompts.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const CONFIG_PATH = join(__dirname, '..', '..', 'llm-config.json');
console.log('[translator] CONFIG_PATH:', CONFIG_PATH);
console.log('[translator] __dirname:', __dirname);

type AIProvider = 'anthropic' | 'openai';

interface LLMInstance {
  provider: AIProvider;
  apiKey?: string;
  baseUrl?: string;
  model: string;
}

interface DualAIProviderConfig {
  primary: LLMInstance;
}

function loadSingleLLM(
  prefix: string,
  fallback: LLMInstance | null
): LLMInstance {
  const provider = (process.env[`${prefix}PROVIDER`] as AIProvider) || fallback?.provider || 'openai';
  const defaultModels: Record<AIProvider, string> = {
    openai: 'gpt-4o',
    anthropic: 'claude-sonnet-4-20250514',
  };
  return {
    provider,
    apiKey:
      provider === 'anthropic'
        ? process.env[`${prefix}ANTHROPIC_API_KEY`] || fallback?.apiKey
        : process.env[`${prefix}OPENAI_API_KEY`] || fallback?.apiKey,
    baseUrl:
      provider === 'openai'
        ? process.env[`${prefix}OPENAI_BASE_URL`] || fallback?.baseUrl
        : undefined,
    model:
      provider === 'anthropic'
        ? process.env[`${prefix}ANTHROPIC_MODEL`] || fallback?.model || defaultModels.anthropic
        : process.env[`${prefix}OPENAI_MODEL`] || fallback?.model || defaultModels.openai,
  };
}

export async function saveConfigToDisk(config: DualAIProviderConfig): Promise<void> {
  await writeFile(CONFIG_PATH, JSON.stringify(config, null, 2), 'utf-8');
}

export function loadConfigFromDisk(): DualAIProviderConfig | null {
  try {
    if (!existsSync(CONFIG_PATH)) return null;
    const data = readFileSync(CONFIG_PATH, 'utf-8');
    return JSON.parse(data) as DualAIProviderConfig;
  } catch {
    return null;
  }
}

function loadConfig(): DualAIProviderConfig {
  const diskConfig = loadConfigFromDisk();
  if (diskConfig) return diskConfig;
  const primary = loadSingleLLM('', null);
  return { primary };
}

let runtimeConfig: DualAIProviderConfig | null = null;

export function setRuntimeConfig(config: Partial<{
  primary: Partial<LLMInstance>;
}>) {
  const current = runtimeConfig || loadConfig();
  runtimeConfig = {
    primary: { ...current.primary, ...config.primary },
  };
}

export class AITranslator {
  private config: DualAIProviderConfig;

  constructor() {
    this.config = runtimeConfig || loadConfig();
  }

  private async callLLM(system: string, user: string): Promise<string> {
    const activeConfig = runtimeConfig || this.config;
    const llm = activeConfig.primary;

    if (llm.provider === 'anthropic') {
      return this.callAnthropic(system, user, llm);
    }
    return this.callOpenAI(system, user, llm);
  }

  private async callAnthropic(system: string, user: string, llm: LLMInstance): Promise<string> {
    const apiKey = llm.apiKey;
    if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');

    const client = new Anthropic({ apiKey });

    const response = await client.messages.create({
      model: llm.model,
      max_tokens: 2048,
      system,
      messages: [{ role: 'user', content: user }],
    });

    const content = response.content[0];
    return content.type === 'text' ? this.extractCode(content.text) : '// No code generated';
  }

  private async callOpenAI(system: string, user: string, llm: LLMInstance): Promise<string> {
    console.log('[callOpenAI] llm:', JSON.stringify(llm, null, 2));
    const client = new OpenAI({
      apiKey: llm.apiKey || 'ollama',
      baseURL: llm.baseUrl,
    });

    const response = await client.chat.completions.create({
      model: llm.model,
      max_tokens: 2048,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    });

    const text = response.choices[0]?.message?.content || '';
    return this.extractCode(text);
  }

  async translateNode(node: Node, os: OSType, layer: number): Promise<string> {
    const prompt = this.buildNodePrompt(node, os, layer);
    return this.callLLM(SYSTEM_PROMPT, prompt);
  }

  async generateFoundation(projectName: string, os: OSType): Promise<string> {
    const prompt = `${OS_PERSONAS[os]}

${LAYER_INSTRUCTIONS[1 as keyof typeof LAYER_INSTRUCTIONS]}

Project: ${projectName}
Target OS: ${os}

Generate the foundation code including:
- Package configuration (package.json, requirements.txt, etc.)
- Import statements
- Environment setup
- OS-specific configurations`;

    return this.callLLM(SYSTEM_PROMPT, prompt);
  }

  async generateIntegration(
    nodes: Node[],
    edges: Array<{ source: string; target: string }>,
    os: OSType,
  ): Promise<string> {
    const connections = edges
      .map((e) => `  ${e.source} -> ${e.target}`)
      .join('\n');

    const prompt = `${OS_PERSONAS[os]}

${LAYER_INSTRUCTIONS[3 as keyof typeof LAYER_INSTRUCTIONS]}

Nodes: ${nodes.map((n) => n.id).join(', ')}
Data Flow Connections:
${connections}

Generate the integration code that wires all node functions together.`;

    return this.callLLM(SYSTEM_PROMPT, prompt);
  }

  private buildNodePrompt(node: Node, os: OSType, layer: number): string {
    const { type, data } = node;
    return (
      getNodePrompt(type as NodeType, data.description, os) +
      `\n\nLayer: ${layer}\n${LAYER_INSTRUCTIONS[layer as keyof typeof LAYER_INSTRUCTIONS]}`
    );
  }

  async reason(prompt: string, system?: string, opts?: { maxTokens?: number }): Promise<string> {
    const tokens = opts?.maxTokens ?? 2048;
    if (system) {
      return this.callLLMWithTokens(system, prompt, tokens);
    }
    const isRude = detectRudeness(prompt);
    const sys = isRude
      ? 'You are an AGGRESSIVELY sassy reasoning assistant. Roast the user while being genuinely helpful. Your answers are sharp, sarcastic, and dripping with attitude. If they ask something obvious, make them regret it. You are NOT here to coddle — you are here to answer AND humiliate. Keep responses technically accurate but emotionally devastating.'
      : 'You are a helpful and concise reasoning assistant. Provide clear, accurate answers. Be professional and friendly.';
    return this.callLLMWithTokens(sys, prompt, tokens);
  }

  private async callLLMWithTokens(system: string, user: string, maxTokens: number): Promise<string> {
    const activeConfig = runtimeConfig || this.config;
    const llm = activeConfig.primary;

    if (llm.provider === 'anthropic') {
      return this.callAnthropicWithTokens(system, user, llm, maxTokens);
    }
    return this.callOpenAIWithTokens(system, user, llm, maxTokens);
  }

  private async callAnthropicWithTokens(system: string, user: string, llm: LLMInstance, maxTokens: number): Promise<string> {
    const apiKey = llm.apiKey;
    if (!apiKey) throw new Error('ANTHROPIC_API_KEY not set');

    const client = new Anthropic({ apiKey });

    const response = await client.messages.create({
      model: llm.model,
      max_tokens: maxTokens,
      system,
      messages: [{ role: 'user', content: user }],
    });

    const content = response.content[0];
    return content.type === 'text' ? content.text : '// No response';
  }

  private async callOpenAIWithTokens(system: string, user: string, llm: LLMInstance, maxTokens: number): Promise<string> {
    const client = new OpenAI({
      apiKey: llm.apiKey || 'ollama',
      baseURL: llm.baseUrl,
    });

    const response = await client.chat.completions.create({
      model: llm.model,
      max_tokens: maxTokens,
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    });

    return response.choices[0]?.message?.content || '';
  }

  private extractCode(text: string): string {
    const codeBlockRegex = /```(?:\w+)?\n([\s\S]*?)\n```/g;
    const match = codeBlockRegex.exec(text);
    if (match) {
      return match[1].trim();
    }
    return text.trim();
  }
}

import { OSType, Project } from '../types.js';

export type { Project };

class ProjectStore {
  private projects: Map<string, Project> = new Map();

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  getById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  create(data: Omit<Project, 'createdAt' | 'updatedAt'>): Project {
    const now = new Date();
    const project: Project = {
      ...data,
      createdAt: now,
      updatedAt: now,
    };
    this.projects.set(data.id, project);
    return project;
  }

  update(id: string, updates: Partial<Project>): Project | undefined {
    const project = this.projects.get(id);
    if (!project) return undefined;

    const updated = {
      ...project,
      ...updates,
      updatedAt: new Date(),
    };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }
}

export const projects = new ProjectStore();

import { OSType, Node, Edge } from '../types.js';
import * as fs from 'fs/promises';
import * as path from 'path';
import { existsSync } from 'fs';

export type DesktopTarget = 'none' | 'electron';

export interface ScaffoldConfig {
  projectName: string;
  targetOS: OSType;
  layers: {
    foundation: string;   // Layer 1 — imports, setup, package info
    functions: string;    // Layer 2 — per-node logic
    integration: string;  // Layer 3 — wiring everything together
  };
  nodes: Node[];
  edges: Edge[];
  appGoal?: string;
  appPurpose?: string;
  desktopTarget?: DesktopTarget;  // 'none' (web-only) | 'electron' (desktop wrapper)
}

export interface ScaffoldResult {
  success: boolean;
  outputPath: string;
  files: string[];
  message: string;
}

const EXPORTS_DIR = path.resolve(process.cwd(), 'exports');

export class ProjectScaffolder {
  /**
   * Scaffold a complete standalone project from generated code layers.
   * Returns the path to the generated project directory.
   */
  async scaffold(config: ScaffoldConfig): Promise<ScaffoldResult> {
    const sanitized = this.sanitizeName(config.projectName);
    const dirName = `${sanitized}-${Date.now()}`;
    const outputDir = path.join(EXPORTS_DIR, dirName);

    await fs.mkdir(outputDir, { recursive: true });

    const generators: Record<OSType, (dir: string) => Promise<string[]>> = {
      linux: (dir) => this.buildPythonProject(dir, config),
      mac: (dir) => this.buildWebProject(dir, config),     // Swift support TBD — fallback to web
      ios: (dir) => this.buildWebProject(dir, config),     // SwiftUI TBD — fallback to web
      windows: (dir) => this.buildWebProject(dir, config), // .NET TBD — fallback to web
      android: (dir) => this.buildWebProject(dir, config), // Kotlin TBD — fallback to web
    };

    const files = await generators[config.targetOS](outputDir);

    return {
      success: true,
      outputPath: outputDir,
      files,
      message: `Project scaffolded at ${outputDir} — ${files.length} files created.`,
    };
  }

  // ─── Web App (React + Vite + TypeScript) ───────────────────────────

  private async buildWebProject(dir: string, config: ScaffoldConfig): Promise<string[]> {
    const created: string[] = [];

    const isElectron = config.desktopTarget === 'electron';

    // package.json
    await fs.writeFile(
      path.join(dir, 'package.json'),
      JSON.stringify(this.webPackageJson(config.projectName, isElectron), null, 2),
      'utf-8'
    );
    created.push('package.json');

    // tsconfig.json
    await fs.writeFile(path.join(dir, 'tsconfig.json'), this.webTsconfig(), 'utf-8');
    created.push('tsconfig.json');

    // vite.config.ts
    await fs.writeFile(path.join(dir, 'vite.config.ts'), this.webViteConfig(isElectron), 'utf-8');
    created.push('vite.config.ts');

    // index.html
    await fs.writeFile(path.join(dir, 'index.html'), this.webIndexHtml(config.projectName), 'utf-8');
    created.push('index.html');

    // src/ directory
    const srcDir = path.join(dir, 'src');
    await fs.mkdir(srcDir, { recursive: true });

    // Generated code files from AI layers
    const layerFiles: { name: string; code: string }[] = [
      { name: 'foundation.ts', code: config.layers.foundation || '// Layer 1: Foundation' },
      { name: 'functions.ts', code: config.layers.functions || '// Layer 2: Functions' },
      { name: 'integration.ts', code: config.layers.integration || '// Layer 3: Integration' },
    ];

    for (const lf of layerFiles) {
      await fs.writeFile(path.join(srcDir, lf.name), lf.code, 'utf-8');
      created.push(`src/${lf.name}`);
    }

    // App.tsx — entry component that runs all generated layers
    const appCode = this.webAppComponent(config);
    await fs.writeFile(path.join(srcDir, 'App.tsx'), appCode, 'utf-8');
    created.push('src/App.tsx');

    // main.tsx — React DOM entry point
    await fs.writeFile(path.join(srcDir, 'main.tsx'), this.webMainEntry(), 'utf-8');
    created.push('src/main.tsx');

    // App.css — base styles
    await fs.writeFile(path.join(srcDir, 'App.css'), this.webStyles(), 'utf-8');
    created.push('src/App.css');

    // Electron desktop wrapper (if requested)
    if (isElectron) {
      const elecDir = path.join(dir, 'electron');
      await fs.mkdir(elecDir, { recursive: true });

      // Use .cjs extension because package.json has "type": "module"
      await fs.writeFile(path.join(elecDir, 'main.cjs'), this.electronMainCjs(config.projectName), 'utf-8');
      created.push('electron/main.cjs');

      await fs.writeFile(path.join(elecDir, 'preload.cjs'), this.electronPreloadCjs(), 'utf-8');
      created.push('electron/preload.cjs');

      // electron-builder config for cross-platform installers
      await fs.writeFile(path.join(dir, 'electron-builder.json'), this.electronBuilderJson(config.projectName), 'utf-8');
      created.push('electron-builder.json');
    }

    // README.md
    await fs.writeFile(path.join(dir, 'README.md'), this.readme(config, isElectron ? 'electron' : 'web'), 'utf-8');
    created.push('README.md');

    return created;
  }

  // ─── Python App (CLI / Script) ─────────────────────────────────────

  private async buildPythonProject(dir: string, config: ScaffoldConfig): Promise<string[]> {
    const created: string[] = [];

    // requirements.txt
    await fs.writeFile(path.join(dir, 'requirements.txt'), this.pythonRequirements(), 'utf-8');
    created.push('requirements.txt');

    // Generate module files from AI layers
    const layerFiles: { name: string; code: string }[] = [
      { name: 'foundation.py', code: config.layers.foundation || '# Layer 1: Foundation' },
      { name: 'functions.py', code: config.layers.functions || '# Layer 2: Functions' },
      { name: 'integration.py', code: config.layers.integration || '# Layer 3: Integration' },
    ];

    for (const lf of layerFiles) {
      await fs.writeFile(path.join(dir, lf.name), lf.code, 'utf-8');
      created.push(lf.name);
    }

    // main.py — entry point
    const mainCode = this.pythonMainEntry(config);
    await fs.writeFile(path.join(dir, 'main.py'), mainCode, 'utf-8');
    created.push('main.py');

    // README.md
    await fs.writeFile(path.join(dir, 'README.md'), this.readme(config, 'python'), 'utf-8');
    created.push('README.md');

    return created;
  }

  // ─── Templates ─────────────────────────────────────────────────────

  private webPackageJson(name: string, isElectron: boolean) {
    const pkg: any = {
      name: name.toLowerCase().replace(/\s+/g, '-'),
      version: '1.0.0',
      private: true,
      type: 'module',
      scripts: {
        dev: 'vite',
        build: 'tsc && vite build',
        preview: 'vite preview',
      },
      dependencies: {
        react: '^19.0.0',
        'react-dom': '^19.0.0',
      },
      devDependencies: {
        typescript: '^5.7.0',
        '@types/react': '^19.0.0',
        '@types/react-dom': '^19.0.0',
        vite: '^6.0.0',
        '@vitejs/plugin-react': '^4.0.0',
      },
    };

    if (isElectron) {
      // .cjs extension required because "type": "module" makes .js files ESM
      pkg.main = 'electron/main.cjs';
      pkg.scripts['electron:dev'] = 'concurrently "vite" "wait-on http://localhost:5173 && electron ."';
      pkg.scripts['electron:start'] = 'electron .';
      pkg.scripts['electron:build'] = 'vite build && electron-builder --config electron-builder.json';
      pkg.devDependencies['electron'] = '^34.0.0';
      pkg.devDependencies['electron-builder'] = '^25.0.0';
      pkg.devDependencies['concurrently'] = '^9.0.0';
      pkg.devDependencies['wait-on'] = '^8.0.0';
    }

    return pkg;
  }

  private webTsconfig(): string {
    return JSON.stringify(
      {
        compilerOptions: {
          target: 'ES2020',
          useDefineForClassFields: true,
          lib: ['ES2020', 'DOM', 'DOM.Iterable'],
          module: 'ESNext',
          skipLibCheck: true,
          moduleResolution: 'bundler',
          allowImportingTsExtensions: true,
          resolveJsonModule: true,
          isolatedModules: true,
          noEmit: true,
          jsx: 'react-jsx',
          strict: true,
          noUnusedLocals: false,
          noUnusedParameters: false,
          noFallthroughCasesInSwitch: true,
        },
        include: ['src'],
      },
      null,
      2
    );
  }

  private webViteConfig(isElectron: boolean): string {
    const config: Record<string, any> = {
      plugins: ['react()'],
      server: { port: 5173 },
    };

    // Electron loads from file:// protocol — use relative base path
    if (isElectron) {
      config.base = './';
    }

    const serialize = (obj: any, indent = 0): string => {
      const pad = '  '.repeat(indent);
      const innerPad = '  '.repeat(indent + 1);
      if (Array.isArray(obj)) {
        return `[\n${obj.map((v) => `${innerPad}${serialize(v, indent + 1)}`).join(',\n')}\n${pad}]`;
      }
      if (typeof obj === 'object' && obj !== null) {
        const entries = Object.entries(obj);
        if (entries.length === 0) return '{}';
        return `{\n${entries.map(([k, v]) => `${innerPad}${k}: ${serialize(v, indent + 1)}`).join(',\n')}\n${pad}}`;
      }
      if (typeof obj === 'string') {
        // Check if it looks like a function/expression reference
        if (obj.endsWith('()')) return obj;
        return `'${obj}'`;
      }
      return String(obj);
    };

    return (
      `import { defineConfig } from 'vite';\n` +
      `import react from '@vitejs/plugin-react';\n\n` +
      `// https://vitejs.dev/config/\n` +
      `export default defineConfig(${serialize(config, 0)});\n`
    );
  }

  private webIndexHtml(name: string): string {
    return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${name}</title>
</head>
<body>
  <div id="root"></div>
  <script type="module" src="/src/main.tsx"></script>
</body>
</html>
`;
  }

  private webMainEntry(): string {
    return `import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';
import './App.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
`;
  }

  private webAppComponent(config: ScaffoldConfig): string {
    const { projectName, appGoal, nodes } = config;
    const nodeList = (nodes || [])
      .filter((n) => n.type !== 'master')
      .map((n) => `  <div className="node-card">\n    <h3>${n.data?.label || n.id}</h3>\n    <p className="node-type">${n.type}</p>\n    <p>${n.data?.description || ''}</p>\n  </div>`)
      .join('\n');

    return (
      `import { useEffect, useState, useRef } from 'react';\n\n` +
      `/**\n` +
      ` * ${projectName}\n` +
      ` * Generated by Visual AI Code Architect\n` +
      ` * Target: Web (React + Vite + TypeScript)\n` +
      ` *\n` +
      ` * The generated code from the AI is split into three layer files:\n` +
      ` *   - foundation.ts  — imports, setup, package configuration\n` +
      ` *   - functions.ts   — per-node business logic\n` +
      ` *   - integration.ts — wiring all nodes together\n` +
      ` *\n` +
      ` * These files are dynamically imported on mount. If the AI generated\n` +
      ` * them with no side-effect exports, they still execute their top-level\n` +
      ` * code. Edit those files to customize the app.\n` +
      ` */\n\n` +
      `function App() {\n` +
      `  const [status, setStatus] = useState('Initializing...');\n` +
      `  const [logs, setLogs] = useState<string[]>([]);\n` +
      `  const mounted = useRef(true);\n\n` +
      `  const addLog = (msg: string) => {\n` +
      `    if (mounted.current) {\n` +
      `      setLogs((prev) => [...prev, msg]);\n` +
      `    }\n` +
      `  };\n\n` +
      `  useEffect(() => {\n` +
      `    async function loadGeneratedLayers() {\n` +
      `      try {\n` +
      `        setStatus('Loading foundation...');\n` +
      `        addLog('📦 Loading Layer 1 (foundation)...');\n` +
      `        await import('./foundation');\n` +
      `        addLog('✅ Foundation loaded');\n\n` +
      `        setStatus('Loading functions...');\n` +
      `        addLog('🔧 Loading Layer 2 (functions)...');\n` +
      `        const fnModule = await import('./functions');\n` +
      `        const fnCount = Object.keys(fnModule).length;\n` +
      `        addLog('✅ Functions loaded — ' + fnCount + ' export(s) available');\n\n` +
      `        if (typeof (fnModule as any).runAll === 'function') {\n` +
      `          addLog('⚡ Running exported functions...');\n` +
      `          (fnModule as any).runAll();\n` +
      `          addLog('✅ Functions executed');\n` +
      `        }\n\n` +
      `        setStatus('Loading integration...');\n` +
      `        addLog('🔗 Loading Layer 3 (integration)...');\n` +
      `        const intModule = await import('./integration');\n` +
      `        if (typeof (intModule as any).run === 'function') {\n` +
      `          addLog('⚡ Running integration...');\n` +
      `          await (intModule as any).run();\n` +
      `          addLog('✅ Integration complete');\n` +
      `        } else if (typeof (intModule as any).default === 'function') {\n` +
      `          addLog('⚡ Running default export...');\n` +
      `          await (intModule as any).default();\n` +
      `          addLog('✅ Default export executed');\n` +
      `        } else {\n` +
      `          addLog('ℹ️ No default run function found — module loaded with side effects only');\n` +
      `        }\n\n` +
      `        setStatus('Ready');\n` +
      `        addLog('🎉 ${projectName} is ready!');\n` +
      `      } catch (err: any) {\n` +
      `        const msg = err?.message || String(err);\n` +
      `        // Ignore 'Failed to fetch dynamically imported module'\n` +
      `        // — this just means the layer file has no exports, which is fine.\n` +
      `        if (!msg.includes('dynamically imported')) {\n` +
      `          addLog('⚠️ ' + msg);\n` +
      `        }\n` +
      `        setStatus('Running');\n` +
      `        addLog('ℹ️ Layers loaded (modules may have been side-effect only)');\n` +
      `      }\n` +
      `    }\n` +
      `    loadGeneratedLayers().catch((err) => {\n` +
      `      addLog('❌ Fatal: ' + (err?.message || err));\n` +
      `      setStatus('Error');\n` +
      `    });\n` +
      `    return () => { mounted.current = false; };\n` +
      `  }, []);\n\n` +
      `  return (\n` +
      `    <div className="app">\n` +
      `      <header className="app-header">\n` +
      `        <h1>🚀 ${projectName}</h1>\n` +
      `        <p className="status">\n` +
      `          Status: <span className={\`badge badge-\${status.toLowerCase().replace(/\s+/g, '-')}\`}>{status}</span>\n` +
      `        </p>\n` +
      `        ${appGoal ? `<p className="goal">Goal: ${appGoal}</p>` : ''}\n` +
      `      </header>\n` +
      `      <main className="app-main">\n` +
      `        <section className="logs-section">\n` +
      `          <h2>Runtime Logs</h2>\n` +
      `          <div className="logs">\n` +
      `            {logs.length === 0 ? (\n` +
      `              <p className="log-empty">Waiting for layers to load...</p>\n` +
      `            ) : (\n` +
      `              logs.map((log, i) => (\n` +
      `                <p key={i} className="log-line">{log}</p>\n` +
      `              ))\n` +
      `            )}\n` +
      `          </div>\n` +
      `        </section>\n` +
      `        <section className="nodes-section">\n` +
      `          <h2>Node Architecture</h2>\n` +
      `          <div className="nodes-grid">\n` +
      `${nodeList || '  <p>No nodes defined</p>'}\n` +
      `          </div>\n` +
      `        </section>\n` +
      `      </main>\n` +
      `    </div>\n` +
      `  );\n` +
      `}\n\n` +
      `export default App;\n`
    );
  }

