  // ─── Electron Templates ────────────────────────────────────────────

  private electronMainCjs(projectName: string): string {
    return (
      `const { app, BrowserWindow } = require('electron');\n` +
      `const path = require('path');\n` +
      `const fs = require('fs');\n\n` +
      `let mainWindow = null;\n\n` +
      `function createWindow(urlOrPath, isFile) {\n` +
      `  mainWindow = new BrowserWindow({\n` +
      `    width: 1200,\n` +
      `    height: 800,\n` +
      `    title: '${projectName}',\n` +
      `    webPreferences: {\n` +
      `      preload: path.join(__dirname, 'preload.cjs'),\n` +
      `      contextIsolation: true,\n` +
      `      nodeIntegration: false,\n` +
      `    },\n` +
      `  });\n` +
      `  if (isFile) {\n` +
      `    mainWindow.loadFile(urlOrPath);\n` +
      `  } else {\n` +
      `    mainWindow.loadURL(urlOrPath);\n` +
      `  }\n` +
      `  mainWindow.on('closed', () => { mainWindow = null; });\n` +
      `}\n\n` +
      `const distIndex = path.join(__dirname, '..', 'dist', 'index.html');\n` +
      `if (fs.existsSync(distIndex)) {\n` +
      `  // Production: load built files (cross-platform via loadFile)\n` +
      `  createWindow(distIndex, true);\n` +
      `} else {\n` +
      `  // Development: assume Vite dev server is running\n` +
      `  createWindow('http://localhost:5173', false);\n` +
      `}\n\n` +
      `app.on('window-all-closed', () => {\n` +
      `  if (process.platform !== 'darwin') {\n` +
      `    app.quit();\n` +
      `  }\n` +
      `});\n\n` +
      `app.on('activate', () => {\n` +
      `  if (mainWindow === null) {\n` +
      `    const index = path.join(__dirname, '..', 'dist', 'index.html');\n` +
      `    createWindow(index, true);\n` +
      `  }\n` +
      `});\n`
    );
  }

  private electronPreloadCjs(): string {
    return (
      `const { contextBridge } = require('electron');\n\n` +
      `/**\n` +
      ` * Preload script — exposes safe, sanitized APIs to the renderer process.\n` +
      ` * The renderer (React app) can access these via window.electronAPI.\n` +
      ` *\n` +
      ` * Never expose full Node.js APIs (like fs, child_process) here.\n` +
      ` * Always use contextBridge to create narrow, intentional APIs.\n` +
      ` */\n` +
      `contextBridge.exposeInMainWorld('electronAPI', {\n` +
      `  platform: process.platform,\n` +
      `  versions: {\n` +
      `    node: process.versions.node,\n` +
      `    chrome: process.versions.chrome,\n` +
      `    electron: process.versions.electron,\n` +
      `  },\n` +
      `});\n`
    );
  }

  private electronBuilderJson(projectName: string): string {
