  // ─── README ────────────────────────────────────────────────────────

  private readme(config: ScaffoldConfig, type: 'web' | 'electron' | 'python'): string {
    const { projectName, appGoal, appPurpose } = config;

    const setup =
      type === 'electron'
        ? [
            '```bash',
            '# Install dependencies',
            'npm install',
            '',
            '# Run in development mode (opens Electron + Vite hot-reload)',
            'npm run electron:dev',
            '',
            '# Build for production + create desktop installer',
            'npm run electron:build',
            '',
            '# The installer will be in release/',
            '```',
          ].join('\n')
        : type === 'web'
        ? [
            '```bash',
            '# Install dependencies',
            'npm install',
            '',
            '# Start development server',
            'npm run dev',
            '',
            '# Build for production',
            'npm run build',
            '```',
          ].join('\n')
        : [
            '```bash',
            '# (Optional) Create a virtual environment',
            'python3 -m venv venv',
            'source venv/bin/activate',
            '',
            '# Install dependencies',
            'pip install -r requirements.txt',
            '',
            '# Run the application',
            'python3 main.py',
            '```',
          ].join('\n');

    return (
      `# ${projectName}\n\n` +
      `Generated by **Visual AI Code Architect** — an AI-powered code generation platform.\n\n` +
      `---\n\n` +
      `## Overview\n\n` +
      (appGoal ? `**Goal:** ${appGoal}\n\n` : '') +
      (appPurpose ? `**Purpose:** ${appPurpose}\n\n` : '') +
      `This project was generated from a visual node-based architecture.\n` +
      `The code is organized into three layers:\n\n` +
      `| Layer | File | Description |\n` +
      `|---|---|---|\n` +
      `| 1 — Foundation | \`src/foundation.${type === 'web' ? 'ts' : 'py'}\` | Package config, imports, environment setup |\n` +
      `| 2 — Functions | \`src/functions.${type === 'web' ? 'ts' : 'py'}\` | Per-node business logic |\n` +
      `| 3 — Integration | \`src/integration.${type === 'web' ? 'ts' : 'py'}\` | Wiring all nodes together |\n\n` +
      `## Quick Start\n\n` +
      `${setup}\n\n` +
      `## Project Structure\n\n` +
      `\`\`\`\n` +
      `.\n` +
      (type === 'web'
        ? [
            '├── index.html',
            '├── package.json',
            '├── tsconfig.json',
            '├── vite.config.ts',
            '├── src/',
            '│   ├── main.tsx        # Entry point',
            '│   ├── App.tsx         # Main component',
            '│   ├── App.css         # Styles',
            '│   ├── foundation.ts   # Layer 1',
            '│   ├── functions.ts    # Layer 2',
            '│   └── integration.ts  # Layer 3',
            '└── README.md',
          ]
        : [
            '├── main.py            # Entry point',
            '├── requirements.txt   # Dependencies',
            '├── foundation.py      # Layer 1',
            '├── functions.py       # Layer 2',
            '├── integration.py     # Layer 3',
            '└── README.md',
          ]
      ).join('\n') +
      `\`\`\`\n\n` +
      `---\n` +
      `*Generated on ${new Date().toISOString().split('T')[0]}*\n`
    );
  }

  // ─── Utilities ─────────────────────────────────────────────────────

  private sanitizeName(name: string): string {
    return name
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
      || 'untitled-project';
  }
}

