import { Project, LayerResult } from '../types.js';
import { AITranslator } from '../ai/translator.js';
import { SandboxRunner } from '../sandbox/runner.js';
import { learningEngine } from '../knowledge/learningEngine.js';

export class LayerEngine {
  private ai: AITranslator;
  private sandbox: SandboxRunner;

  constructor() {
    this.ai = new AITranslator();
    this.sandbox = new SandboxRunner();
  }

  async generateLayer(
    project: Project,
    layerNum: number
  ): Promise<LayerResult> {
    // console.log(`Generating Layer ${layerNum} for project ${project.name}`);

    let code = '';
    let errors: string[] = [];

    try {
      switch (layerNum) {
        case 1:
          code = await this.ai.generateFoundation(project.name, project.targetOS);
          break;

        case 2:
          code = await this.generateNodeFunctions(project);
          break;

        case 3:
          code = await this.ai.generateIntegration(
            project.nodes,
            project.edges,
            project.targetOS
          );
          break;

        default:
          throw new Error(`Invalid layer number: ${layerNum}`);
      }

      // Run sandbox validation
      const validationResult = await this.sandbox.run(code, project.targetOS);

      if (!validationResult.success) {
        errors = validationResult.errors;
      }

      // Learn from successful generation
      if (code && errors.length === 0) {
        try {
          await learningEngine.learnFromProject(project, code, true);
        } catch (err) {
          console.error('[learning] Error learning from generation:', err);
        }
      }

      return {
        code,
        errors,
        validated: errors.length === 0,
      };
    } catch (error) {
      console.error(`Layer ${layerNum} generation failed:`, error);
      return {
        code: '',
        errors: [error instanceof Error ? error.message : 'Unknown error'],
        validated: false,
      };
    }
  }

  private async generateNodeFunctions(project: Project): Promise<string> {
    const results = await Promise.allSettled(
      project.nodes.map(async (node) => {
        const code = await this.ai.translateNode(node, project.targetOS, 2);
        return this.wrapFunction(node.id, code);
      })
    );

    const functions: string[] = [];
    for (const r of results) {
      if (r.status === 'fulfilled') {
        functions.push(r.value);
      } else {
        const nodeId = (r.reason as any)?.nodeId || 'unknown';
        console.error(`Failed to generate code for node ${nodeId}:`, r.reason);
        functions.push(`// Error generating code for node ${nodeId}`);
      }
    }
    // Learn from the node functions
    const fullCode = functions.join('\n\n');
    if (fullCode) {
      try {
        learningEngine.learnFromProject(project, fullCode, true);
      } catch (err) {
        console.error('[learning] Error learning from node functions:', err);
      }
    }

    return fullCode;
  }

  private wrapFunction(nodeId: string, code: string): string {
    return `// Node: ${nodeId}
async function node_${nodeId}(input) {
${code.split('\n').map(line => '  ' + line).join('\n')}
}`;
  }
}

/**
 * A minimal character-level Venorica implemented from scratch in pure TypeScript.
 * No external ML libraries - just math.
 * Architecture: Embedding -> Venorica (tanh) -> Dense -> Softmax
 */

export interface RNNConfig {
  vocabSize: number;
  hiddenSize: number;
  learningRate: number;
  seqLength: number;
}

export const DEFAULT_RNN_CONFIG: RNNConfig = {
  vocabSize: 100,
  hiddenSize: 128,
  learningRate: 0.01,
  seqLength: 64,
};

/**
 * Vector/Matrix utilities
 */
function matVecMul(mat: number[][], vec: number[]): number[] {
  const result: number[] = new Array(mat.length).fill(0);
  for (let i = 0; i < mat.length; i++) {
    for (let j = 0; j < vec.length; j++) {
      result[i] += mat[i][j] * vec[j];
    }
  }
  return result;
}

function vecAdd(a: number[], b: number[]): number[] {
  return a.map((v, i) => v + (b[i] || 0));
}

function vecScale(vec: number[], scale: number): number[] {
  return vec.map(v => isFinite(v) ? v * scale : 0);
}

function vecCopy(vec: number[]): number[] {
  return [...vec];
}

/** Tanh activation and its derivative */
function tanh(x: number): number {
  if (x > 20) return 1;
  if (x < -20) return -1;
  const e2x = Math.exp(2 * x);
  const result = (e2x - 1) / (e2x + 1);
  return isNaN(result) ? (x > 0 ? 1 : -1) : result;
}

function tanhDeriv(y: number): number {
  return 1 - y * y;
}

/**
 * Softmax function for output probabilities
 */
function softmax(x: number[]): number[] {
  const maxVal = Math.max(...x);
  // Subtract max for numerical stability, clip inputs to prevent exp overflow
  const exps = x.map(v => {
    const diff = v - maxVal;
    if (diff > 50) return Infinity;
    if (diff < -50) return 0;
    return Math.exp(diff);
  });
  const sum = exps.reduce((a, b) => a + b, 0);
  if (sum === Infinity || sum === 0 || isNaN(sum)) {
    // Fallback: uniform distribution
    return x.map(() => 1 / x.length);
  }
  return exps.map(v => v / sum);
}

/** Cross-entropy loss */
function crossEntropy(pred: number[], targetIdx: number): number {
  return -Math.log(Math.max(pred[targetIdx], 1e-10));
}

/** Random number with Gaussian distribution (Box-Muller) */
function randn(): number {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  return Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
}

/**
 * Venorica State - holds all parameters for the model
 */
export class RNNState {
  // Weight matrices
  Wxh: number[][];  // input -> hidden
  Whh: number[][];  // hidden -> hidden
  Why: number[][];  // hidden -> output
  // Bias vectors
  bh: number[];     // hidden bias
  by: number[];     // output bias
  // Gradients
  dWxh: number[][];
  dWhh: number[][];
  dWhy: number[][];
  dbh: number[];
  dby: number[];
  // Optimizer state (AdaGrad)
  mWxh: number[][];
  mWhh: number[][];
  mWhy: number[][];
  mbh: number[];
  mby: number[];
  // Config
  config: RNNConfig;
  // Training stats
  iter: number = 0;
  smoothLoss: number = 0;

  constructor(config: RNNConfig) {
    this.config = { ...config };
    const { vocabSize, hiddenSize } = config;

    // Initialize weights with small random values
    this.Wxh = this.initMat(hiddenSize, vocabSize, 0.01);
    this.Whh = this.initMat(hiddenSize, hiddenSize, 0.01);
    this.Why = this.initMat(vocabSize, hiddenSize, 0.01);
    this.bh = new Array(hiddenSize).fill(0);
    this.by = new Array(vocabSize).fill(0);

    // Initialize gradients
    this.dWxh = this.initMat(hiddenSize, vocabSize, 0);
    this.dWhh = this.initMat(hiddenSize, hiddenSize, 0);
    this.dWhy = this.initMat(vocabSize, hiddenSize, 0);
    this.dbh = new Array(hiddenSize).fill(0);
    this.dby = new Array(vocabSize).fill(0);

    // Initialize AdaGrad memory
    this.mWxh = this.initMat(hiddenSize, vocabSize, 0);
    this.mWhh = this.initMat(hiddenSize, hiddenSize, 0);
    this.mWhy = this.initMat(vocabSize, hiddenSize, 0);
    this.mbh = new Array(hiddenSize).fill(0);
    this.mby = new Array(vocabSize).fill(0);
  }

  initMat(rows: number, cols: number, scale: number): number[][] {
    return Array.from({ length: rows }, () =>
      Array.from({ length: cols }, () => randn() * scale)
    );
  }

  /** Get serializable snapshot for saving */
  toJSON(): any {
    return {
      config: this.config,
      Wxh: this.Wxh,
      Whh: this.Whh,
      Why: this.Why,
      bh: this.bh,
      by: this.by,
      iter: this.iter,
      smoothLoss: this.smoothLoss,
    };
  }

  /** Load from snapshot */
  fromJSON(data: any): void {
    this.config = data.config;
    this.Wxh = data.Wxh;
    this.Whh = data.Whh;
    this.Why = data.Why;
    this.bh = data.bh;
    this.by = data.by;
    this.iter = data.iter || 0;
    this.smoothLoss = data.smoothLoss || 0;

    // Recreate gradient and optimizer buffers
    const { vocabSize, hiddenSize } = this.config;
    this.dWxh = this.initMat(hiddenSize, vocabSize, 0);
    this.dWhh = this.initMat(hiddenSize, hiddenSize, 0);
    this.dWhy = this.initMat(vocabSize, hiddenSize, 0);
    this.dbh = new Array(hiddenSize).fill(0);
    this.dby = new Array(vocabSize).fill(0);
    this.mWxh = this.initMat(hiddenSize, vocabSize, 0);
    this.mWhh = this.initMat(hiddenSize, hiddenSize, 0);
    this.mWhy = this.initMat(vocabSize, hiddenSize, 0);
    this.mbh = new Array(hiddenSize).fill(0);
    this.mby = new Array(vocabSize).fill(0);
  }
}

/**
 * Stores the computation graph for a single time step
 */
class RNNGate {
  hs: number[] = [];    // hidden state output
  xs: number[] = [];    // input one-hot
  raw: number[] = [];   // pre-tanh hidden state
  ps: number[] = [];    // output probabilities
}

/**
 * Forward pass of the Venorica for a sequence of inputs
 */
export function rnnForward(
  model: RNNState,
  inputs: number[],
  hprev: number[]
): { gates: RNNGate[]; loss: number; h: number[] } {
  const { vocabSize, hiddenSize } = model.config;
  const gates: RNNGate[] = [];
  let loss = 0;
  let h = vecCopy(hprev);

  for (let t = 0; t < inputs.length; t++) {
    const gate = new RNNGate();

    // One-hot encode input
    gate.xs = new Array(vocabSize).fill(0);
    gate.xs[inputs[t]] = 1.0;

    // Hidden state: h = tanh(Wxh * x + Whh * h_prev + bh)
    const wxh = matVecMul(model.Wxh, gate.xs);
    const whh = matVecMul(model.Whh, h);
    gate.raw = vecAdd(vecAdd(wxh, whh), model.bh);
    gate.hs = gate.raw.map(v => tanh(v));

    // Output: y = Why * h + by
    const y = vecAdd(matVecMul(model.Why, gate.hs), model.by);

    // Softmax probabilities
    gate.ps = softmax(y);

    // Cross-entropy loss (predict next char)
    if (t + 1 < inputs.length) {
      loss += crossEntropy(gate.ps, inputs[t + 1]);
    }

    gates.push(gate);
    h = gate.hs;
  }

  return { gates, loss, h };
}

/**
 * Backpropagation through time
 */
export function rnnBackward(
  model: RNNState,
  inputs: number[],
  gates: RNNGate[],
  hprev: number[]
): void {
  const { vocabSize, hiddenSize } = model.config;

  // Zero gradients
  model.dWxh = model.initMat(hiddenSize, vocabSize, 0);
  model.dWhh = model.initMat(hiddenSize, hiddenSize, 0);
  model.dWhy = model.initMat(vocabSize, hiddenSize, 0);
  model.dbh = new Array(hiddenSize).fill(0);
  model.dby = new Array(vocabSize).fill(0);

  let dhNext = new Array(hiddenSize).fill(0);

  for (let t = gates.length - 1; t >= 0; t--) {
    const gate = gates[t];
    const targetIdx = t + 1 < inputs.length ? inputs[t + 1] : inputs[inputs.length - 1];

    // Gradient of output: dL/dy = p - target
    const dy = [...gate.ps];
    dy[targetIdx] -= 1.0;

    // dWhy = dy * h^T
    for (let i = 0; i < vocabSize; i++) {
      for (let j = 0; j < hiddenSize; j++) {
        model.dWhy[i][j] += dy[i] * gate.hs[j];
      }
    }

    // dby = dy
    for (let i = 0; i < vocabSize; i++) {
      model.dby[i] += dy[i];
    }

    // dh = Why^T * dy + dhNext
    let dh = new Array(hiddenSize).fill(0);
    for (let i = 0; i < hiddenSize; i++) {
      for (let j = 0; j < vocabSize; j++) {
        dh[i] += model.Why[j][i] * dy[j];
      }
      dh[i] += dhNext[i];
    }

    // Backprop through tanh: dtanh = dh * (1 - h^2)
    const dtanh = dh.map((d, i) => d * tanhDeriv(gate.hs[i]));

    // dWxh = dtanh * x^T
    for (let i = 0; i < hiddenSize; i++) {
      for (let j = 0; j < vocabSize; j++) {
        model.dWxh[i][j] += dtanh[i] * gate.xs[j];
      }
    }

    // dWhh = dtanh * h_{t-1}^T
    const hPrev = t > 0 ? gates[t - 1].hs : hprev;
    for (let i = 0; i < hiddenSize; i++) {
      for (let j = 0; j < hiddenSize; j++) {
        model.dWhh[i][j] += dtanh[i] * hPrev[j];
      }
    }

    // dbh = dtanh
    for (let i = 0; i < hiddenSize; i++) {
      model.dbh[i] += dtanh[i];
    }

    // dhNext = Whh^T * dtanh
    dhNext = new Array(hiddenSize).fill(0);
    for (let i = 0; i < hiddenSize; i++) {
      for (let j = 0; j < hiddenSize; j++) {
        dhNext[i] += model.Whh[j][i] * dtanh[j];
      }
    }
  }
}

/**
 * Update weights using AdaGrad
 */
export function rnnUpdate(model: RNNState): void {
  const lr = model.config.learningRate;
  const eps = 1e-8;

  function updateWeight(mat: number[][], grad: number[][], mem: number[][]) {
    for (let i = 0; i < mat.length; i++) {
      for (let j = 0; j < mat[0].length; j++) {
        mem[i][j] += grad[i][j] * grad[i][j];
        mat[i][j] -= lr * grad[i][j] / (Math.sqrt(mem[i][j]) + eps);
      }
    }
  }

  function updateBias(vec: number[], grad: number[], mem: number[]) {
    for (let i = 0; i < vec.length; i++) {
      mem[i] += grad[i] * grad[i];
      vec[i] -= lr * grad[i] / (Math.sqrt(mem[i]) + eps);
    }
  }

  updateWeight(model.Wxh, model.dWxh, model.mWxh);
  updateWeight(model.Whh, model.dWhh, model.mWhh);
  updateWeight(model.Why, model.dWhy, model.mWhy);
  updateBias(model.bh, model.dbh, model.mbh);
  updateBias(model.by, model.dby, model.mby);
}

/**
 * Train the Venorica on a single batch of data
 */
export function rnnTrainStep(
  model: RNNState,
  inputs: number[],
  hprev: number[]
): { loss: number; h: number[] } {
  // Forward pass
  const { gates, loss, h } = rnnForward(model, inputs, hprev);

  // Backward pass
  rnnBackward(model, inputs, gates, hprev);

  // Clip gradients to prevent explosion
  clipGradients(model, 5.0);

  // Update weights
  rnnUpdate(model);

  return { loss, h };
}

function clipGradients(model: RNNState, maxNorm: number): void {
  let totalNorm = 0;

  function addGradNorm(mat: number[][]) {
    for (const row of mat) {
      for (const g of row) {
        if (isFinite(g)) totalNorm += g * g;
      }
    }
  }

  // Also include bias gradients in norm computation
  for (const g of model.dbh) if (isFinite(g)) totalNorm += g * g;
  for (const g of model.dby) if (isFinite(g)) totalNorm += g * g;

  addGradNorm(model.dWxh);
  addGradNorm(model.dWhh);
  addGradNorm(model.dWhy);

  totalNorm = Math.sqrt(totalNorm);

  // Check for NaN/Inf in totalNorm
  if (!isFinite(totalNorm) || totalNorm === 0) {
    // Reset all gradients to prevent NaN propagation
    const { vocabSize, hiddenSize } = model.config;
    model.dWxh = model.initMat(hiddenSize, vocabSize, 0);
    model.dWhh = model.initMat(hiddenSize, hiddenSize, 0);
    model.dWhy = model.initMat(vocabSize, hiddenSize, 0);
    model.dbh = new Array(hiddenSize).fill(0);
    model.dby = new Array(vocabSize).fill(0);
    return;
  }

  if (totalNorm > maxNorm) {
    const scale = maxNorm / totalNorm;
    function scaleGrad(mat: number[][]) {
      for (let i = 0; i < mat.length; i++) {
        for (let j = 0; j < mat[0].length; j++) {
          if (isFinite(mat[i][j])) mat[i][j] *= scale;
        }
      }
    }
    scaleGrad(model.dWxh);
    scaleGrad(model.dWhh);
    scaleGrad(model.dWhy);
    model.dbh = vecScale(model.dbh, scale);
    model.dby = vecScale(model.dby, scale);
  }
}

/**
 * Generate text from the RNN
 */
export function rnnGenerate(
  model: RNNState,
  seedChar: number,
  length: number,
  temperature: number = 0.8
): { text: number[]; states: number[][] } {
  const { vocabSize, hiddenSize } = model.config;
  let h = new Array(hiddenSize).fill(0);
  let x = new Array(vocabSize).fill(0);
  x[seedChar] = 1.0;

  const output: number[] = [seedChar];
  const states: number[][] = [h];

  for (let t = 0; t < length - 1; t++) {
    // Forward pass one step
    const wxh = matVecMul(model.Wxh, x);
    const whh = matVecMul(model.Whh, h);
    const raw = vecAdd(vecAdd(wxh, whh), model.bh);
    h = raw.map(v => tanh(v));

    const y = vecAdd(matVecMul(model.Why, h), model.by);

    // Apply temperature
    const adjustedY = y.map(v => v / temperature);
    const ps = softmax(adjustedY);

    // Sample from the distribution
    const idx = sampleFromDistribution(ps);

    output.push(idx);
    states.push(h);

    // Set next input
    x = new Array(vocabSize).fill(0);
    x[idx] = 1.0;
  }

  return { text: output, states };
}

function sampleFromDistribution(probs: number[]): number {
  const r = Math.random();
  let cumulative = 0;
  for (let i = 0; i < probs.length; i++) {
    cumulative += probs[i];
    if (r < cumulative) return i;
  }
  return probs.length - 1;
}

/**
 * Initialize hidden state (zeros)
 */
export function initHiddenState(model: RNNState): number[] {
  return new Array(model.config.hiddenSize).fill(0);
}

/**
 * Save model to JSON string
 */
export function saveModel(model: RNNState): string {
  return JSON.stringify(model.toJSON());
}

/**
 * Load model from JSON string
 */
export function loadModel(json: string, config?: RNNConfig): RNNState {
  const data = JSON.parse(json);
  const cfg = config || data.config || DEFAULT_RNN_CONFIG;
  const model = new RNNState(cfg);
  model.fromJSON(data);
  return model;
}

/**
 * Venorica -- Sync Manager
 * Tracks the total size of Venorica's training data and automatically
 * exports patterns as JSONL to the LLM Training Studio
 * when the 50MB threshold is exceeded.
 */

import { existsSync, writeFileSync, mkdirSync, readdirSync, statSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { knowledgeStore } from '../knowledge/knowledgeStore.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

const KNOWLEDGE_DIR = join(__dirname, '..', '..', 'knowledge');
const TRAINING_STUDIO_DIR = join(__dirname, '..', '..', '..', 'llm-training-app', 'data', 'uploads');

/** Default threshold: 50 MB */
const DEFAULT_THRESHOLD_BYTES = 50 * 1024 * 1024;

export interface SyncStatus {
  /** Current training sheet number */
  currentSheet: number;
  /** Max patterns per sheet before archive */
  sheetCap: number;
  totalBytes: number;
  totalSize: string;
  thresholdReached: boolean;
  thresholdPercent: string;
  patternCount: number;
  lastSyncTimestamp: string | null;
  lastSyncResult: string | null;
}

let syncState: {
  lastSyncTimestamp: string | null;
  lastSyncResult: string | null;
  lastPatternCount: number;
} = {
  lastSyncTimestamp: null,
  lastSyncResult: null,
  lastPatternCount: 0,
};

function formatBytes(bytes: number): string {
  if (bytes === 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  const val = bytes / Math.pow(1024, i);
  return `${val.toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}

export function getKnowledgeDirSize(): { bytes: number; human: string } {
  try {
    if (!existsSync(KNOWLEDGE_DIR)) {
      return { bytes: 0, human: '0 B' };
    }
    const entries = readdirSync(KNOWLEDGE_DIR);
    let totalBytes = 0;
    for (const entry of entries) {
      try {
        const stats = statSync(join(KNOWLEDGE_DIR, entry));
        if (stats.isFile()) totalBytes += stats.size;
      } catch { /* skip unreadable */ }
    }
    return { bytes: totalBytes, human: formatBytes(totalBytes) };
  } catch (e) {
    console.warn('[Venorica Sync] Failed to calculate knowledge dir size:', e);
    return { bytes: 0, human: '0 B' };
  }
}

function ensureStudioDir(): boolean {
  try {
    if (!existsSync(TRAINING_STUDIO_DIR)) {
      mkdirSync(TRAINING_STUDIO_DIR, { recursive: true });
    }
    return true;
  } catch (e) {
    console.warn('[Venorica Sync] Cannot create Training Studio directory:', e);
    return false;
  }
}

function exportToStudio(): string | null {
  try {
    if (!ensureStudioDir()) return null;
    const allPatterns = knowledgeStore.getAll();
    if (allPatterns.length === 0) return null;
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const filename = `venorica-sync-${timestamp}.jsonl`;
    const exportPath = join(TRAINING_STUDIO_DIR, filename);
    // Generate JSONL using PatternEntry properties
    const lines = allPatterns.map(function(p) {
      return JSON.stringify({
        text: p.code,
        title: p.title,
        language: p.language,
        nodeType: p.nodeType,
        tags: p.tags,
        source: 'venorica',
        timestamp: p.createdAt,
      });
    });
    writeFileSync(exportPath, lines.join('\n'), 'utf-8');
    console.log(`[Venorica Sync] Exported ${allPatterns.length} patterns to ${exportPath}`);
    return exportPath;
  } catch (e) {
    console.error('[Venorica Sync] Export failed:', e);
    return null;
  }
}

export function checkAndSync(thresholdBytes: number = DEFAULT_THRESHOLD_BYTES): SyncStatus {
  const { bytes, human } = getKnowledgeDirSize();
  const patternCount = knowledgeStore.count();
  const thresholdReached = bytes >= thresholdBytes;
  const pct = bytes > 0 ? ((bytes / thresholdBytes) * 100).toFixed(1) : '0.0';
  const result: SyncStatus = {
    totalBytes: bytes,
    totalSize: human,
    thresholdReached,
    thresholdPercent: pct,
    patternCount,
    currentSheet: knowledgeStore.getCurrentSheet(),
    sheetCap: 100,
    lastSyncTimestamp: syncState.lastSyncTimestamp,
    lastSyncResult: syncState.lastSyncResult,
  };
  if (thresholdReached) {
    const hasNewData = patternCount !== syncState.lastPatternCount;
    const hasNotExportedYet = !syncState.lastSyncTimestamp;
    if (hasNewData || hasNotExportedYet) {
      const exportPath = exportToStudio();
      if (exportPath) {
        const now = new Date().toISOString();
        syncState.lastSyncTimestamp = now;
        syncState.lastSyncResult = 'synced';
        syncState.lastPatternCount = patternCount;
        result.lastSyncTimestamp = now;
        result.lastSyncResult = 'synced';
        console.log(`[Venorica Sync] Auto-synced ${human} of training data to LLM Training Studio`);
      } else {
        syncState.lastSyncResult = 'export-failed';
        result.lastSyncResult = 'export-failed';
      }
    } else {
      result.lastSyncResult = 'up-to-date';
    }
  } else {
    console.log(`[Venorica Sync] Training data at ${human} (${pct}% of 50 MB threshold)`);
  }
  return result;
}

export function forceSync(): { success: boolean; path: string | null; message: string } {
  const { bytes, human } = getKnowledgeDirSize();
  const exportPath = exportToStudio();
  if (exportPath) {
    const now = new Date().toISOString();
    syncState.lastSyncTimestamp = now;
    syncState.lastSyncResult = 'synced';
    syncState.lastPatternCount = knowledgeStore.count();
    return { success: true, path: exportPath, message: `Exported ${human} of training data to LLM Training Studio` };
  }
  return { success: false, path: null, message: 'Export failed -- check console for details' };
}

export function getSyncStatus(): SyncStatus {
  const { bytes, human } = getKnowledgeDirSize();
  const patternCount = knowledgeStore.count();
  const pct = bytes > 0 ? ((bytes / DEFAULT_THRESHOLD_BYTES) * 100).toFixed(1) : '0.0';
  return {
    totalBytes: bytes,
    totalSize: human,
    thresholdReached: bytes >= DEFAULT_THRESHOLD_BYTES,
    thresholdPercent: pct,
    patternCount,
    currentSheet: knowledgeStore.getCurrentSheet(),
    sheetCap: 100,
    lastSyncTimestamp: syncState.lastSyncTimestamp,
    lastSyncResult: syncState.lastSyncResult,
  };
}

/**
 * Character-level tokenizer for the tiny RNN.
 * Converts code text into sequences of character indices.
 */

export class CharTokenizer {
  private charToIdx: Map<string, number> = new Map();
  private idxToChar: Map<number, string> = new Map();
  private _vocabSize: number = 0;

  constructor() {
    // Initialize with basic ASCII printable characters
    const chars = '\n !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[]^_`abcdefghijklmnopqrstuvwxyz{|}~\t\r';
    for (const c of chars) {
      if (!this.charToIdx.has(c)) {
        const idx = this._vocabSize;
        this.charToIdx.set(c, idx);
        this.idxToChar.set(idx, c);
        this._vocabSize++;
      }
    }
  }

  /** Build vocabulary from training text */
  fit(texts: string[]): void {
    for (const text of texts) {
      for (const c of text) {
        if (!this.charToIdx.has(c)) {
          const idx = this._vocabSize;
          this.charToIdx.set(c, idx);
          this.idxToChar.set(idx, c);
          this._vocabSize++;
        }
      }
    }
  }

  /** Encode text to sequence of indices */
  encode(text: string): number[] {
    const indices: number[] = [];
    for (const c of text) {
      if (this.charToIdx.has(c)) {
        indices.push(this.charToIdx.get(c)!);
      } else {
        // Unknown char - use space as fallback
        indices.push(this.charToIdx.get(' ') || 0);
      }
    }
    return indices;
  }

  /** Decode indices back to text */
  decode(indices: number[]): string {
    return indices.map(i => this.idxToChar.get(i) || '?').join('');
  }

  /** One-hot encode a single index */
  oneHot(index: number): number[] {
    const vec = new Array(this._vocabSize).fill(0);
    vec[index] = 1.0;
    return vec;
  }

  get vocabSize(): number {
    return this._vocabSize;
  }

  /** Number of chars (for display) */
  get vocabChars(): number {
    return this._vocabSize;
  }
}

export const defaultTokenizer = new CharTokenizer();

import { RNNState, RNNConfig, DEFAULT_RNN_CONFIG, rnnTrainStep, 
        rnnGenerate, initHiddenState, saveModel, loadModel } from './rnn.js';
import { CharTokenizer } from './tokenizer.js';
import { knowledgeStore } from '../knowledge/knowledgeStore.js';
import { checkAndSync as syncCheck } from './syncManager.js';
import * as fs from 'fs';
import { gzipSync, gunzipSync } from 'zlib';
import * as path from 'path';

const MODEL_PATH = path.join(process.cwd(), 'knowledge', 'rnn-model.json');

export class RNNTrainingEngine {
  model: RNNState | null = null;
  tokenizer: CharTokenizer = new CharTokenizer();
  config: RNNConfig;
  trainedChars: number = 0;
  isTraining: boolean = false;

  constructor(config?: Partial<RNNConfig>) {
    this.config = { ...DEFAULT_RNN_CONFIG, ...config };
    if (!this.loadModel()) {
      console.log('[Venorica] No saved model found, initializing blank model...');
      this.initModel();
    }
  }

  /** Initialize a fresh model */
  initModel(): void {
    const patterns = knowledgeStore.getAll();
    const codeTexts = patterns.map(p => p.code);

    // Fit tokenizer on existing patterns
    this.tokenizer.fit(codeTexts);

    // Update config with actual vocab size
    this.config.vocabSize = this.tokenizer.vocabSize;
    this.model = new RNNState(this.config);
    console.log(`[Venorica] Initialized model: vocab=${this.config.vocabSize}, hidden=${this.config.hiddenSize}`);
  }

  /** Train on all patterns in the knowledge store */
  async train(iterations: number = 500): Promise<{ loss: number; chars: number }> {
    const patterns = knowledgeStore.getAll();
    if (patterns.length === 0) {
      throw new Error('No patterns to train on');
    }

    const codeTexts = patterns.map(p => p.code);

    // Fit tokenizer to learn any new characters
    this.tokenizer.fit(codeTexts);
    const newVocabSize = this.tokenizer.vocabSize;

    // CRITICAL: If vocab size changed, the model weight matrices have wrong dimensions.
    // Must reinitialize the model with the correct vocab size.
    if (this.model && this.config.vocabSize !== newVocabSize) {
      console.log(`[Venorica] Vocab changed ${this.config.vocabSize} -> ${newVocabSize}, reinitializing model`);
      this.config.vocabSize = newVocabSize;
      this.model = new RNNState(this.config);
    } else {
      this.config.vocabSize = newVocabSize;
    }

    // Initialize model if needed
    if (!this.model) {
      this.model = new RNNState(this.config);
    }

    // Prepare training data: concatenate all code
    const allCode = codeTexts.join('\n---\n');
    const indices = this.tokenizer.encode(allCode);

    console.log(`[Venorica] Training on ${indices.length} characters from ${patterns.length} patterns`);

    this.isTraining = true;
    const seqLen = this.config.seqLength;
    let smoothLoss = 0;
    let charCount = 0;

    for (let i = 0; i < iterations; i++) {
      // Yield to event loop periodically to avoid blocking
      if (i % 50 === 0 && i > 0) {
        await new Promise(resolve => setImmediate(resolve));
      }

      // Get a random subsequence
      const startIdx = Math.floor(Math.random() * Math.max(1, indices.length - seqLen - 1));
      const inputs = indices.slice(startIdx, startIdx + seqLen);

      if (inputs.length < 2) continue;

      const hprev = initHiddenState(this.model);
      const result = rnnTrainStep(this.model!, inputs, hprev);

      // Sanity check: abort if loss is NaN
      if (isNaN(result.loss)) {
        console.log(`[Venorica] NaN detected at iter ${i}, aborting training and resetting model`);
        this.isTraining = false;
        this.initModel();
        throw new Error('NaN loss detected - model reset to initial state');
      }

      // Smooth the loss for monitoring
      if (i === 0) smoothLoss = result.loss;
      smoothLoss = smoothLoss * 0.999 + result.loss * 0.001;

      charCount += inputs.length;

      if (i % 100 === 0) {
        console.log(`[Venorica] Iter ${i}/${iterations}, loss: ${smoothLoss.toFixed(4)}`);
      }
    }

    this.trainedChars += charCount;
    this.model.smoothLoss = smoothLoss;
    this.model.iter += iterations;

    // Save model
    this.saveModel();

    this.isTraining = false;
    console.log(`[Venorica] Training complete. Loss: ${smoothLoss.toFixed(4)}, Chars: ${charCount}`);

    return { loss: smoothLoss, chars: charCount };
  }

  /** Generate code from the trained model */
  generate(seedText: string = 'function', length: number = 200, temperature: number = 0.8): string {
    if (!this.model) {
      throw new Error('Model not trained yet');
    }

    const seedIndices = this.tokenizer.encode(seedText);
    if (seedIndices.length === 0) {
      throw new Error('Could not encode seed text');
    }

    const result = rnnGenerate(this.model, seedIndices[0], length, temperature);
    return this.tokenizer.decode(result.text);
  }

  /** Get model status */
  getStatus(): any {
    if (!this.model) {
      return {
        initialized: false,
        vocabSize: this.tokenizer.vocabSize,
        hiddenSize: this.config.hiddenSize,
        trainedChars: this.trainedChars,
        iterations: 0,
        loss: null,
        patternCount: knowledgeStore.count(),
        isTraining: this.isTraining,
      };
    }
    return {
      initialized: true,
      vocabSize: this.config.vocabSize,
      hiddenSize: this.config.hiddenSize,
      trainedChars: this.trainedChars,
      iterations: this.model.iter,
      loss: this.model.smoothLoss,
      patternCount: knowledgeStore.count(),
      isTraining: this.isTraining,
      learningRate: this.config.learningRate,
      seqLength: this.config.seqLength,
    };
  }

  /** Save model to disk */
  saveModel(): void {
    if (!this.model) return;
    try {
      const dir = path.dirname(MODEL_PATH);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      const data = {
        model: this.model.toJSON(),
        config: this.config,
        trainedChars: this.trainedChars,
        tokenizerVocabSize: this.tokenizer.vocabSize,
        savedAt: new Date().toISOString(),
      };
      const jsonStr = JSON.stringify(data);
      fs.writeFileSync(MODEL_PATH, gzipSync(Buffer.from(jsonStr, 'utf-8')));
      console.log(`[Venorica] Model saved to ${MODEL_PATH}`);
    } catch (err) {
      console.error('[Venorica] Error saving model:', err);
    }
  }

  /** Load model from disk */
  loadModel(): boolean {
    try {
      if (!fs.existsSync(MODEL_PATH)) return false;
      const raw = fs.readFileSync(MODEL_PATH);
      let data: any;
      try {
        data = JSON.parse(gunzipSync(raw).toString('utf-8'));
      } catch {
        data = JSON.parse(raw.toString('utf-8'));
      }
      this.config = data.config || this.config;
      // Keep the saved vocabSize — this is critical for the model dimensions.
      // The tokenizer will be re-fit later when training happens.
      this.model = new RNNState(this.config);
      this.model.fromJSON(data.model);
      this.trainedChars = data.trainedChars || 0;
      console.log(`[Venorica] Model loaded from ${MODEL_PATH}`);
      return true;
    } catch (err) {
      console.error('[Venorica] Error loading model:', err);
      return false;
    }
  }

  /** Learn from all patterns in the knowledge store */
  async learnFromKnowledge(iterations: number = 200): Promise<{ loss: number; chars: number }> {
    if (!this.model) {
      console.log('[Venorica] No model, initializing...');
      this.initModel();
    }

    if (knowledgeStore.count() === 0) {
      console.log('[Venorica] No patterns to learn from');
      return { loss: 0, chars: 0 };
    }

    // Don't start training if already training
    if (this.isTraining) {
      console.log('[Venorica] Already training, skipping request');
      return { loss: 0, chars: 0 };
    }

    return this.train(iterations);
  }
}

