import { Router } from 'express';
import { projects } from '../db/projects.js';
import { LayerEngine } from '../layers/layerEngine.js';
import { ProjectScaffolder, ScaffoldConfig } from '../export/scaffolder.js';

export const exportRoutes = Router();
const layerEngine = new LayerEngine();
const scaffolder = new ProjectScaffolder();

/**
 * POST /api/export/:projectId/scaffold
 *
 * Generate all 3 layers of code for a project, then scaffold
 * a complete standalone project directory.
 *
 * Response includes:
 *   - outputPath: absolute path to the generated project
 *   - files: list of created files
 *   - layers: preview of each generated layer
 */
exportRoutes.post('/:projectId/scaffold', async (req, res) => {
  try {
    const { projectId } = req.params;
    const project = projects.getById(projectId);

    if (!project) {
      return res.status(404).json({ error: 'Project not found' });
    }

    // Generate all 3 layers of code
    const results: { layer: number; code: string; errors: string[] }[] = [];
    for (let layer = 1; layer <= 3; layer++) {
      const result = await layerEngine.generateLayer(project, layer);
      results.push({
        layer,
        code: result.code,
        errors: result.errors,
      });
    }

    // Ensure we have all 3 layers (use empty strings if generation failed)
    const layers = {
      foundation: results[0]?.code || '// Foundation generation failed',
      functions: results[1]?.code || '// Functions generation failed',
      integration: results[2]?.code || '// Integration generation failed',
    };

    // Find goal/purpose from the master node
    const masterNode = project.nodes.find((n) => n.type === 'master');
    const appGoal = masterNode?.data?.appGoal || '';
    const appPurpose = masterNode?.data?.appPurpose || '';

    // Read optional desktopTarget from request body
    const desktopTarget = req.body.desktopTarget || 'none';

    // Scaffold the project
    const scaffoldConfig: ScaffoldConfig = {
      projectName: project.name,
      targetOS: project.targetOS,
      layers,
      nodes: project.nodes as any,
      edges: project.edges as any,
      appGoal,
      appPurpose,
      desktopTarget: desktopTarget === 'electron' ? 'electron' : 'none',
    };

    const result = await scaffolder.scaffold(scaffoldConfig);

    res.json({
      success: result.success,
      outputPath: result.outputPath,
      files: result.files,
      message: result.message,
      layers: results.map((r) => ({
        layer: r.layer,
        length: r.code.length,
        errors: r.errors.length > 0 ? r.errors : undefined,
      })),
    });
  } catch (error) {
    console.error('Scaffold failed:', error);
    res.status(500).json({
      error: error instanceof Error ? error.message : 'Scaffold failed',
    });
  }
});

