/**
 * Codebuff Training Data Pipeline
 * 
 * Captures code changes, conversations, and generated code as structured
 * training data that feeds into:
 *   1. The Venorica RNN knowledge store (for pattern-based learning)
 *   2. The LLM Training Studio upload directory (for LLM fine-tuning data)
 * 
 * This makes every codebuff interaction contribute to the system's
 * ongoing learning, creating a virtuous feedback loop.
 * 
 * Usage:
 *   npx tsx backend/src/scripts/capture-training-data.ts
 *   npx tsx backend/src/scripts/capture-training-data.ts --watch  (file watcher mode)
 *   npx tsx backend/src/scripts/capture-training-data.ts --from-git  (capture uncommitted changes)
 */

import * as fs from 'fs';
import * as path from 'path';
import { execSync } from 'child_process';

const PROJECT_ROOT = path.resolve(process.cwd());

// ─── Configuration ──────────────────────────────────────────────────────────

const TRAINING_STUDIO_DIR = path.join(PROJECT_ROOT, 'llm-training-app', 'data', 'uploads');
const KNOWLEDGE_DIR = path.join(PROJECT_ROOT, 'knowledge');
const CAPTURE_LOG = path.join(PROJECT_ROOT, 'knowledge', 'capture-log.jsonl');

interface TrainingRecord {
  text: string;
  source: 'codebuff-codechange' | 'codebuff-conversation' | 'codebuff-generation' | 'codebuff-system';
  title: string;
  language: string;
  tags: string[];
  nodeType: string;
  filePath: string;
  timestamp: string;
  sessionId: string;
  metadata: Record<string, string>;
}

// ─── Git-based change capture ──────────────────────────────────────────────

function getGitDiff(): { filePath: string; content: string; status: string }[] {
  try {
    const stdout = execSync('git diff --cached --name-status', { cwd: PROJECT_ROOT, encoding: 'utf-8', timeout: 5000 });
    if (!stdout.trim()) return [];

    const changedFiles: { filePath: string; content: string; status: string }[] = [];
    const lines = stdout.trim().split('\n');

    for (const line of lines) {
      const [status, ...fileParts] = line.trim().split('\t');
      const filePath = fileParts.join('\t');
      if (!filePath) continue;

      // Skip binary, large, and node_modules files
      const ext = path.extname(filePath).toLowerCase();
      if (!['.ts', '.tsx', '.js', '.jsx', '.py', '.css', '.html', '.json', '.md', '.yml', '.yaml'].includes(ext)) continue;
      if (filePath.includes('node_modules') || filePath.includes('dist')) continue;

      try {
        const content = execSync(`git diff --cached "${filePath}"`, { cwd: PROJECT_ROOT, encoding: 'utf-8', timeout: 5000 });
        if (content.length > 20 && content.length < 50000) {
          changedFiles.push({ filePath, content, status });
        }
      } catch {
        // skip files that can't be diffed
      }
    }
    return changedFiles;
  } catch {
    return [];
  }
}

function getUncommittedChanges(): { filePath: string; content: string; status: string }[] {
  try {
    const stdout = execSync('git diff --name-status', { cwd: PROJECT_ROOT, encoding: 'utf-8', timeout: 5000 });
    if (!stdout.trim()) return [];

    const changedFiles: { filePath: string; content: string; status: string }[] = [];
    const lines = stdout.trim().split('\n');

    for (const line of lines) {
      const [status, ...fileParts] = line.trim().split('\t');
      const filePath = fileParts.join('\t');
      if (!filePath) continue;

      const ext = path.extname(filePath).toLowerCase();
      if (!['.ts', '.tsx', '.js', '.jsx', '.py', '.css', '.html', '.json', '.md', '.yml', '.yaml'].includes(ext)) continue;
      if (filePath.includes('node_modules') || filePath.includes('dist') || filePath.includes('exports')) continue;

      try {
        const content = execSync(`git diff "${filePath}"`, { cwd: PROJECT_ROOT, encoding: 'utf-8', timeout: 5000 });
        if (content.length > 20 && content.length < 100000) {
          changedFiles.push({ filePath, content, status });
        }
      } catch {
        // skip
      }
    }
    return changedFiles;
  } catch {
    return [];
  }
}

function detectLanguage(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  const langMap: Record<string, string> = {
    '.ts': 'typescript', '.tsx': 'typescript', '.js': 'javascript', '.jsx': 'javascript',
    '.py': 'python', '.css': 'css', '.html': 'html', '.json': 'json',
    '.md': 'markdown', '.yml': 'yaml', '.yaml': 'yaml',
  };
  return langMap[ext] || 'unknown';
}

function extractTagsFromDiff(diff: string, filePath: string): string[] {
  const tags: string[] = [detectLanguage(filePath)];

  // Detect patterns in the diff
  if (diff.includes('function ') || diff.includes('async ')) tags.push('function-def');
  if (diff.includes('class ')) tags.push('class-def');
  if (diff.includes('interface ')) tags.push('interface');
  if (diff.includes('import ') || diff.includes('require(')) tags.push('import');
  if (diff.includes('export ')) tags.push('export');
  if (diff.includes('try ') || diff.includes('catch ')) tags.push('error-handling');
  if (diff.includes('const ') || diff.includes('let ')) tags.push('variable');
  if (diff.includes('async ') || diff.includes('await ')) tags.push('async');
  if (diff.includes('type ')) tags.push('type-def');
  if (diff.includes('=>')) tags.push('arrow-function');

  // Extract component/framework hints
  if (diff.includes('React') || diff.includes('useState') || diff.includes('useEffect')) tags.push('react');
  if (diff.includes('Express') || diff.includes('Router')) tags.push('express');
  if (diff.includes('@') && filePath.endsWith('.ts')) tags.push('decorator');

  return tags;
}

function extractCodeFromDiff(diff: string): string {
  // Remove diff metadata (---/+++ lines and @@ hunk headers) and extract added/modified lines
  const lines = diff.split('\n');
  const codeLines: string[] = [];
  let inHunk = false;

  for (const line of lines) {
    if (line.startsWith('diff --git') || line.startsWith('index ') || line.startsWith('---') || line.startsWith('+++')) {
      continue;
    }
    if (line.startsWith('@@')) {
      inHunk = true;
      continue;
    }
    if (inHunk) {
      if (line.startsWith('+')) {
        codeLines.push(line.substring(1));
      } else if (line.startsWith(' ')) {
        codeLines.push(line.substring(1));
      }
      // Skip removed lines (start with -)
    }
  }

  return codeLines.join('\n').trim();
}

// ─── Direct file capture ─────────────────────────────────────────────────

function captureFileContent(filePath: string): string | null {
  try {
    const fullPath = path.join(PROJECT_ROOT, filePath);
    if (!fs.existsSync(fullPath)) return null;
    const content = fs.readFileSync(fullPath, 'utf-8');
    if (content.length < 20 || content.length > 100000) return null;
    return content;
  } catch {
    return null;
  }
}

// ─── Export to Training Studio ───────────────────────────────────────────

function ensureDir(dir: string): void {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
}

function exportToTrainingStudio(records: TrainingRecord[]): number {
  if (records.length === 0) return 0;

  ensureDir(TRAINING_STUDIO_DIR);
  ensureDir(KNOWLEDGE_DIR);

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const filename = `codebuff-capture-${timestamp}.jsonl`;
  const exportPath = path.join(TRAINING_STUDIO_DIR, filename);

  // Write as JSONL — each line is one training example
  const lines = records.map(r => JSON.stringify({
    text: r.text,
    source: r.source,
    title: r.title,
    language: r.language,
    tags: r.tags,
    nodeType: r.nodeType,
    filePath: r.filePath,
    timestamp: r.timestamp,
    sessionId: r.sessionId,
    metadata: r.metadata,
    // Add instruction-response format for LLM fine-tuning
    instruction: `Generate ${r.language} code for: ${r.title}`,
    response: r.text,
  }));

  fs.writeFileSync(exportPath, lines.join('\n') + '\n', 'utf-8');
  console.log(`[capture] Exported ${records.length} training records to ${exportPath}`);

  // Append to master capture log
  const logLines = records.map(r => JSON.stringify({
    ...r,
    _exportedTo: filename,
    _exportedAt: new Date().toISOString(),
  }));
  fs.appendFileSync(CAPTURE_LOG, logLines.join('\n') + '\n', 'utf-8');

  return records.length;
}

// ─── Add to Knowledge Store ──────────────────────────────────────────────

async function addToKnowledgeStore(records: TrainingRecord[]): Promise<number> {
  if (records.length === 0) return 0;

  try {
    const { knowledgeStore } = await import('../knowledge/knowledgeStore.js');

    let addedCount = 0;
    for (const record of records) {
      try {
        knowledgeStore.addPattern({
          category: 'code_pattern',
          title: record.title,
          code: record.text,
          description: `Codebuff ${record.source} — ${record.filePath}. Language: ${record.language}`,
          tags: record.tags,
          projectId: 'codebuff-capture',
          targetOS: 'linux',
          nodeType: 'source-file',
          language: record.language,
          success: true,
          qualityScore: 6.0,
        });
        addedCount++;
      } catch {
        // skip
      }
    }

    return addedCount;
  } catch (err: any) {
    console.error(`[capture] Failed to add to knowledge store: ${err.message}`);
    return 0;
  }
}

// ─── Main capture orchestration ──────────────────────────────────────────

let sessionId = `cb_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;

async function captureFromGitChanges(): Promise<{ records: TrainingRecord[]; exported: number; stored: number }> {
  const changes = getUncommittedChanges();

  if (changes.length === 0) {
    console.log('[capture] No uncommitted changes found.');
    return { records: [], exported: 0, stored: 0 };
  }

  console.log(`[capture] Found ${changes.length} changed files.`);

  const records: TrainingRecord[] = [];
  const timestamp = new Date().toISOString();

  for (const change of changes) {
    const code = extractCodeFromDiff(change.content);
    if (!code || code.length < 30) continue;

    const language = detectLanguage(change.filePath);
    const tags = extractTagsFromDiff(change.content, change.filePath);
    const fileName = path.basename(change.filePath);
    const fileDir = path.dirname(change.filePath);

    records.push({
      text: code,
      source: 'codebuff-codechange',
      title: `${fileName} — ${change.status === 'A' ? 'New' : 'Modified'}`,
      language,
      tags: [...new Set(tags)],
      nodeType: 'source-file',
      filePath: change.filePath,
      timestamp,
      sessionId,
      metadata: {
        status: change.status,
        directory: fileDir,
        changeType: change.status === 'A' ? 'creation' : 'modification',
      },
    });
  }

  // Export to training studio
  const exported = exportToTrainingStudio(records);

  // Also add to knowledge store
  const stored = await addToKnowledgeStore(records);

  console.log(`[capture] Done: ${records.length} records captured, ${exported} exported, ${stored} stored`);

  return { records, exported, stored };
}

// ─── Capture from specific file patterns ─────────────────────────────────

async function captureFromDirectory(dir: string, pattern?: RegExp): Promise<number> {
  const fullDir = path.join(PROJECT_ROOT, dir);
  if (!fs.existsSync(fullDir)) {
    console.error(`[capture] Directory not found: ${fullDir}`);
    return 0;
  }

  const records: TrainingRecord[] = [];
  const timestamp = new Date().toISOString();

  function walk(currentDir: string) {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(currentDir, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      const relativePath = path.relative(PROJECT_ROOT, fullPath);

      if (entry.isDirectory()) {
        if (entry.name === 'node_modules' || entry.name === 'dist' || entry.name === '.git' || entry.name === 'exports') continue;
        walk(fullPath);
        continue;
      }

      const ext = path.extname(entry.name).toLowerCase();
      if (!['.ts', '.tsx', '.js', '.py', '.css', '.html', '.json', '.md'].includes(ext)) continue;
      if (pattern && !pattern.test(relativePath)) continue;

      const content = captureFileContent(relativePath);
      if (!content) continue;

      const language = detectLanguage(relativePath);
      const tags = [language, 'codebuff-work', 'source-file'];

      records.push({
        text: content,
        source: 'codebuff-system',
        title: `${entry.name} — Source File`,
        language,
        tags,
        nodeType: 'source-file',
        filePath: relativePath,
        timestamp,
        sessionId,
        metadata: {
          directory: path.dirname(relativePath),
          size: String(content.length),
        },
      });
    }
  }

  walk(fullDir);

  if (records.length === 0) {
    console.log('[capture] No files found in directory.');
    return 0;
  }

  const exported = exportToTrainingStudio(records);
  const stored = await addToKnowledgeStore(records);
  console.log(`[capture] Captured ${records.length} files from ${dir}: ${exported} exported, ${stored} stored`);
  return records.length;
}

// ─── File watcher mode (simple polling) ───────────────────────────────────

let lastSnapshotState = '';

/** Watched source directories for non-git polling fallback */
const WATCHED_DIRS = ['backend/src', 'frontend/src', 'llm-training-app'];

/**
 * Compute a quick hash of file mtimes for the watched directories.
 * Used as a lightweight change detector when git is unavailable.
 */
function hashSourceDirs(): string {
  const parts: string[] = [];
  for (const dir of WATCHED_DIRS) {
    const fullDir = path.join(PROJECT_ROOT, dir);
    if (!fs.existsSync(fullDir)) continue;
    try {
      walkForHash(fullDir, parts);
    } catch { /* skip unreadable */ }
  }
  return parts.join('|');
}

function walkForHash(currentDir: string, parts: string[]): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(currentDir, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.')) continue;
    if (entry.name === 'node_modules' || entry.name === 'dist' || entry.name === 'exports') continue;
    const fullPath = path.join(currentDir, entry.name);
    if (entry.isDirectory()) {
      walkForHash(fullPath, parts);
    } else {
      const ext = path.extname(entry.name).toLowerCase();
      if (!['.ts', '.tsx', '.js', '.py', '.css', '.html', '.json', '.md'].includes(ext)) continue;
      try {
        const stat = fs.statSync(fullPath);
        parts.push(`${entry.name}:${stat.mtimeMs}`);
      } catch { /* skip */ }
    }
  }
}

function watchMode(intervalMs: number = 30000): void {
  console.log(`[capture] Watch mode active — polling every ${intervalMs / 1000}s for changes...`);

  let useGitFallback = false;

  async function poll() {
    let hasChanges = false;

    // Try git-based detection first
    try {
      const currentState = execSync('git status --porcelain', { cwd: PROJECT_ROOT, encoding: 'utf-8', timeout: 5000 });

      if (currentState !== lastSnapshotState && currentState.trim()) {
        console.log('[capture] Changes detected, capturing...');
        const { records, exported } = await captureFromGitChanges();
        if (records.length > 0) {
          console.log(`[capture] Captured ${records.length} records from git changes`);
          // Also re-scan source dirs for full context
          await captureFromDirectory('backend/src');
          await captureFromDirectory('frontend/src');
        }
        lastSnapshotState = currentState;
        hasChanges = true;
      }
    } catch {
      // git not available — use filesystem mtime fallback
      useGitFallback = true;
    }

    // Fallback: poll filesystem mtimes for non-git repos
    if (useGitFallback && !hasChanges) {
      const currentHash = hashSourceDirs();
      if (currentHash !== lastSnapshotState && currentHash) {
        console.log('[capture] Filesystem changes detected (mtime), capturing...');
        for (const dir of WATCHED_DIRS) {
          const count = await captureFromDirectory(dir);
          if (count > 0) {
            console.log(`[capture] Re-scanned ${dir}: ${count} files`);
          }
        }
        lastSnapshotState = currentHash;
        hasChanges = true;
      }
    }

    // Initialize state on first poll if not set
    if (!lastSnapshotState) {
      if (useGitFallback) {
        lastSnapshotState = hashSourceDirs();
      }
    }

    setTimeout(poll, intervalMs);
  }

  // Initial capture
  poll();
}

// ─── CLI ─────────────────────────────────────────────────────────────────

async function main() {
  const args = process.argv.slice(2);

  console.log('='.repeat(60));
  console.log('  Codebuff Training Data Pipeline');
  console.log('='.repeat(60));

  if (args.includes('--watch')) {
    // Watch mode — continuously capture changes
    const intervalIndex = args.indexOf('--interval');
    const interval = intervalIndex >= 0 ? parseInt(args[intervalIndex + 1]) || 30000 : 30000;
    await captureFromGitChanges();
    watchMode(interval);
    return;
  }

  if (args.includes('--from-git')) {
    // Capture from uncommitted git changes
    console.log('\n[git] Scanning uncommitted changes...');
    const { records, exported, stored } = await captureFromGitChanges();
    console.log(`\n[complete] ${records.length} records, ${exported} exported to studio, ${stored} stored in knowledge base`);
    return;
  }

  if (args.includes('--dir')) {
    // Capture all files from a directory
    const dirIndex = args.indexOf('--dir');
    const dir = dirIndex >= 0 ? args[dirIndex + 1] : 'backend/src';
    const pattern = args.includes('--pattern') ? new RegExp(args[args.indexOf('--pattern') + 1]) : undefined;
    console.log(`\n[dir] Scanning directory: ${dir}${pattern ? ` (pattern: ${pattern})` : ''}`);
    const count = await captureFromDirectory(dir, pattern);
    console.log(`\n[complete] Captured ${count} files from ${dir}`);
    return;
  }

  if (args.includes('--stats')) {
    // Show capture statistics
    console.log('\n[stats] Capture statistics:');
    let totalRecords = 0;
    let fileCount = 0;
    if (fs.existsSync(CAPTURE_LOG)) {
      const logContent = fs.readFileSync(CAPTURE_LOG, 'utf-8');
      fileCount = logContent.split('\n').filter(l => l.trim()).length;
    }

    const studioFiles = fs.existsSync(TRAINING_STUDIO_DIR)
      ? fs.readdirSync(TRAINING_STUDIO_DIR).filter(f => f.startsWith('codebuff-capture-'))
      : [];

    console.log(`  Capture log records:   ${fileCount}`);
    console.log(`  Studio JSONL files:    ${studioFiles.length}`);
    console.log(`  Knowledge store:       ${getKnowledgeStoreCount()}`);
    console.log(`  Session ID:            ${sessionId}`);
    return;
  }

  // Default: capture from recent changes
  console.log('\n[default] Capturing from uncommitted changes...');
  const { records, exported, stored } = await captureFromGitChanges();
  console.log(`\n[complete] ${records.length} records, ${exported} exported, ${stored} stored`);

  if (records.length === 0) {
    console.log('\n  No changes to capture. Try:');
    console.log('    --watch        Continuous file watching mode');
    console.log('    --dir <path>   Capture all files from a directory');
    console.log('    --from-git     Capture staged/uncommitted git changes');
    console.log('    --stats        Show capture statistics');
  }
}

function getKnowledgeStoreCount(): number {
  try {
    const patternFile = path.join(KNOWLEDGE_DIR, 'patterns.json');
    if (fs.existsSync(patternFile)) {
      const data = JSON.parse(fs.readFileSync(patternFile, 'utf-8'));
      return Array.isArray(data) ? data.length : 0;
    }
  } catch {}
  return 0;
}

main().catch(err => {
  console.error('[capture] Fatal error:', err);
  process.exit(1);
});

/**
 * Extended Venorica RNN Training
 * 
 * Runs 10,000 more iterations on the current model and compares loss.
 * Run with: npx tsx backend/src/scripts/extend-training.ts
 */

import * as path from 'path';
import { rnnEngine } from '../neural/trainer.js';

async function main() {
  const PROJECT_ROOT = process.cwd();
  const MODEL_PATH = path.join(PROJECT_ROOT, 'knowledge', 'rnn-model.json');

  console.log('='.repeat(70));
  console.log('  Venorica RNN — Extended Training (10,000 more iterations)');
  console.log('='.repeat(70));

  // Show pre-training status
  const preStatus = rnnEngine.getStatus();
  console.log('\n📊 PRE-TRAINING STATUS:');
  console.log(`  Iterations so far:  ${preStatus.iterations}`);
  console.log(`  Current loss:       ${preStatus.loss?.toFixed(4) ?? 'N/A'}`);
  console.log(`  Trained chars:      ${(preStatus.trainedChars ?? 0).toLocaleString()}`);
  console.log(`  Vocabulary size:    ${preStatus.vocabSize}`);
  console.log(`  Pattern count:      ${preStatus.patternCount}`);

  // Generate pre-training samples
  console.log(`\n${'='.repeat(70)}`);
  console.log('  PRE-TRAINING GENERATION SAMPLES');
  console.log(`  ${'='.repeat(70)}`);

  const seeds = [
    { seed: 'import', temp: 0.6, label: 'Seed: "import" (temp=0.6)' },
    { seed: 'function', temp: 0.4, label: 'Seed: "function" (temp=0.4)' },
    { seed: 'const', temp: 0.8, label: 'Seed: "const" (temp=0.8)' },
    { seed: 'export', temp: 0.5, label: 'Seed: "export" (temp=0.5)' },
    { seed: 'class', temp: 0.6, label: 'Seed: "class" (temp=0.6)' },
    { seed: 'interface', temp: 0.3, label: 'Seed: "interface" (temp=0.3, low entropy)' },
  ];

  for (const { seed, temp, label } of seeds) {
    try {
      const output = rnnEngine.generate(seed, 200, temp);
      console.log(`\n--- ${label} ---`);
      console.log(output.substring(0, 250).replace(/\n/g, '\\n'));
    } catch (e: any) {
      console.log(`\n--- ${label} --- Error: ${e.message}`);
    }
  }

  // Run extended training
  const ADDITIONAL_ITERATIONS = 10000;
  console.log(`\n${'='.repeat(70)}`);
  console.log(`  🚀 Training for ${ADDITIONAL_ITERATIONS.toLocaleString()} more iterations...`);
  console.log(`  ${'='.repeat(70)}`);

  const startTime = Date.now();

  try {
    const result = await rnnEngine.learnFromKnowledge(ADDITIONAL_ITERATIONS);
    const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);

    // Show post-training status
    const postStatus = rnnEngine.getStatus();

    console.log(`\n✅ TRAINING COMPLETE (${elapsed}s)`);
    console.log('='.repeat(70));
    console.log('  LOSS COMPARISON');
    console.log('  ' + '-'.repeat(50));
    console.log(`  Before:  ${(preStatus.loss ?? 0).toFixed(4)} (after ${preStatus.iterations} iters)`);
    console.log(`  After:   ${(postStatus.loss ?? 0).toFixed(4)} (after ${postStatus.iterations} iters)`);

    const pctImprovement = ((preStatus.loss - postStatus.loss) / preStatus.loss * 100);
    console.log(`  Change:  ${(postStatus.loss - preStatus.loss) > 0 ? '+' : ''}${(postStatus.loss - preStatus.loss).toFixed(4)} (${pctImprovement.toFixed(1)}% reduction)`);

    console.log(`\n  OTHER METRICS:`);
    console.log(`  More characters:   ${result.chars.toLocaleString()}`);
    console.log(`  Total chars:       ${(postStatus.trainedChars ?? 0).toLocaleString()}`);
    console.log(`  Total iterations:  ${postStatus.iterations}`);

    // Generate post-training samples
    console.log(`\n${'='.repeat(70)}`);
    console.log('  POST-TRAINING GENERATION SAMPLES');
    console.log(`  ${'='.repeat(70)}`);

    for (const { seed, temp, label } of seeds) {
      try {
        const output = rnnEngine.generate(seed, 200, temp);
        console.log(`\n--- ${label} ---`);
        console.log(output.substring(0, 250).replace(/\n/g, '\\n'));
      } catch (e: any) {
        console.log(`\n--- ${label} --- Error: ${e.message}`);
      }
    }

    // Summary
    console.log(`\n${'='.repeat(70)}`);
    console.log('  SUMMARY');
    console.log(`  ${'='.repeat(70)}`);
    console.log(`  Training time:     ${elapsed}s`);
    console.log(`  Loss:              ${(preStatus.loss ?? 0).toFixed(4)} → ${(postStatus.loss ?? 0).toFixed(4)}`);
    console.log(`  Improvement:       ${pctImprovement.toFixed(1)}% reduction`);
    console.log(`  Additional chars:  ${result.chars.toLocaleString()}`);
    console.log(`  Model saved at:    ${MODEL_PATH}`);
    console.log(`\n✅ Extended training complete!`);

  } catch (err: any) {
    console.error(`\n❌ Training failed: ${err.message}`);
    process.exit(1);
  }
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

/**
 * Venorica RNN Training Script
 * 
 * Scans all project source files and trains Venorica RNN on them.
 * Run with: npx tsx backend/src/scripts/train-on-codebase.ts
 */

import * as fs from 'fs';
import * as path from 'path';
import { knowledgeStore } from '../knowledge/knowledgeStore.js';
import { rnnEngine } from '../neural/trainer.js';

const PROJECT_ROOT = path.resolve(process.cwd());
const EXTENSIONS = ['.ts', '.tsx', '.css', '.py', '.html', '.js'];
const EXCLUDE_DIRS = ['node_modules', 'dist', '.git', 'exports'];

interface SourceFile {
  path: string;
  relativePath: string;
  content: string;
  language: string;
}

function collectSourceFiles(dir: string): SourceFile[] {
  const files: SourceFile[] = [];

  function walk(currentDir: string) {
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(currentDir, { withFileTypes: true });
    } catch {
      return;
    }

    for (const entry of entries) {
      const fullPath = path.join(currentDir, entry.name);
      const relativePath = path.relative(PROJECT_ROOT, fullPath);

      // Skip excluded directories
      if (entry.isDirectory()) {
        if (EXCLUDE_DIRS.includes(entry.name)) continue;
        walk(fullPath);
        continue;
      }

      const ext = path.extname(entry.name).toLowerCase();
      if (!EXTENSIONS.includes(ext)) continue;

      let content: string;
      try {
        content = fs.readFileSync(fullPath, 'utf-8');
      } catch {
        continue;
      }

      // Skip empty or very small files
      if (content.trim().length < 10) continue;

      // Determine language
      let language = 'unknown';
      switch (ext) {
        case '.ts':
        case '.tsx':
          language = 'typescript';
          break;
        case '.css':
          language = 'css';
          break;
        case '.py':
          language = 'python';
          break;
        case '.html':
          language = 'html';
          break;
        case '.js':
          language = 'javascript';
          break;
      }

      files.push({ path: fullPath, relativePath, content, language });
    }
  }

  walk(dir);
  return files;
}

async function main() {
  console.log('='.repeat(60));
  console.log('  Venorica RNN — Codebase Knowledge Training');
  console.log('='.repeat(60));

  // Check existing patterns count
  const existingCount = knowledgeStore.count();
  console.log(`\n[scan] Existing patterns: ${existingCount}`);

  // Collect all source files
  const srcDirs = [
    path.join(PROJECT_ROOT, 'backend', 'src'),
    path.join(PROJECT_ROOT, 'frontend', 'src'),
  ];

  const allFiles: SourceFile[] = [];
  for (const dir of srcDirs) {
    if (fs.existsSync(dir)) {
      allFiles.push(...collectSourceFiles(dir));
    }
  }

  console.log(`[scan] Found ${allFiles.length} source files to learn from`);

  // Filter out files we've already learned from (check relative paths)
  const existingPatterns = knowledgeStore.getAll();
  const existingPaths = new Set(
    existingPatterns
      .filter(p => p.tags.includes('source-file'))
      .map(p => p.description.split('Source: ')[1] || '')
  );

  const newFiles = allFiles.filter(f => !existingPaths.has(f.relativePath));
  console.log(`[scan] New files to add: ${newFiles.length} (already have ${allFiles.length - newFiles.length})`);

  if (newFiles.length === 0 && existingCount > 0) {
    console.log('[scan] All files already learned. Proceeding to train with more iterations...');
  }

  // Add each file as a pattern
  let addedCount = 0;
  for (const file of newFiles) {
    // Check if we're near the sheet cap — if so, skip remaining
    if (knowledgeStore.count() >= 90) {
      console.log(`[scan] Approaching pattern cap (${knowledgeStore.count()}/100), stopping addition`);
      break;
    }

    const fileName = path.basename(file.path);
    const fileDir = path.dirname(file.relativePath);

    // Generate tags
    const tags = ['source-file', file.language, 'codebase'];
    if (fileDir.includes('/')) {
      tags.push(fileDir.split('/').join('-'));
    }

    try {
      knowledgeStore.addPattern({
        category: 'code_pattern',
        title: `${fileName} — Source code pattern`,
        code: file.content,
        description: `Full source code from ${file.relativePath}. Source: ${file.relativePath}`,
        tags,
        projectId: 'codebase-scan',
        targetOS: 'linux',
        nodeType: 'source-file',
        language: file.language,
        success: true,
        qualityScore: 7.0,
      });
      addedCount++;
    } catch (err: any) {
      console.error(`[scan] Failed to add ${file.relativePath}: ${err.message}`);
    }
  }

  console.log(`\n[add] Added ${addedCount} new patterns to knowledge store`);
  console.log(`[add] Total patterns: ${knowledgeStore.count()}`);

  // Now train the RNN on all patterns
  console.log(`\n${'='.repeat(60)}`);
  console.log('  Training Venorica RNN...');
  console.log(`  ${'='.repeat(60)}`);

  console.log('\n[venorica] Model status before training:');
  console.log(JSON.stringify(rnnEngine.getStatus(), null, 2));

  // Train with substantial iterations
  const ITERATIONS = 3000;
  console.log(`\n[venorica] Starting ${ITERATIONS} training iterations...`);

  try {
    const result = await rnnEngine.learnFromKnowledge(ITERATIONS);
    console.log(`\n[venorica] ✅ Training complete!`);
    console.log(`  Final loss: ${result.loss.toFixed(4)}`);
    console.log(`  Characters seen: ${result.chars.toLocaleString()}`);

    // Generate sample output to verify model learned
    console.log(`\n${'='.repeat(60)}`);
    console.log('  Generation Samples');
    console.log(`  ${'='.repeat(60)}`);

    const seeds = [
      'import',
      'function',
      'const',
      'class',
      'interface',
    ];

    for (const seed of seeds) {
      try {
        const output = rnnEngine.generate(seed, 150, 0.6);
        console.log(`\n--- Seed: "${seed}" (temp=0.6) ---`);
        console.log(output.substring(0, 300));
      } catch (e: any) {
        console.log(`\n--- Seed: "${seed}" --- Error: ${e.message}`);
      }
    }
  } catch (err: any) {
    console.error(`[venorica] Training failed: ${err.message}`);
    process.exit(1);
  }

  // Final stats
  console.log(`\n${'='.repeat(60)}`);
  console.log('  Training Summary');
  console.log(`  ${'='.repeat(60)}`);
  const status = rnnEngine.getStatus();
  console.log(`  Total patterns:      ${knowledgeStore.count()}`);
  console.log(`  New patterns added:  ${addedCount}`);
  console.log(`  Vocab size:          ${status.vocabSize}`);
  console.log(`  Hidden size:         ${status.hiddenSize}`);
  console.log(`  Total iterations:    ${status.iterations}`);
  console.log(`  Final loss:          ${status.loss?.toFixed(4) || 'N/A'}`);
  console.log(`  Characters trained:  ${status.trainedChars?.toLocaleString() || 0}`);
  console.log(`  Model saved to:      ${path.join(PROJECT_ROOT, 'knowledge', 'rnn-model.json')}`);
  console.log(`\n✅ Venorica RNN training complete!`);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});

export type OSType = 'windows' | 'mac' | 'ios' | 'linux' | 'android';

export type NodeType = 'input' | 'output' | 'logic' | 'api' | 'database' | 'ui' | 'master';

export type NodeStatus = 'pending' | 'generating' | 'valid' | 'error';

export interface Node {
  id: string;
  type: NodeType;
  position: { x: number; y: number };
  data: NodeData;
}

export interface NodeData {
  label: string;
  description: string;
  status: NodeStatus;
  language?: string;
  generatedCode?: string;
  error?: string;
  appGoal?: string;
  appPurpose?: string;
  selectedOS?: OSType;
}

export interface Edge {
  id: string;
  source: string;
  target: string;
}

export interface LayerResult {
  code: string;
  errors: string[];
  validated: boolean;
}

export interface DbNode {
  id: string;
  type: NodeType;
  position: { x: number; y: number };
  data: NodeData & { subNodes?: SubNodeData[]; subNodeEdges?: Array<{ id: string; source: string; target: string }> };
}

export interface SubNodeData {
  id: string;
  label: string;
  description: string;
  type: NodeType;
  status: NodeStatus;
  language?: string;
  position: { x: number; y: number };
  generatedCode?: string;
  error?: string;
}

export interface Project {
  id: string;
  name: string;
  targetOS: OSType;
  nodes: DbNode[];
  edges: Edge[];
  createdAt: Date;
  updatedAt: Date;
}

