import { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';
import { useProjectStore, getNextNodeId } from '../store/projectStore';
import type { Node } from 'reactflow';
import type { NodeType, NodeData } from '../types';
import './FileDropHandler.css';

interface DroppedFile {
  path: string;
  content: string;
}

async function readEntry(
  entry: FileSystemEntry,
  basePath = ''
): Promise<DroppedFile[]> {
  if (entry.isFile) {
    const fileEntry = entry as FileSystemFileEntry;
    return new Promise((resolve) => {
      fileEntry.file((file) => {
        const path = basePath ? `${basePath}/${file.name}` : file.name;
        const ext = file.name.split('.').pop()?.toLowerCase() || '';
        const textExts = new Set([
          'js', 'ts', 'jsx', 'tsx', 'py', 'rs', 'go', 'java', 'c', 'cpp', 'h',
          'css', 'html', 'json', 'yaml', 'yml', 'toml', 'md', 'txt', 'xml',
          'sh', 'bash', 'zig', 'swift', 'kt', 'rb', 'php', 'vue', 'svelte',
          'sql', 'graphql', 'prisma', 'env', 'ini', 'cfg', 'conf',
        ]);
        if (file.size > 50000 || !textExts.has(ext)) {
          resolve([{ path, content: `[${file.size > 50000 ? 'binary/large' : 'binary'} file: ${file.name}]` }]);
          return;
        }
        const reader = new FileReader();
        reader.onload = () => resolve([{ path, content: reader.result as string }]);
        reader.onerror = () => resolve([{ path, content: '' }]);
        reader.readAsText(file);
      });
    });
  }
  if (entry.isDirectory) {
    const dirEntry = entry as FileSystemDirectoryEntry;
    const dir = dirEntry.createReader();
    return new Promise((resolve) => {
      const results: DroppedFile[] = [];
      const readDir = () => {
        dir.readEntries(async (entries) => {
          if (entries.length === 0) {
            resolve(results);
            return;
          }
          const sub = await Promise.all(
            entries.map((e) => readEntry(e, basePath ? `${basePath}/${entry.name}` : entry.name))
          );
          for (const s of sub) results.push(...s);
          readDir();
        }, () => resolve(results));
      };
      readDir();
    });
  }
  return [];
}

async function readFiles(items: DataTransferItemList): Promise<DroppedFile[]> {
  const entries: FileSystemEntry[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.kind === 'file') {
      const entry = item.webkitGetAsEntry();
      if (entry) entries.push(entry);
    }
  }
  const results = await Promise.all(entries.map((e) => readEntry(e)));
  return results.flat();
}

const FILE_NODE_TYPES: NodeType[] = ['logic', 'input', 'output', 'api', 'database', 'ui'];

const FileDropHandler: React.FC = () => {
  const [dragOver, setDragOver] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [files, setFiles] = useState<DroppedFile[]>([]);
  const [nodeName, setNodeName] = useState('');
  const [nodeType, setNodeType] = useState<NodeType>('logic');
  const [instructions, setInstructions] = useState('');
  const [status, setStatus] = useState<'idle' | 'analyzing' | 'done' | 'error'>('idle');
  const [statusMsg, setStatusMsg] = useState('');
  const dragCounter = useRef(0);
  const { addNode } = useProjectStore();

  useEffect(() => {
    const handleDragEnter = (e: DragEvent) => {
      if (e.dataTransfer?.types.includes('Files')) {
        dragCounter.current++;
        if (dragCounter.current === 1) setDragOver(true);
      }
    };
    const handleDragLeave = () => {
      dragCounter.current--;
      if (dragCounter.current <= 0) {
        dragCounter.current = 0;
        setDragOver(false);
      }
    };
    const handleDragOver = (e: DragEvent) => {
      if (e.dataTransfer?.types.includes('Files')) {
        e.preventDefault();
      }
    };
    const handleDrop = async (e: DragEvent) => {
      e.preventDefault();
      dragCounter.current = 0;
      setDragOver(false);
      if (!e.dataTransfer?.items || e.dataTransfer.items.length === 0) return;
      setStatus('idle');
      setStatusMsg('');
      try {
        const dropped = await readFiles(e.dataTransfer.items);
        if (dropped.length === 0) return;
        setFiles(dropped);
        const firstFilename = dropped[0].path.split('/').pop() || dropped[0].path;
        const nameParts = firstFilename.replace(/\.[^.]+$/, '').split(/[-_./\\]+/).filter(Boolean);
        setNodeName(nameParts.map((s) => s.charAt(0).toUpperCase() + s.slice(1)).join(' '));
        setNodeType('logic');
        setInstructions('');
        setDialogOpen(true);
      } catch (err) {
        setStatusMsg('Error reading files: ' + (err instanceof Error ? err.message : String(err)));
      }
    };
    document.addEventListener('dragenter', handleDragEnter);
    document.addEventListener('dragleave', handleDragLeave);
    document.addEventListener('dragover', handleDragOver);
    document.addEventListener('drop', handleDrop);
    return () => {
      document.removeEventListener('dragenter', handleDragEnter);
      document.removeEventListener('dragleave', handleDragLeave);
      document.removeEventListener('dragover', handleDragOver);
      document.removeEventListener('drop', handleDrop);
    };
  }, []);

  const handleAnalyze = useCallback(async () => {
    setStatus('analyzing');
    setStatusMsg(`Analyzing ${files.length} file(s) with LLM...`);

    const fileContext = files
      .map((f) => `--- ${f.path} ---\n${f.content}`)
      .join('\n\n');

    const systemPrompt = `You are a sassy code analysis assistant with a sharp wit. Analyze the following dropped file(s) and describe what the code/function does. Provide:
1. A concise summary of the purpose (2-3 sentences)
2. Key functions, classes, or exports
3. Dependencies and inputs/outputs

Keep the response technical and actionable for a developer building a visual app architecture.

User instructions: ${instructions || 'Analyze the files and describe what function they implement.'}

Files to analyze:
${fileContext}`;

    try {
      const res = await axios.post('/api/reason', { prompt: systemPrompt, maxTokens: 1024 });
      const analysis = res.data.response || 'Analysis complete.';

      const nodeData: NodeData = {
        label: nodeName,
        description: analysis,
        type: nodeType,
        status: 'pending' as const,
      };

      const newNode: Node = {
        id: getNextNodeId(),
        type: nodeType,
        position: { x: 300 + Math.random() * 200, y: 200 + Math.random() * 150 },
        data: nodeData,
      };

      addNode(newNode);
      setStatus('done');
      setStatusMsg('Node created successfully!');
      setTimeout(() => {
        setDialogOpen(false);
        setStatus('idle');
      }, 1200);
    } catch (err) {
      setStatus('error');
      setStatusMsg('LLM analysis failed: ' + (err instanceof Error ? err.message : 'Connection error'));
    }
  }, [files, nodeName, nodeType, instructions, addNode]);

  return (
    <>
      {dragOver && (
        <div className="filedrop-overlay dragging">
          <div className="filedrop-hint">Drop files or folders to create a node</div>
        </div>
      )}

      {dialogOpen && (
        <div className="filedrop-dialog-overlay" onClick={() => { if (status !== 'analyzing') setDialogOpen(false); }}>
          <div className="filedrop-dialog" onClick={(e) => e.stopPropagation()}>
            <h2>📁 Create Node from Files</h2>

            <div className="filedrop-file-list">
              {files.slice(0, 30).map((f, i) => (
                <span key={i}>{f.path}</span>
              ))}
              {files.length > 30 && <span>+{files.length - 30} more</span>}
            </div>

            <div className="filedrop-field">
              <label>Node Name</label>
              <input value={nodeName} onChange={(e) => setNodeName(e.target.value)} placeholder="My Function" />
            </div>

            <div className="filedrop-field">
              <label>Node Type</label>
              <select value={nodeType} onChange={(e) => setNodeType(e.target.value as NodeType)}>
                {FILE_NODE_TYPES.map((t) => (
                  <option key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</option>
                ))}
              </select>
            </div>

            <div className="filedrop-field">
              <label>Instructions for LLM (optional)</label>
              <textarea
                value={instructions}
                onChange={(e) => setInstructions(e.target.value)}
                placeholder="Tell the LLM what to focus on when analyzing these files..."
                rows={2}
              />
            </div>

            {status !== 'idle' && (
              <div className={`filedrop-status ${status === 'error' ? 'error' : ''}`}>
                {status === 'analyzing' && <span className="spinner" />}
                {status === 'done' && '✅'}
                {status === 'error' && '❌'}
                {statusMsg}
              </div>
            )}

            <div className="filedrop-actions">
              <button
                className="nn-btn nn-cancel"
                onClick={() => setDialogOpen(false)}
                disabled={status === 'analyzing'}
              >
                Cancel
              </button>
              <button
                className="nn-btn nn-confirm"
                onClick={handleAnalyze}
                disabled={status === 'analyzing' || !nodeName.trim()}
              >
                {status === 'analyzing' ? 'Analyzing...' : 'Analyze & Create Node'}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default FileDropHandler;

import { useEffect } from 'react';

export default function GlobalShortcuts() {
  useEffect(() => {
    function handler(e: KeyboardEvent) {
      if (e.key === 'Escape') {
        document.querySelector<HTMLElement>('.settings-modal-overlay')?.click();
      }
    }
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, []);
  return null;
}

import { useState, useEffect, useCallback, useRef } from 'react';

interface Props {
  onChange?: (model: string, key: string) => void;
}

interface LLMState {
  provider: string;
  model: string;
  apiKey: string;
  baseUrl: string;
}

interface LLMProfile {
  name: string;
  primary: LLMState;
}

const PROVIDERS = [
  { id: 'openai', label: 'OpenAI', needsKey: true, needsBaseUrl: true, defaultModel: 'gpt-4', defaultBaseUrl: 'https://api.openai.com/v1' },
  { id: 'anthropic', label: 'Anthropic', needsKey: true, needsBaseUrl: false, defaultModel: 'claude-sonnet-4-20250514', defaultBaseUrl: '' },
  { id: 'ollama', label: 'Ollama (Local)', needsKey: false, needsBaseUrl: false, defaultModel: '', defaultBaseUrl: 'http://127.0.0.1:11434/v1' },
];

function useDebounce<T>(value: T, ms: number): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), ms);
    return () => clearTimeout(id);
  }, [value, ms]);
  return debounced;
}

const OPENAI_MODELS = ['gpt-4', 'gpt-4-turbo', 'gpt-4o', 'gpt-4o-mini', 'gpt-3.5-turbo'];
const ANTHROPIC_MODELS = ['claude-sonnet-4-20250514', 'claude-3-5-sonnet-latest', 'claude-3-opus-latest', 'claude-3-haiku-latest'];
const OLLAMA_CHAT_MODELS = ['llama3.2', 'llama3.1', 'llama3', 'mistral', 'gemma2', 'phi3', 'qwen2.5', 'deepseek-r1', 'deepseek-v3', 'deepseek-v4'];
const CODE_KEYWORDS = ['embed', 'codellama', 'codegemma', 'starcoder', 'codeqwen', 'deepseek-coder'];

const LS_KEYS = {
  primary: { provider: 'llm-provider', model: 'llm-model', key: 'llm-key', baseUrl: 'llm-base-url' },

};
const PROFILES_KEY = 'llm-profiles';

function loadPersistedLLM(keys: typeof LS_KEYS.primary): LLMState {
  return {
    provider: localStorage.getItem(keys.provider) || 'ollama',
    model: localStorage.getItem(keys.model) || '',
    apiKey: localStorage.getItem(keys.key) || '',
    baseUrl: localStorage.getItem(keys.baseUrl) || '',
  };
}

function persistToServer(primary: LLMState) {
  localStorage.setItem(LS_KEYS.primary.provider, primary.provider);
  localStorage.setItem(LS_KEYS.primary.model, primary.model);
  localStorage.setItem(LS_KEYS.primary.key, primary.apiKey);
  localStorage.setItem(LS_KEYS.primary.baseUrl, primary.baseUrl);
  fetch('/api/config/llm', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      primary: { provider: primary.provider, apiKey: primary.apiKey, model: primary.model, baseUrl: primary.baseUrl },
    }),
  }).catch(() => {});
}

function loadProfiles(): LLMProfile[] {
  try {
    return JSON.parse(localStorage.getItem(PROFILES_KEY) || '[]');
  } catch { return []; }
}

function saveProfiles(profiles: LLMProfile[]) {
  localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
}

function LLMConfigSection({
  state,
  onChange,
  ollamaModels,
  ollamaScanning,
  onDetectOllama,
}: {
  state: LLMState;
  onChange: (s: LLMState) => void;
  ollamaModels: string[];
  ollamaScanning: boolean;
  onDetectOllama: () => void;
}) {
  const providerCfg = PROVIDERS.find(p => p.id === state.provider);
  const modelOptions = state.provider === 'ollama'
    ? (ollamaModels.length > 0 ? ollamaModels : OLLAMA_CHAT_MODELS)
    : state.provider === 'anthropic'
    ? ANTHROPIC_MODELS
    : OPENAI_MODELS;

  const set = (partial: Partial<LLMState>) => onChange({ ...state, ...partial });

  const handleProviderChange = (p: string) => {
    if (p === 'ollama') {
      set({ provider: p, apiKey: '', model: '', baseUrl: 'http://127.0.0.1:11434/v1' });
      onDetectOllama();
    } else if (p === 'openai') {
      set({ provider: p, model: OPENAI_MODELS[0], baseUrl: 'https://api.openai.com/v1' });
    } else if (p === 'anthropic') {
      set({ provider: p, model: ANTHROPIC_MODELS[0], baseUrl: '' });
    }
  };

  return (
    <div className="llm-config-section">
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <label style={{ fontSize: 11 }}>
          Provider:
          <select value={state.provider} onChange={(e) => handleProviderChange(e.target.value)}>
            {PROVIDERS.map(p => (
              <option key={p.id} value={p.id}>{p.label}</option>
            ))}
          </select>
        </label>

        {state.provider === 'ollama' && (
          <label style={{ fontSize: 11 }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              Model:
              <button onClick={onDetectOllama} disabled={ollamaScanning} style={{ fontSize: 11, padding: '1px 6px' }}>
                {ollamaScanning ? 'Scanning...' : '🔄'}
              </button>
            </span>
            <select value={state.model} onChange={(e) => set({ model: e.target.value })}>
              {modelOptions.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </label>
        )}

        {state.provider !== 'ollama' && (
          <label style={{ fontSize: 11 }}>
            Model:
            <select value={state.model} onChange={(e) => set({ model: e.target.value })}>
              {modelOptions.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </label>
        )}

        {providerCfg?.needsKey && (
          <label style={{ fontSize: 11 }}>
            API Key:
            <input
              type="password"
              value={state.apiKey}
              onChange={(e) => set({ apiKey: e.target.value })}
              placeholder={state.provider === 'openai' ? 'sk-...' : 'Enter your Anthropic key'}
            />
          </label>
        )}

        {state.provider === 'ollama' && (
          <label style={{ fontSize: 11 }}>
            Host:
            <input
              type="text"
              value={state.baseUrl}
              onChange={(e) => set({ baseUrl: e.target.value })}
              placeholder="http://127.0.0.1:11434/v1"
            />
          </label>
        )}

        {state.provider === 'openai' && (
          <label style={{ fontSize: 11 }}>
            API Base URL:
            <input
              type="text"
              value={state.baseUrl}
              onChange={(e) => set({ baseUrl: e.target.value })}
              placeholder="https://api.openai.com/v1"
            />
          </label>
        )}
      </div>
    </div>
  );
}

const btnStyle: React.CSSProperties = {
  fontSize: 10,
  padding: '2px 6px',
  border: '1px solid #4a4a6a',
  borderRadius: 3,
  background: '#2a2a3e',
  color: '#ccc',
  cursor: 'pointer',
};

const LLMConfig: React.FC<Props> = ({ onChange }) => {
  const [primary, setPrimary] = useState<LLMState>(() => loadPersistedLLM(LS_KEYS.primary));
  const [ollamaModels, setOllamaModels] = useState<string[]>([]);
  const [ollamaScanning, setOllamaScanning] = useState(false);
  const [profiles, setProfiles] = useState<LLMProfile[]>(() => loadProfiles());
  const [selectedProfile, setSelectedProfile] = useState('');
  const [profileNameInput, setProfileNameInput] = useState('');
  const [showNewProfile, setShowNewProfile] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const importRef = useRef<HTMLInputElement>(null);

  const detectOllama = useCallback(async () => {
    setOllamaScanning(true);
    const tagUrls = [
      'http://127.0.0.1:11434/api/tags',
      'http://localhost:11434/api/tags',
      '/api/config/ollama-models',
    ];
    for (const tagUrl of tagUrls) {
      try {
        const res = await fetch(tagUrl, { signal: AbortSignal.timeout(3000) });
        if (res.ok) {
          const data = await res.json();
          const names: string[] = (data.models || []).map((m: any) => m.name);
          const chatModels = names.filter(n => !CODE_KEYWORDS.some(k => n.toLowerCase().includes(k)));
          if (chatModels.length > 0) {
            setOllamaModels(chatModels);
            setOllamaScanning(false);
            return;
          }
        }
      } catch {}
    }
    setOllamaModels(OLLAMA_CHAT_MODELS);
    setOllamaScanning(false);
  }, []);

  useEffect(() => {
    detectOllama();
  }, []);

  const debouncedPrimary = useDebounce(primary, 500);

  useEffect(() => {
    if (debouncedPrimary.model) {
      persistToServer(debouncedPrimary);
      onChange?.(debouncedPrimary.model, debouncedPrimary.apiKey);
    }
  }, [debouncedPrimary]);

  const getCurrentSnapshot = (): LLMProfile => ({
    name: selectedProfile || 'current',
    primary: { ...primary },
  });

  const handleSave = () => {
    const name = profileNameInput.trim();
    if (!name) return;
    const updated = [...profiles.filter(p => p.name !== name)];
    updated.push({ name, primary: { ...primary } });
    updated.sort((a, b) => a.name.localeCompare(b.name));
    saveProfiles(updated);
    setProfiles(updated);
    setSelectedProfile(name);
    setShowNewProfile(false);
    setProfileNameInput('');
  };

  const handleLoad = () => {
    const profile = profiles.find(p => p.name === selectedProfile);
    if (!profile) return;
    setPrimary(profile.primary);
  };

  const handleNew = () => {
    setSelectedProfile('');
    setProfileNameInput('');
    setShowNewProfile(true);
  };

  const handleExport = () => {
    const snapshot = getCurrentSnapshot();
    const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${snapshot.name.replace(/\s+/g, '_')}_llm_config.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = () => {
    importRef.current?.click();
  };

  const handlePersistToDisk = async () => {
    setSaveStatus('saving');
    try {
      const res = await fetch('/api/config/llm/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          primary: { provider: primary.provider, apiKey: primary.apiKey, model: primary.model, baseUrl: primary.baseUrl },
        }),
      });
      if (res.ok) {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } else {
        setSaveStatus('error');
        setTimeout(() => setSaveStatus('idle'), 3000);
      }
    } catch {
      setSaveStatus('error');
      setTimeout(() => setSaveStatus('idle'), 3000);
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const profile: LLMProfile = JSON.parse(ev.target?.result as string);
        if (profile.primary) {
          setPrimary(profile.primary);

          if (profile.name) setSelectedProfile(profile.name);
        }
      } catch {}
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="llm-config" style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      <input
        ref={importRef}
        type="file"
        accept=".json"
        style={{ display: 'none' }}
        onChange={handleImportFile}
      />

      <div style={{ display: 'flex', alignItems: 'center', gap: 4, flexWrap: 'wrap' }}>
        <select
          value={selectedProfile}
          onChange={(e) => setSelectedProfile(e.target.value)}
          style={{ flex: 1, fontSize: 11, minWidth: 100 }}
        >
          <option value="">-- Select Profile --</option>
          {profiles.map(p => (
            <option key={p.name} value={p.name}>{p.name}</option>
          ))}
        </select>
        <button style={btnStyle} onClick={handleNew} title="New profile">New</button>
        {showNewProfile ? (
          <>
            <input
              type="text"
              value={profileNameInput}
              onChange={(e) => setProfileNameInput(e.target.value)}
              placeholder="Profile name"
              style={{ fontSize: 10, width: 90, padding: '1px 4px' }}
              onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); }}
            />
            <button style={btnStyle} onClick={handleSave}>Save</button>
          </>
        ) : (
          <button style={btnStyle} onClick={handleSave} title="Save current as">Save</button>
        )}
        <button style={btnStyle} onClick={handleLoad} title="Load selected profile" disabled={!selectedProfile}>Load</button>
        <button style={btnStyle} onClick={handleExport} title="Export as JSON">Export</button>
        <button style={btnStyle} onClick={handleImport} title="Import from JSON">Import</button>
      </div>

      <div style={{
        border: '1px solid #4a9eff',
        borderRadius: 6,
        padding: 10,
        background: 'rgba(74, 158, 255, 0.05)'
      }}>
        <div style={{ fontSize: 13, fontWeight: 'bold', color: '#4a9eff', marginBottom: 6 }}>
          LLM 1 — Reasoning & Design
        </div>
        <div style={{ fontSize: 10, color: '#888', marginBottom: 8 }}>
          Handles reasoning, blueprints, roadmap, and code design
        </div>
        <LLMConfigSection
          state={primary}
          onChange={setPrimary}
          ollamaModels={ollamaModels}
          ollamaScanning={ollamaScanning}
          onDetectOllama={detectOllama}
        />
      </div>



      <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'flex-end' }}>
        <span style={{ fontSize: 10, color: saveStatus === 'saved' ? '#4ade80' : saveStatus === 'error' ? '#f87171' : '#888' }}>
          {saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? 'Saved to disk' : saveStatus === 'error' ? 'Save failed' : ''}
        </span>
        <button
          onClick={handlePersistToDisk}
          disabled={saveStatus === 'saving'}
          style={{
            fontSize: 11, padding: '5px 14px', border: '1px solid #4ade80', borderRadius: 4,
            background: 'rgba(74, 222, 128, 0.1)', color: '#4ade80', cursor: 'pointer', fontWeight: 500,
          }}
        >
          {saveStatus === 'saving' ? 'Saving...' : '💾 Save to Disk'}
        </button>
      </div>
    </div>
  );
};

export default LLMConfig;

