import { memo, useCallback, useRef, useState } from 'react';
import { Handle, Position, NodeProps } from 'reactflow';
import { OSType, OS_OPTIONS } from '../types';
import { useProjectStore, getNextNodeId } from '../store/projectStore';
import './MasterNode.css';

interface MasterNodeData {
  label: string;
  appGoal?: string;
  appPurpose?: string;
  selectedOS?: OSType;
  status?: string;
}

const NODE_TYPES = ['input', 'output', 'logic', 'api', 'database', 'ui'] as const;

function MasterNode({ id, data, selected }: NodeProps<MasterNodeData>) {
  const updateNode = useProjectStore((s) => s.updateNode);
  const goalRef = useRef<HTMLTextAreaElement>(null);
  const purposeRef = useRef<HTMLTextAreaElement>(null);
  const [building, setBuilding] = useState(false);

  const onGoalChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      updateNode(id, { appGoal: e.target.value });
    },
    [id, updateNode]
  );

  const onPurposeChange = useCallback(
    (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      updateNode(id, { appPurpose: e.target.value });
    },
    [id, updateNode]
  );

  const onOSChange = useCallback(
    (e: React.ChangeEvent<HTMLSelectElement>) => {
      updateNode(id, { selectedOS: e.target.value as OSType });
      useProjectStore.getState().setTargetOS(e.target.value as OSType);
    },
    [id, updateNode]
  );

  const handleBuildSetup = useCallback(async () => {
    const goal = (data.appGoal || '').trim();
    const purpose = (data.appPurpose || '').trim();
    const os = data.selectedOS || 'linux';

    if (!goal && !purpose) {
      alert('Please describe what you want to build first.');
      return;
    }

    setBuilding(true);

    const store = useProjectStore.getState();

    const systemPrompt = `You are an expert software architect. Given a user's app description, generate a node-based architecture.

Return ONLY a JSON array of nodes. Each node has:
- "label": short name
- "description": what this node does (2-3 sentences)
- "type": one of ${NODE_TYPES.join(', ')}
- "language": one of javascript, typescript, python, rust, go, java, csharp, cpp, swift, kotlin, php, ruby
- "position": { "x": number, "y": number } — arrange in a logical left-to-right, top-to-bottom flow

Also return an "edges" array with { "source": label, "target": label } for connections.

Respond with valid JSON only, no markdown formatting, no code fences.`;

    const prompt = `Build a node-based architecture for this app:
Goal: ${goal || 'Not specified'}
Purpose: ${purpose || 'Not specified'}
Target OS: ${os}

Generate 4-8 nodes that cover input handling, core logic, data storage, external APIs, UI, and output. Use appropriate languages for each node's purpose.`;

    try {
      const res = await fetch('/api/reason', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt, system: systemPrompt, maxTokens: 512 }),
        signal: AbortSignal.timeout(15000),
      });
      if (!res.ok) throw new Error(`Reasoning API returned ${res.status}`);
      const data = await res.json();
      const text = data.response || '';

      let parsed;
      try {
        parsed = JSON.parse(text);
      } catch {
        const jsonMatch = text.match(/\[[\s\S]*\]/);
        if (jsonMatch) {
          try {
            parsed = JSON.parse(jsonMatch[0]);
          } catch {
            throw new Error('Could not parse LLM response as JSON');
          }
        } else {
          throw new Error('Could not parse LLM response as JSON');
        }
      }

      const nodesArr = Array.isArray(parsed) ? parsed : parsed.nodes || [];
      const edgesArr = parsed.edges || [];

      if (nodesArr.length === 0) {
        throw new Error('No nodes returned from LLM');
      }

      const idMap: Record<string, string> = {};
      const flowNodes = nodesArr.map((n: any) => {
        const nodeId = getNextNodeId();
        idMap[n.label] = nodeId;
        return {
          id: nodeId,
          type: n.type || 'logic',
          position: n.position || { x: 250, y: 300 + nodesArr.indexOf(n) * 170 },
          data: {
            label: n.label,
            description: n.description || '',
            type: n.type || 'logic',
            status: 'pending' as const,
            language: n.language || 'typescript',
          },
        };
      });

      const flowEdges = edgesArr
        .filter((e: any) => idMap[e.source] && idMap[e.target])
        .map((e: any) => ({
          id: `edge_${idMap[e.source]}_${idMap[e.target]}`,
          source: idMap[e.source],
          target: idMap[e.target],
          type: 'default' as const,
        }));

      store.batchAddNodes(flowNodes, flowEdges, os);
    } catch (err: any) {
      console.error('Build Node Setup failed:', err);
      alert(`AI architecture generation failed: ${err.message}. Falling back to template.`);
      fallbackTemplate(goal, purpose, os, store);
    } finally {
      setBuilding(false);
    }
  }, [data]);

  const onPointerDown = useCallback((e: React.PointerEvent) => {
    e.stopPropagation();
  }, []);

  return (
    <div className={`master-node ${selected ? 'selected' : ''}`}>
      <div className="master-node-header">
        <span className="master-node-icon">🎯</span>
        <span className="master-node-title">App Blueprint</span>
      </div>

      <div className="master-node-body">
        <label className="master-field">
          <span className="master-field-label">What you want to build</span>
          <textarea
            ref={goalRef}
            className="master-textarea react-flow__nodrag"
            placeholder="Describe the app you want to build..."
            value={data.appGoal || ''}
            onChange={onGoalChange}
            onPointerDown={onPointerDown}
            rows={3}
          />
        </label>

        <label className="master-field">
          <span className="master-field-label">What the app is used for</span>
          <textarea
            ref={purposeRef}
            className="master-textarea react-flow__nodrag"
            placeholder="Describe what users will do with it..."
            value={data.appPurpose || ''}
            onChange={onPurposeChange}
            onPointerDown={onPointerDown}
            rows={3}
          />
        </label>

        <label className="master-field">
          <span className="master-field-label">Target OS</span>
          <select
            className="master-select react-flow__nodrag"
            value={data.selectedOS || 'linux'}
            onChange={onOSChange}
            onPointerDown={onPointerDown}
          >
            {OS_OPTIONS.map((os) => (
              <option key={os.value} value={os.value}>{os.label}</option>
            ))}
          </select>
        </label>

        <button
          className={`master-build-btn react-flow__nodrag ${building ? 'building' : ''}`}
          onClick={handleBuildSetup}
          disabled={building}
          onPointerDown={onPointerDown}
        >
          {building ? '⏳ Building...' : '🤖 Build Node Setup'}
        </button>
      </div>

      <div className="master-node-footer">
        <span className="master-hint">
          Fill in the details above. The Reasoning LLM will analyze your requirements and create a custom node architecture.
        </span>
      </div>

      <Handle type="source" position={Position.Bottom} className="master-handle" />
    </div>
  );
}

function fallbackTemplate(goal: string, purpose: string, os: OSType, store: any) {
  const lang = 'typescript';
  const g = goal.toLowerCase();
  const p = purpose.toLowerCase();
  const isGame = /game|play|player|board|turn/i.test(g) || /game|play|player|board|turn/i.test(p);
  const isData = /data|analytics|report|dashboard|chart|monitor/i.test(g) || /data|report|analytics|dashboard/i.test(p);
  const isApi = /api|backend|server|webhook|rest|graphql/i.test(g) || /api|server|backend/i.test(p);

  let nodes: any[] = [];
  let edges: any[] = [];

  if (isGame) {
    nodes = [
      { id: getNextNodeId(), type: 'input', position: { x: 300, y: 300 }, data: { label: 'Player Input', description: `Handle player input for ${goal || 'the game'}. Capture clicks, taps, or key presses.`, type: 'input', status: 'pending', language: lang } },
      { id: getNextNodeId(), type: 'logic', position: { x: 300, y: 470 }, data: { label: 'Game State', description: `Maintain game state: ${purpose || goal || 'game logic'}. Track turns, scores, board state.`, type: 'logic', status: 'pending', language: lang } },
