import { useState, useEffect, useCallback, useRef } from 'react';
import axios from 'axios';

interface RunningModel {
  name: string;
  size?: number;
  processor?: string;
  expiresAt?: string;
  details?: Record<string, any>;
}

interface RunningHost {
  host: string;
  models: RunningModel[];
  reachable: boolean;
  error?: string;
}

function formatBytes(bytes?: number): string {
  if (!bytes) return '?';
  if (bytes >= 1e9) return (bytes / 1e9).toFixed(1) + ' GB';
  if (bytes >= 1e6) return (bytes / 1e6).toFixed(1) + ' MB';
  return bytes + ' B';
}

function persistLlm(model: string, baseUrl: string) {
  localStorage.setItem('llm-model', model);
  if (baseUrl) localStorage.setItem('llm-base-url', baseUrl);
  localStorage.setItem('llm-provider', 'openai');
  fetch('/api/config/llm', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      primary: {
        provider: 'openai',
        model: localStorage.getItem('llm-model') || '',
        apiKey: localStorage.getItem('llm-key') || '',
        baseUrl: localStorage.getItem('llm-base-url') || '',
      },
    }),
  }).catch(() => {});
}

function readActive(): { model: string; baseUrl: string } | null {
  const model = localStorage.getItem('llm-model');
  const baseUrl = localStorage.getItem('llm-base-url');
  if (!model) return null;
  return { model, baseUrl: baseUrl || 'http://127.0.0.1:11434/v1' };
}

const DEFAULT_HOSTS = ['http://127.0.0.1:11434', 'http://localhost:11434'];

const ModelExplorer: React.FC = () => {
  const [hosts, setHosts] = useState<RunningHost[]>([]);
  const [scanning, setScanning] = useState(false);
  const [customHost, setCustomHost] = useState('');
  const [collapsed, setCollapsed] = useState(false);
  const [version, setVersion] = useState(0);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const activeLlm = readActive();
  void version;

  const scan = useCallback(async (hostList: string[]) => {
    if (hostList.length === 0) return;
    setScanning(true);
    try {
      const res = await axios.post('/api/config/models/running', { hosts: hostList });
      const discovered: RunningHost[] = res.data.hosts || [];
      setHosts((prev) => {
        const merged = [...prev];
        for (const d of discovered) {
          const idx = merged.findIndex((h) => h.host === d.host);
          if (idx >= 0) merged[idx] = d;
          else merged.push(d);
        }
        return merged;
      });
    } catch {}
    setScanning(false);
  }, []);

  const hostsRef = useRef(hosts);
  hostsRef.current = hosts;

  useEffect(() => {
    const allHosts = DEFAULT_HOSTS;
    scan(allHosts);
    intervalRef.current = setInterval(() => {
      const current = hostsRef.current;
      scan(current.length > 0 ? current.map((h) => h.host) : DEFAULT_HOSTS);
    }, 10000);
    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, []);

  const addCustomHost = () => {
    const url = customHost.trim().replace(/\/+$/, '');
    if (!url) return;
    if (hosts.some((h) => h.host === url)) return;
    scan([url]);
    setCustomHost('');
  };

  const assign = (model: string, host: string) => {
    const baseUrl = host.replace(/\/+$/, '') + '/v1';
    persistLlm(model, baseUrl);
    setVersion((v) => v + 1);
  };

  const isActive = (modelName: string, host: string): boolean => {
    const baseUrl = host.replace(/\/+$/, '') + '/v1';
    return activeLlm?.model === modelName && activeLlm?.baseUrl === baseUrl;
  };

  const allRunning = hosts.flatMap((h) =>
    h.models.map((m) => ({ ...m, host: h.host, reachable: h.reachable }))
  );

  if (collapsed) {
    return (
      <div style={{
        width: 32,
        background: '#0f0f1a',
        borderLeft: '1px solid #4a4a6a',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        paddingTop: 8,
        cursor: 'pointer',
      }} onClick={() => setCollapsed(false)} title="Running Models">
        <span style={{ fontSize: 16 }}>⚡</span>
        <span style={{ fontSize: 9, color: '#888', writingMode: 'vertical-rl', marginTop: 8 }}>Running</span>
      </div>
    );
  }

  return (
    <div style={{
      width: 260,
      background: '#0f0f1a',
      borderLeft: '1px solid #4a4a6a',
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden',
      flexShrink: 0,
    }}>
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '6px 10px',
        borderBottom: '1px solid #4a4a6a',
      }}>
        <span style={{ fontSize: 12, fontWeight: 'bold', color: '#00d9ff' }}>
          Running Models
        </span>
        <div style={{ display: 'flex', gap: 4 }}>
          <button
            onClick={() => scan(hosts.length > 0 ? hosts.map((h) => h.host) : DEFAULT_HOSTS)}
            disabled={scanning}
            style={{ background: 'none', border: 'none', color: '#888', cursor: 'pointer', fontSize: 12 }}
            title="Refresh"
          >
            {scanning ? '⋯' : '↻'}
          </button>
          <button
            onClick={() => setCollapsed(true)}
            style={{ background: 'none', border: 'none', color: '#888', cursor: 'pointer', fontSize: 14 }}
            title="Collapse"
          >
            ▸
          </button>
        </div>
      </div>

      <div style={{ padding: '6px 10px', borderBottom: '1px solid #2a2a4a' }}>
        <div style={{ display: 'flex', gap: 4 }}>
          <input
            type="text"
            value={customHost}
            onChange={(e) => setCustomHost(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && addCustomHost()}
            placeholder="Add Ollama host: http://ip:11434"
            style={{ flex: 1, fontSize: 11, padding: '3px 6px', background: '#1a1a2e', border: '1px solid #4a4a6a', borderRadius: 3, color: '#eee' }}
          />
          <button
            onClick={addCustomHost}
            disabled={scanning || !customHost.trim()}
            style={{ fontSize: 11, padding: '3px 8px', background: '#00d9ff', color: '#0f0f1a', border: 'none', borderRadius: 3, cursor: 'pointer' }}
          >
            +
          </button>
        </div>
        <div style={{ fontSize: 9, color: '#666', marginTop: 4 }}>
          Auto-refreshes every 10s
        </div>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: 4 }}>
        {allRunning.length === 0 && !scanning && (
          <div style={{ fontSize: 11, color: '#666', textAlign: 'center', padding: 20 }}>
            No models currently running.<br />Add a host or load a model in Ollama first.
          </div>
        )}
        {allRunning.map((model, i) => {
          const active = isActive(model.name, model.host);
          return (
            <div key={`${model.host}-${model.name}-${i}`} style={{
              padding: '6px 8px',
              marginBottom: 4,
              borderRadius: 4,
              background: active ? 'rgba(74, 158, 255, 0.1)' : '#1a1a2e',
              border: active
                ? '1px solid #4a9eff'
                : '1px solid #2a2a4a',
              fontSize: 11,
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <strong style={{ color: '#eee', fontSize: 12 }}>{model.name}</strong>
                <span style={{
                  fontSize: 9,
                  padding: '1px 5px',
                  borderRadius: 3,
                  background: active ? '#4a9eff' : '#2a2a4a',
                  color: active ? '#fff' : '#666',
                }}>
                  {active ? 'Active' : 'idle'}
                </span>
              </div>
              <div style={{ color: '#888', fontSize: 10, marginTop: 2 }}>
                {model.host.replace(/^https?:\/\//, '')}
                {model.size ? ` · ${formatBytes(model.size)}` : ''}
                {model.processor ? ` · ${model.processor}` : ''}
              </div>
              <div style={{ display: 'flex', gap: 4, marginTop: 4 }}>
                <button
                  onClick={() => assign(model.name, model.host)}
                  style={{
                    flex: 1, fontSize: 9, padding: '2px 4px', border: 'none', borderRadius: 3, cursor: 'pointer',
                    background: active ? '#4a9eff' : '#2a2a4a',
                    color: active ? '#fff' : '#aaa',
                  }}
                >
                  {active ? '✓ Active' : '→ Use this model'}
                </button>
              </div>
            </div>
          );
        })}
        {scanning && (
          <div style={{ fontSize: 11, color: '#888', textAlign: 'center', padding: 10 }}>
            Scanning hosts for running models...
          </div>
        )}
      </div>
    </div>
  );
};

export default ModelExplorer;

