function LlmSettingsPanel({ onClose }: { onClose: () => void }) {
  const [provider, setProvider] = useState(() => localStorage.getItem('llm-provider') || 'ollama');
  const [apiKey, setApiKey] = useState(() => localStorage.getItem('llm-key') || '');
  const [model, setModel] = useState(() => localStorage.getItem('llm-model') || '');
  const [baseUrl, setBaseUrl] = useState(() => localStorage.getItem('llm-base-url') || '');
  const [status, setStatus] = useState('');
  const [statusType, setStatusType] = useState<'success' | 'error' | ''>('');
  const [ollamaModels, setOllamaModels] = useState<string[]>([]);
  const [scanning, setScanning] = useState(true);
  const [tab, setTab] = useState<'local' | 'cloud'>('local');

  const applyConfig = useCallback((p: string, k: string, m: string, u: string) => {
    setProvider(p);
    setApiKey(k);
    setModel(m);
    setBaseUrl(u);
    localStorage.setItem('llm-provider', p);
    localStorage.setItem('llm-key', k);
    localStorage.setItem('llm-model', m);
    localStorage.setItem('llm-base-url', u);
    fetch('/api/config/llm', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        primary: { provider: p === 'ollama' ? 'ollama' : p, apiKey: k, model: m, baseUrl: u },
      }),
    }).catch(() => {});
  }, []);

  useEffect(() => {
    (async () => {
      setScanning(true);
      const urls = [
        'http://127.0.0.1:11434/api/tags',
        'http://localhost:11434/api/tags',
        '/api/config/ollama-models',
      ];
      for (const url of urls) {
        try {
          const res = await fetch(url, { signal: AbortSignal.timeout(3000) });
          if (res.ok) {
            const data = await res.json();
            const names: string[] = (data.models || []).map((m: any) => m.name);
            if (names.length > 0) {
              setOllamaModels(names);
              setScanning(false);
              return;
            }
          }
        } catch {}
      }
      setOllamaModels([]);
      setScanning(false);
    })();
  }, []);

  const handleSelectOllamaModel = (m: string) => {
    applyConfig('ollama', '', m, 'http://127.0.0.1:11434/v1');
    setStatus(`✅ Connected — ${m}`);
    setStatusType('success');
  };

  const handleCloudConfig = () => {
    applyConfig(provider, apiKey, model, baseUrl);
    setStatus('Saved');
    setStatusType('success');
  };

  const handleTestConnection = async () => {
    setStatus('Testing both LLM slots...');
    setStatusType('');
    const testEndpoint = async (p: string, k: string, m: string, u: string, label: string): Promise<string> => {
      const url = u || (p === 'openai' ? 'https://api.openai.com/v1' : p === 'ollama' ? 'http://127.0.0.1:11434/v1' : '');
      if (!url) return `${label}: ⚠ No URL configured`;
      try {
        const endpoint = url.replace(/\/+$/, '') + '/chat/completions';
        const headers: Record<string, string> = { 'Content-Type': 'application/json' };
        if (k) headers['Authorization'] = 'Bearer ' + k;
        const res = await fetch(endpoint, {
          method: 'POST', headers,
          body: JSON.stringify({ model: m || 'gpt-4', messages: [{ role: 'user', content: 'Reply with just: ok' }], max_tokens: 10 }),
          signal: AbortSignal.timeout(8000),
        });
        return res.ok ? `${label}: ✅ OK` : `${label}: ❌ HTTP ${res.status}`;
      } catch (e: any) { return `${label}: ❌ ${e?.message || 'Failed'}`; }
    };

    const results = await Promise.all([
      testEndpoint(provider, apiKey, model, baseUrl, 'LLM 1'),
      testEndpoint(
        localStorage.getItem('llm-secondary-provider') || provider,
        localStorage.getItem('llm-secondary-key') || apiKey,
        localStorage.getItem('llm-secondary-model') || model,
        localStorage.getItem('llm-secondary-base-url') || baseUrl,
        'LLM 2'
      ),
    ]);

    const allOk = results.every(r => r.includes('✅'));
    setStatus(results.join('  |  '));
    setStatusType(allOk ? 'success' : 'error');
  };

  return (
    <div className="settings-modal-overlay" onClick={onClose}>
      <div className="settings-modal" onClick={(e) => e.stopPropagation()}>
        <div className="settings-modal-header">
          <span>LLM Connection</span>
          <button className="settings-modal-close" onClick={onClose}>✕</button>
        </div>
        <div className="settings-modal-body">

          <div style={{ display: 'flex', gap: 0, marginBottom: 12, borderBottom: '1px solid #3a3a5a' }}>
            <button
              onClick={() => setTab('local')}
              style={{
                flex: 1, padding: '6px 0', border: 'none', cursor: 'pointer', fontWeight: tab === 'local' ? 600 : 400,
                background: tab === 'local' ? '#2a2a4e' : 'transparent', color: tab === 'local' ? '#fff' : '#888',
                borderBottom: tab === 'local' ? '2px solid #4ade80' : '2px solid transparent', fontSize: 12,
              }}
            >
              🖥 Local LLM
            </button>
            <button
              onClick={() => setTab('cloud')}
              style={{
                flex: 1, padding: '6px 0', border: 'none', cursor: 'pointer', fontWeight: tab === 'cloud' ? 600 : 400,
                background: tab === 'cloud' ? '#2a2a4e' : 'transparent', color: tab === 'cloud' ? '#fff' : '#888',
                borderBottom: tab === 'cloud' ? '2px solid #60a5fa' : '2px solid transparent', fontSize: 12,
              }}
            >
              ☁ Cloud API
            </button>
          </div>

          {tab === 'local' ? (
            <>
              <div style={{ fontSize: 11, color: '#aaa', marginBottom: 8 }}>
                {scanning ? 'Scanning for local LLMs...' : ollamaModels.length > 0 ? 'Select a running model:' : 'No local LLM detected.'}
              </div>
              {scanning ? (
                <div style={{ textAlign: 'center', padding: 12, fontSize: 11, color: '#888' }}>⏳ Scanning...</div>
              ) : ollamaModels.length > 0 ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 4, maxHeight: 200, overflowY: 'auto' }}>
                  {ollamaModels.map((m) => (
                    <button
                      key={m}
                      onClick={() => handleSelectOllamaModel(m)}
                      style={{
                        textAlign: 'left', padding: '8px 10px', border: m === model ? '1px solid #4ade80' : '1px solid #3a3a5a',
                        borderRadius: 5, background: m === model ? 'rgba(74,222,128,0.1)' : '#1e1e2e',
                        color: m === model ? '#4ade80' : '#ccc', cursor: 'pointer', fontSize: 12,
                      }}
                    >
                      <strong>{m}</strong>
                      <span style={{ float: 'right', fontSize: 10, color: '#666' }}>Ollama</span>
                    </button>
                  ))}
                </div>
              ) : (
                <div style={{ textAlign: 'center', padding: 12 }}>
                  <div style={{ fontSize: 11, color: '#888', marginBottom: 8 }}>
                    Make sure Ollama is running:<br />
                    <code style={{ background: '#1a1a2e', padding: '2px 6px', borderRadius: 3 }}>ollama serve</code>
                  </div>
                  <button
                    onClick={() => {
                      setScanning(true);
                      setOllamaModels([]);
                      setTimeout(() => {
                        const urls = ['http://127.0.0.1:11434/api/tags', 'http://localhost:11434/api/tags', '/api/config/ollama-models'];
                        Promise.allSettled(urls.map(url => fetch(url, { signal: AbortSignal.timeout(3000) }).then(r => r.ok ? r.json() : null)))
                          .then(results => {
                            for (const r of results) {
                              if (r.status === 'fulfilled' && r.value) {
                                const names = (r.value.models || []).map((m: any) => m.name);
                                if (names.length > 0) { setOllamaModels(names); setScanning(false); return; }
                              }
                            }
                            setScanning(false);
                          });
                      }, 500);
                    }}
                    style={{
                      padding: '6px 16px', border: '1px solid #60a5fa', borderRadius: 4,
                      background: 'rgba(96,165,250,0.1)', color: '#60a5fa', cursor: 'pointer', fontSize: 11,
                    }}
                  >
                    🔄 Scan Again
                  </button>
                </div>
              )}
            </>
          ) : (
            <>
              <label className="settings-field">
                <span>Provider</span>
                <select value={provider} onChange={(e) => setProvider(e.target.value)}>
                  <option value="openai">OpenAI</option>
                  <option value="anthropic">Anthropic</option>
                </select>
              </label>
              <label className="settings-field">
                <span>API Key</span>
                <input type="password" value={apiKey} onChange={(e) => setApiKey(e.target.value)} placeholder="sk-..." />
              </label>
              <label className="settings-field">
                <span>Model</span>
                <input type="text" value={model} onChange={(e) => setModel(e.target.value)}
                  placeholder={provider === 'openai' ? 'gpt-4o, gpt-4, ...' : 'claude-sonnet-4-20250514, ...'} />
              </label>
              {provider === 'openai' && (
                <label className="settings-field">
                  <span>Base URL</span>
                  <input type="text" value={baseUrl} onChange={(e) => setBaseUrl(e.target.value)} placeholder="https://api.openai.com/v1" />
                </label>
              )}
              <button
                onClick={handleCloudConfig}
                style={{
                  width: '100%', marginTop: 8, padding: '8px 0', border: '1px solid #60a5fa', borderRadius: 4,
                  background: 'rgba(96,165,250,0.1)', color: '#60a5fa', cursor: 'pointer', fontSize: 12, fontWeight: 500,
                }}
              >
                Apply Cloud Config
              </button>
            </>
          )}

          {status && <div className={`settings-status ${statusType}`} style={{ marginTop: 8 }}>{status}</div>}
        </div>

        <div className="settings-modal-footer">
          <button className="settings-test-btn" onClick={handleTestConnection}>🔌 Test Connection</button>
          <button className="settings-save-btn" onClick={() => applyConfig(provider, apiKey, model, baseUrl)}>Save</button>
        </div>
      </div>
    </div>
  );
}

function TtsSettingsPanel({ onClose }: { onClose: () => void }) {
