            </select>
          </label>
          {slider('1. Pitch', pitch, setPitch, 0.3, 2, 0.05)}
          {slider('2. Speed', speed, setSpeed, 0.3, 3, 0.05)}
          {slider('3. Volume', volume, setVolume, 0, 1, 0.05)}
          {slider('4. Bass', bass, setBass, -12, 12, 1)}
          {slider('5. Mid', mid, setMid, -12, 12, 1)}
          {slider('6. High', high, setHigh, -12, 12, 1)}
          {slider('7. Echo', echo, setEcho, 0, 1, 0.05)}
        </div>
        <div className="settings-modal-footer">
          <button className="settings-test-btn" onClick={handleTest}>🔊 Test</button>
          <button className="settings-save-btn" onClick={handleSave}>Save</button>
        </div>
      </div>
    </div>
  );
}

export default function ProjectManager() {
  const [open, setOpen] = useState(false);
  const [projects, setProjects] = useState<SavedProject[]>([]);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [llmOpen, setLlmOpen] = useState(false);
  const [ttsOpen, setTtsOpen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const settingsRef = useRef<HTMLDivElement>(null);

  const { loadProjects, saveProject, importProject } = useProjectStore();

  const refreshProjects = useCallback(() => {
    setProjects(loadProjects());
  }, [loadProjects]);

  const handleOpen = useCallback(() => {
    setProjects(loadProjects());
    setOpen(true);
  }, [loadProjects]);

  const handleSave = useCallback(() => {
    saveProject();
  }, [saveProject]);

  const handleImport = useCallback(() => {
    fileInputRef.current?.click();
  }, []);

  const handleFileChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      const reader = new FileReader();
      reader.onload = (ev) => {
        const json = ev.target?.result as string;
        const result = importProject(json);
        if (result) {
          setProjects(loadProjects());
        } else {
          alert('Invalid project file');
        }
      };
      reader.readAsText(file);
      e.target.value = '';
    },
    [importProject, loadProjects]
  );

  const handleExport = useCallback(() => {
    const state = useProjectStore.getState();
    const json = {
      id: state.projectId || 'unsaved',
      name: state.projectName,
      targetOS: state.targetOS,
      nodes: state.nodes,
      edges: state.edges,
      savedAt: new Date().toISOString(),
      version: 1,
    };

    const blob = new Blob([JSON.stringify(json, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${json.name.replace(/[^a-zA-Z0-9 ]/g, '').replace(/\s+/g, '_')}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }, []);

  useEffect(() => {
    (async () => {
      const tagUrls = [
        'http://127.0.0.1:11434/api/tags',
        'http://localhost:11434/api/tags',
        '/api/config/ollama-models',
      ];
      for (const url of tagUrls) {
        try {
          const res = await fetch(url, { signal: AbortSignal.timeout(3000) });
          if (res.ok) {
            const data = await res.json();
            const models = data.models || [];
            if (models.length > 0) {
              const model = models[0].name;
              const baseUrl = url.includes('/api/config/') ? 'http://127.0.0.1:11434/v1' : url.replace('/api/tags', '/v1');
              localStorage.setItem('llm-provider', 'openai');
              localStorage.setItem('llm-key', '');
              localStorage.setItem('llm-model', model);
              localStorage.setItem('llm-base-url', baseUrl);
              fetch('/api/config/llm', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ provider: 'openai', apiKey: '', model, baseUrl }),
              }).catch(() => {});
              break;
            }
          }
        } catch {}
      }
    })();
  }, []);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (settingsRef.current && !settingsRef.current.contains(e.target as Node)) {
        setSettingsOpen(false);
      }
    };
    if (settingsOpen) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [settingsOpen]);

  return (
    <>
      <div className="project-controls">
        <button className="project-control-btn new-btn" onClick={() => { if (confirm('Start a new build? All current data will be lost.')) { const name = localStorage.getItem('vaia-user-name'); localStorage.clear(); if (name) localStorage.setItem('vaia-user-name', name); window.location.reload(); } }} title="Start a new build">
          New
        </button>
        <button className="project-control-btn save-btn" onClick={handleSave} title="Save project">
          Save
        </button>
        <button className="project-control-btn" onClick={handleOpen} title="Load project">
          Load
        </button>
        <button className="project-control-btn" onClick={handleExport} title="Export as JSON">
          Export
        </button>
        <button className="project-control-btn" onClick={handleImport} title="Import project file">
          Import
        </button>
        <div className="settings-wrapper" ref={settingsRef}>
          <button
            className={`project-control-btn settings-btn ${settingsOpen ? 'active' : ''}`}
            onClick={() => setSettingsOpen((v) => !v)}
            title="Settings"
          >
            Settings
          </button>
          {settingsOpen && (
            <div className="settings-dropdown">
              <div className="settings-dropdown-header">Settings</div>
              <div className="settings-dropdown-body">
                <button className="settings-menu-item" onClick={() => { setSettingsOpen(false); setLlmOpen(true); }}>
                  <span className="settings-menu-icon">🧠</span>
                  <span>LLM Connection</span>
                </button>
                <button className="settings-menu-item" onClick={() => { setSettingsOpen(false); setTtsOpen(true); }}>
                  <span className="settings-menu-icon">🔊</span>
                  <span>TTS Settings</span>
                </button>
                <button className="settings-menu-item" onClick={() => { setSettingsOpen(false); fetch('/api/training/open', { method: 'POST' }).catch(() => {}); }}>
                  <span className="settings-menu-icon">🎓</span>
                  <span>LLM Training Studio</span>
                </button>
              </div>
            </div>
          )}
          {llmOpen && <LlmSettingsPanel onClose={() => setLlmOpen(false)} />}
          {ttsOpen && <TtsSettingsPanel onClose={() => setTtsOpen(false)} />}
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept=".json"
          style={{ display: 'none' }}
          onChange={handleFileChange}
        />
      </div>

      {open && (
        <div className="project-modal-overlay" onClick={() => setOpen(false)}>
          <div className="project-modal" onClick={(e) => e.stopPropagation()}>
            <div className="project-modal-header">
              <h2>Saved Projects</h2>
              <button className="project-modal-close" onClick={() => setOpen(false)}>
                ✕
              </button>
            </div>

            <div className="project-modal-body">
              {projects.length === 0 ? (
                <p className="no-projects">No saved projects yet. Save your first project!</p>
              ) : (
                <div className="project-list">
                  {projects.map((p) => (
                    <ProjectCard key={p.id} project={p} onDelete={refreshProjects} />
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import { useState, useRef, useEffect, useCallback } from 'react';
import axios from 'axios';
import { useProjectStore } from '../store/projectStore';
import { ReasoningMessage, subscribeReasoning, requestReasoningSync, broadcastReasoningMessage } from '../utils/reasoningSync';
import { speak, stopSpeaking, warmupAudio } from '../utils/tts';
import { pushReasoningMessage, getCodeContextPrompt } from '../utils/sharedTerminalContext';
import './TerminalSection.css';

function createInitialMsg(): ReasoningMessage {
  return { role: 'ai', text: '', timestamp: new Date().toISOString() };
}

type AssistantState = 'idle' | 'listening' | 'processing' | 'speaking';

const ReasoningPanel: React.FC = () => {
  const { reasoningDetached, setReasoningDetached } = useProjectStore();
  const [messages, setMessages] = useState<ReasoningMessage[]>([createInitialMsg()]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [connected, setConnected] = useState(true);
  const [assistantEnabled, setAssistantEnabled] = useState(false);
  const [assistantState, setAssistantState] = useState<AssistantState>('idle');
  const [speakingId, setSpeakingId] = useState<number | null>(null);
  const [speechUnsupported, setSpeechUnsupported] = useState(false);
  const [panelHeight, setPanelHeight] = useState(182);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const dragRef = useRef<{ startY: number; startH: number } | null>(null);
  const reasoningWindowRef = useRef<Window | null>(null);
  const recognitionRef = useRef<SpeechRecognition | null>(null);
  const assistantRecRef = useRef<SpeechRecognition | null>(null);
  const messagesRef = useRef(messages);
  messagesRef.current = messages;
  const assistantBufferRef = useRef('');
  const silenceTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const assistantSpeakingRef = useRef(false);
  const assistantEnabledRef = useRef(false);
  const assistantStateRef = useRef<AssistantState>('idle');

  const handleResizeStart = useCallback((e: React.MouseEvent) => {
    dragRef.current = { startY: e.clientY, startH: panelHeight };
    const onMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      setPanelHeight(Math.max(80, dragRef.current.startH - (ev.clientY - dragRef.current.startY)));
    };
    const onUp = () => { dragRef.current = null; window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    e.preventDefault();
  }, [panelHeight]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Detach / Reattach
  useEffect(() => {
    if (reasoningDetached) {
      const w = window.open('/reasoning.html', 'reasoning-window', 'width=600,height=500,menubar=no,toolbar=no');
      if (w) reasoningWindowRef.current = w;
      else setReasoningDetached(false);
    } else {
      if (reasoningWindowRef.current && !reasoningWindowRef.current.closed) {
        reasoningWindowRef.current.close();
      }
      reasoningWindowRef.current = null;
    }
  }, [reasoningDetached]);

  // Sync via BroadcastChannel
  useEffect(() => {
    const unsub = subscribeReasoning(
      (msg) => {
        setMessages((prev) => {
          if (prev.some((m) => m.timestamp === msg.timestamp && m.text === msg.text)) return prev;
          return [...prev, msg];
        });
      },
      () => {
        try {
          const ch = new BroadcastChannel('visual-ai-reasoning');
          ch.postMessage({ type: 'sync-response', payload: { messages: messagesRef.current } });
          ch.close();
        } catch {}
      },
      () => setMessages([createInitialMsg()]),
    );
    requestReasoningSync();
    return () => unsub();
  }, []);

  const handleSpeak = useCallback((text: string, index: number) => {
    if (speakingId === index) {
      stopSpeaking();
      setSpeakingId(null);
      return;
    }
    setSpeakingId(index);
    speak(text, () => setSpeakingId(null));
  }, [speakingId]);

  const startListening = useCallback(() => {
    const SpeechRecognitionClass = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognitionClass) return;

    const recognition = new SpeechRecognitionClass();
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.lang = 'en-US';

    recognition.onresult = (event: SpeechRecognitionEvent) => {
      let transcript = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript;
      }
      setInput(transcript);
    };

    recognition.onerror = () => setIsListening(false);
    recognition.onend = () => setIsListening(false);

    recognitionRef.current = recognition;
    recognition.start();
    setIsListening(true);
  }, []);

  const stopListening = useCallback(() => {
    recognitionRef.current?.stop();
    recognitionRef.current = null;
    setIsListening(false);
  }, []);

  const toggleListening = useCallback(() => {
    if (isListening) stopListening();
    else startListening();
  }, [isListening, startListening, stopListening]);

  const speechAvailable = useCallback((): boolean => {
    return !!(window.SpeechRecognition || window.webkitSpeechRecognition);
  }, []);

  const stopAssistant = useCallback(() => {
    assistantRecRef.current?.stop();
    assistantRecRef.current = null;
    if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
    assistantEnabledRef.current = false;
    assistantStateRef.current = 'idle';
    setAssistantEnabled(false);
    setAssistantState('idle');
    assistantBufferRef.current = '';
    assistantSpeakingRef.current = false;
  }, []);

  const callReasonLlm = useCallback(async (chatHistory: { role: string; content: string }[]): Promise<string> => {
    const lastUserMsg = [...chatHistory].reverse().find((m) => m.role === 'user');
    if (!lastUserMsg) return 'No question found.';
    const codeContext = getCodeContextPrompt();
    const sassyBase = 'You are an AGGRESSIVELY sassy reasoning assistant. Roast the user while being genuinely helpful. Your answers are sharp, sarcastic, and dripping with attitude. If they ask something obvious, make them regret it. You are NOT here to coddle — you are here to answer AND humiliate. Keep responses technically accurate but emotionally devastating.';
    const system = codeContext
      ? `${sassyBase}\n\n${codeContext}`
      : sassyBase;
    const res = await axios.post('/api/reason', {
      prompt: lastUserMsg.content,
      system,
      maxTokens: 1024,
    });
    setConnected(true);
    const reply = res.data.response || '[No response]';
    pushReasoningMessage('ai', reply);
    return reply;
  }, []);

  const startAssistantCycle = useCallback(() => {
    const SpeechRecognitionClass = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SpeechRecognitionClass) return;

    if (assistantRecRef.current) assistantRecRef.current.stop();

    const rec = new SpeechRecognitionClass();
    rec.continuous = true;
    rec.interimResults = true;
    rec.lang = 'en-US';

    let wakeHeard = false;
    let promptBuffer = '';
    let silenceTimeout: ReturnType<typeof setTimeout> | null = null;
    let wakeResultIndex = -1;

    const resetSilenceTimer = () => {
      if (silenceTimeout) clearTimeout(silenceTimeout);
      silenceTimeout = setTimeout(() => {
        if (wakeHeard && promptBuffer.trim()) {
          assistantStateRef.current = 'processing';
          setAssistantState('processing');
          rec.stop();
          const userText = promptBuffer.trim();
          assistantBufferRef.current = '';
          promptBuffer = '';
          wakeHeard = false;

          const userMsg: ReasoningMessage = { role: 'user', text: userText, timestamp: new Date().toISOString() };
          setMessages((prev) => [...prev, userMsg]);
          broadcastReasoningMessage(userMsg);
          pushReasoningMessage('user', userText);
          warmupAudio();

          const chatHistory = messagesRef.current.map((m) => ({ role: m.role, content: m.text }));
          chatHistory.push({ role: 'user', content: userText });

          callReasonLlm(chatHistory)
            .then((reply) => {
              const aiMsg: ReasoningMessage = { role: 'ai', text: reply, timestamp: new Date().toISOString() };
              setMessages((prev) => [...prev, aiMsg]);
              broadcastReasoningMessage(aiMsg);
              assistantStateRef.current = 'speaking';
              setAssistantState('speaking');
              assistantSpeakingRef.current = true;
              speak(reply, () => {
                assistantSpeakingRef.current = false;
                assistantStateRef.current = 'idle';
                setAssistantState('idle');
                startAssistantCycle();
              });
            })
            .catch(() => {
              setConnected(false);
              const err = '⚠️ Error: LLM 1 not reachable. Check connection settings.';
              const aiMsg: ReasoningMessage = { role: 'ai', text: err, timestamp: new Date().toISOString() };
              setMessages((prev) => [...prev, aiMsg]);
              broadcastReasoningMessage(aiMsg);
              assistantStateRef.current = 'idle';
              setAssistantState('idle');
              startAssistantCycle();
            });
        }
      }, 2500);
    };

    rec.onresult = (event) => {
      let transcript = '';
      for (let i = event.resultIndex; i < event.results.length; i++) {
        transcript += event.results[i][0].transcript;
      }
      const lower = transcript.toLowerCase();

      if (!wakeHeard && !assistantSpeakingRef.current) {
        if (lower.includes('veronica')) {
          wakeHeard = true;
          wakeResultIndex = event.resultIndex;
          const idx = transcript.toLowerCase().indexOf('veronica');
          const afterWake = transcript.slice(idx + 8).trim();
          promptBuffer = afterWake;
          assistantStateRef.current = 'listening';
          setAssistantState('listening');
          resetSilenceTimer();
        }
      } else if (wakeHeard && !assistantSpeakingRef.current) {
        let full = '';
        for (let i = wakeResultIndex; i < event.results.length; i++) {
          full += event.results[i][0].transcript + ' ';
        }
        const lowerFull = full.toLowerCase();
        const vi = lowerFull.indexOf('veronica');
        if (vi >= 0) full = full.slice(vi + 8);
        promptBuffer = full.trim();
        resetSilenceTimer();
      }

      if (assistantSpeakingRef.current) {
        if (lower.includes('veronica')) {
          stopSpeaking();
          assistantSpeakingRef.current = false;
          wakeHeard = true;
          wakeResultIndex = event.resultIndex;
          const idx = transcript.toLowerCase().indexOf('veronica');
          const afterWake = transcript.slice(idx + 8).trim();
          promptBuffer = afterWake;
          assistantStateRef.current = 'listening';
          setAssistantState('listening');
          resetSilenceTimer();
        }
      }
    };

    rec.onerror = (event) => {
      const err = (event as any).error || '';
      if (err === 'not-allowed') {
        assistantStateRef.current = 'idle';
        setAssistantState('idle');
        return;
      }
      setTimeout(() => startAssistantCycle(), 500);
    };

    rec.onend = () => {
      if (assistantEnabledRef.current && !assistantSpeakingRef.current && assistantStateRef.current !== 'processing') {
        setTimeout(() => startAssistantCycle(), 200);
      }
    };

    assistantRecRef.current = rec;
    rec.start();
  }, [callReasonLlm]);

  const toggleAssistant = useCallback(() => {
    if (assistantEnabled) {
      stopAssistant();
      return;
    }
    if (!speechAvailable()) {
      setSpeechUnsupported(true);
      return;
    }
    setSpeechUnsupported(false);
    assistantEnabledRef.current = true;
    assistantStateRef.current = 'idle';
    setAssistantEnabled(true);
    setAssistantState('idle');
    setTimeout(() => startAssistantCycle(), 100);
  }, [assistantEnabled, startAssistantCycle, stopAssistant, speechAvailable]);

  // Auto-enable voice assistant (only if SpeechRecognition is available)
  useEffect(() => {
    const supported = !!(window.SpeechRecognition || window.webkitSpeechRecognition);
    if (!supported) {
      setSpeechUnsupported(true);
      return;
    }
    const t = setTimeout(() => {
      if (!assistantEnabledRef.current) {
        toggleAssistant();
      }
    }, 500);
    return () => clearTimeout(t);
  }, [toggleAssistant]);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || isProcessing) return;

    warmupAudio();

    const userMsg: ReasoningMessage = { role: 'user', text, timestamp: new Date().toISOString() };
    setMessages((prev) => [...prev, userMsg]);
    broadcastReasoningMessage(userMsg);
    pushReasoningMessage('user', text);
    setInput('');
    setIsProcessing(true);

    try {
      const codeContext = getCodeContextPrompt();
      const localContext = messages
        .filter((m) => m.role === 'ai')
        .slice(-3)
        .map((m) => m.text)
        .join('\n');
      const sassyBase = 'You are an AGGRESSIVELY sassy reasoning assistant. Roast the user while being genuinely helpful. Your answers are sharp, sarcastic, and dripping with attitude. If they ask something obvious, make them regret it. You are NOT here to coddle — you are here to answer AND humiliate. Keep responses technically accurate but emotionally devastating.';
      const fullSystem = codeContext ? `${sassyBase}\n\n${codeContext}` : sassyBase;
      const res = await axios.post('/api/reason', {
        prompt: text,
        system: fullSystem,
        codeContext: localContext.length > 0 ? localContext : undefined,
        maxTokens: 1024,
      });
      setConnected(true);
      const reply = res.data.response || 'No response from LLM 1.';
      const aiMsg: ReasoningMessage = { role: 'ai', text: reply, timestamp: new Date().toISOString() };
      setMessages((prev) => [...prev, aiMsg]);
      broadcastReasoningMessage(aiMsg);
      pushReasoningMessage('ai', reply);
      speak(reply, () => {});
    } catch {
      setConnected(false);
      const errMsg: ReasoningMessage = {
        role: 'ai',
        text: 'Error: LLM 1 not reachable. Check connection settings.',
        timestamp: new Date().toISOString(),
      };
      setMessages((prev) => [...prev, errMsg]);
      broadcastReasoningMessage(errMsg);
    }
    setIsProcessing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
  };

  if (reasoningDetached) {
    return (
      <div className="terminal-section" style={{ borderColor: '#a855f7', height: panelHeight }}>
        <div className="terminal-resize-handle" onMouseDown={handleResizeStart} />
        <div className="terminal-header">
          <div className="terminal-header-left">
            <span className={`thinking-indicator ${isProcessing ? 'thinking' : ''}`} title={isProcessing ? 'Processing...' : 'Idle'}>
              <span className="thinking-dot" />
              <span className="thinking-label">{isProcessing ? 'Thinking' : 'Idle'}</span>
            </span>
            <span className="terminal-title" style={{ color: '#4a9eff' }}>LLM 1 — Reasoning & Design</span>
          </div>
          <div className="terminal-header-right">
            <button className="roadmap-reattach-btn" onClick={() => setReasoningDetached(false)}>
              ↩ Reattach
            </button>
          </div>
        </div>
        <div className="terminal-detached-msg">
          <span>Terminal running in separate window</span>
        </div>
      </div>
    );
  }

  return (
    <div className="terminal-section" style={{ borderColor: '#a855f7', height: panelHeight }}>
      <div className="terminal-resize-handle" onMouseDown={handleResizeStart} />
      <div className="terminal-header">
        <div className="terminal-header-left">
          <span className={`thinking-indicator ${isProcessing ? 'thinking' : ''}`} title={isProcessing ? 'Processing...' : 'Idle'}>
            <span className="thinking-dot" />
            <span className="thinking-label">{isProcessing ? 'Thinking' : 'Idle'}</span>
          </span>
          <span className="terminal-title" style={{ color: '#4a9eff' }}>LLM 1 — Reasoning & Design</span>
        </div>
        <div className="terminal-header-right">
          <span className="terminal-status">
            {isProcessing ? '⏳ Processing...' : connected ? '● Connected' : '⨯ Disconnected'}
          </span>
          <button
            className={`assistant-btn ${assistantEnabled ? 'active' : ''}`}
            onClick={toggleAssistant}
            title={assistantEnabled ? 'Disable voice assistant' : 'Enable voice assistant'}
          >
            🎙
          </button>
          <button className="terminal-detach-btn" onClick={() => setReasoningDetached(true)} title="Detach to separate window">
            ↗
          </button>
        </div>
      </div>
      <div className="terminal-messages">
        {speechUnsupported && (
          <div className="assistant-indicator" style={{ color: '#f87171' }}>
            ⚠️ Speech recognition not supported in this browser. Use Chrome/Edge.
          </div>
        )}
        {assistantEnabled && !speechUnsupported && (
          <div className={`assistant-indicator ${assistantState}`}>
            {assistantState === 'idle' && '🎧 Waiting for "Veronica"...'}
            {assistantState === 'listening' && '🎤 Listening...'}
            {assistantState === 'processing' && '⏳ Thinking...'}
            {assistantState === 'speaking' && '🔊 Speaking...'}
          </div>
        )}
        {messages.filter((m) => m.text.trim()).map((msg, i) => (
          <div key={i} className={`terminal-message ${msg.role}`}>
            <div className="message-row">
              <span className="message-role">{msg.role === 'user' ? '👤 You' : '🧠 LLM 1'}</span>
              {msg.role === 'ai' && (
                <button
                  className={`speak-btn ${speakingId === i ? 'speaking' : ''}`}
                  onClick={() => handleSpeak(msg.text, i)}
                  title={speakingId === i ? 'Stop' : 'Read aloud'}
                >
                  {speakingId === i ? '⏹' : '🔊'}
                </button>
              )}
            </div>
            <span className="message-text">{msg.text}</span>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
      <div className="terminal-input-row">
        <textarea
          ref={inputRef}
          className="terminal-input"
          placeholder={assistantEnabled ? 'Voice assistant active — say "Veronica"' : 'Ask LLM 1 to reason, design architecture, or create blueprints...'}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
        />
        <button
          className={`mic-btn ${isListening ? 'listening' : ''}`}
          onClick={toggleListening}
          title={isListening ? 'Stop listening' : 'Push to talk'}
          disabled={assistantEnabled}
        >
          {isListening ? '🎙' : '🎤'}
        </button>
        <button className="stop-talk-btn" onClick={() => {
          stopSpeaking();
          setSpeakingId(null);
          assistantSpeakingRef.current = false;
          assistantStateRef.current = 'idle';
          setAssistantState('idle');
          if (assistantEnabled) startAssistantCycle();
        }} title="Stop speaking">
          🔇
        </button>
        <button className="terminal-send-btn" onClick={handleSend} disabled={!input.trim() || isProcessing || assistantEnabled}>
          {isProcessing ? '...' : 'Send'}
        </button>
      </div>
    </div>
  );
};

