import { useState, useRef, useEffect, useCallback } from 'react';
import { useProjectStore } from '../store/projectStore';
import { broadcastMessage, subscribeTerminal, requestSync } from '../utils/terminalSync';
import { pushCodeMessage, getReasoningContextPrompt } from '../utils/sharedTerminalContext';
import './TerminalSection.css';

interface Message {
  role: 'user' | 'ai';
  text: string;
  timestamp: Date;
}

function createInitialMessage(): Message {
  return {
    role: 'ai' as const,
    text: '',
    timestamp: new Date(),
  };
}

export default function TerminalSection() {
  const { terminalDetached, setTerminalDetached, thinking, progress, isGenerating } = useProjectStore();
  const [messages, setMessages] = useState<Message[]>([createInitialMessage()]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [panelHeight, setPanelHeight] = useState(182);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const dragRef = useRef<{ startY: number; startH: number } | null>(null);
  const messagesRef = useRef(messages);
  messagesRef.current = messages;
  const terminalWindowRef = useRef<Window | null>(null);

  const handleResizeStart = useCallback((e: React.MouseEvent) => {
    dragRef.current = { startY: e.clientY, startH: panelHeight };
    const onMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      const dy = ev.clientY - dragRef.current.startY;
      setPanelHeight(Math.max(80, dragRef.current.startH - dy));
    };
    const onUp = () => { dragRef.current = null; window.removeEventListener('mousemove', onMove); window.removeEventListener('mouseup', onUp); };
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
    e.preventDefault();
  }, [panelHeight]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  useEffect(() => {
    if (terminalDetached) {
      const w = window.open('/terminal.html', 'terminal-window', 'width=600,height=500,menubar=no,toolbar=no');
      if (w) terminalWindowRef.current = w;
      else setTerminalDetached(false);
    } else {
      if (terminalWindowRef.current && !terminalWindowRef.current.closed) {
        terminalWindowRef.current.close();
      }
      terminalWindowRef.current = null;
    }
  }, [terminalDetached, setTerminalDetached]);

  useEffect(() => {
    const unsub = subscribeTerminal(
      (msg) => {
        setMessages((prev) => {
          if (prev.some((m) => m.role === msg.role && m.text === msg.text)) return prev;
          const m: Message = { role: msg.role, text: msg.text, timestamp: new Date(msg.timestamp) };
          return [...prev, m];
        });
      },
      () => {
        const msgs = messagesRef.current.map((m) => ({
          role: m.role,
          text: m.text,
          timestamp: m.timestamp instanceof Date ? m.timestamp.toISOString() : String(m.timestamp),
        }));
        try {
          const ch = new BroadcastChannel('visual-ai-terminal');
          ch.postMessage({ type: 'sync-response', payload: { messages: msgs } });
          ch.close();
        } catch {}
      },
      () => {
        setMessages([createInitialMessage()]);
      }
    );
    requestSync();
    return unsub;
  }, []);

  async function callLlm(messages: { role: string; content: string }[]): Promise<string> {
    const provider = localStorage.getItem('llm-provider') || 'openai';
    const apiKey = localStorage.getItem('llm-key') || '';
    let model = localStorage.getItem('llm-model') || '';
    let baseUrl = localStorage.getItem('llm-base-url') || '';

    if (!model && provider !== 'anthropic') {
      return "I can't find a suitable chat model. Please install a conversational model (e.g. `ollama pull llama3.2`) or configure an API provider in Settings.";
    }

    if (provider === 'anthropic') {
      const key = apiKey;
      const m = model || 'claude-sonnet-4-20250514';
      const res = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': key,
          'anthropic-version': '2023-06-01',
        },
        body: JSON.stringify({
          model: m,
          max_tokens: 1024,
          system: 'You are an expert AI code architect and friendly conversational assistant. You help users build software projects by understanding their needs and guiding them through the process. Keep responses clear, helpful, and conversational. Never output raw code blocks unless specifically asked for a code example.\n\n' + getReasoningContextPrompt(),
          messages: messages.map((m) => ({ role: m.role === 'ai' ? 'assistant' : 'user', content: m.content })),
        }),
        signal: AbortSignal.timeout(120000),
      });
      if (!res.ok) throw new Error(`Anthropic HTTP ${res.status}: ${await res.text().catch(() => '')}`);
      const data = await res.json();
      return data.content?.[0]?.text || '[No response]';
    }

    const url = (baseUrl || 'https://api.openai.com/v1').replace(/\/+$/, '') + '/chat/completions';
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (apiKey) headers['Authorization'] = 'Bearer ' + apiKey;
    const res = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        model: model || 'gpt-4',
        messages: [
          { role: 'system', content: 'You are an expert AI code architect and friendly conversational assistant. You help users build software projects by understanding their needs and guiding them through the process. Keep responses clear, helpful, and conversational. Never output raw code blocks unless specifically asked for a code example.\n\n' + getReasoningContextPrompt() },
          ...messages.map((m) => ({ role: m.role === 'ai' ? 'assistant' : 'user', content: m.content })),
        ],
        max_tokens: 1024,
      }),
      signal: AbortSignal.timeout(120000),
    });
    if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
    const data = await res.json();
    const content = data.choices?.[0]?.message?.content || '[No response]';
    return content;
  }

  const handleSend = async () => {
    const text = input.trim();
    if (!text || isProcessing) return;

    const userMsg: Message = { role: 'user', text, timestamp: new Date() };
    setMessages((prev) => [...prev, userMsg]);
    broadcastMessage({ role: 'user', text, timestamp: new Date().toISOString() });
    pushCodeMessage('user', text);
    setInput('');
    setIsProcessing(true);

    try {
      const chatHistory = messagesRef.current.map((m) => ({ role: m.role, content: m.text }));
      chatHistory.push({ role: 'user', content: text });
      const reply = await callLlm(chatHistory);
      const aiMsg: Message = { role: 'ai', text: reply, timestamp: new Date() };
      setMessages((prev) => [...prev, aiMsg]);
      broadcastMessage({ role: 'ai', text: reply, timestamp: new Date().toISOString() });
      pushCodeMessage('ai', reply);
    } catch (e: any) {
      const errMsg = `⚠️ Error: ${e?.message || 'LLM request failed'}`;
      const aiMsg: Message = { role: 'ai', text: errMsg, timestamp: new Date() };
      setMessages((prev) => [...prev, aiMsg]);
      broadcastMessage({ role: 'ai', text: errMsg, timestamp: new Date().toISOString() });
    }

    setIsProcessing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleDetach = () => setTerminalDetached(true);
  const handleReattach = () => setTerminalDetached(false);

  if (terminalDetached) {
    return (
      <div className="terminal-section" style={{ height: panelHeight }}>
        <div className="terminal-resize-handle" onMouseDown={handleResizeStart} />
        <div className="terminal-header">
          <div className="terminal-header-left">
            <span className={`thinking-indicator ${thinking ? 'thinking' : ''}`} title={thinking ? 'AI is working...' : 'Idle'}>
              <span className="thinking-dot" />
              <span className="thinking-label">{thinking ? 'Thinking' : 'Idle'}</span>
            </span>
            <span className="terminal-title">Code Builder</span>
          </div>
          <div className="terminal-header-right">
            {isGenerating && (
              <div className="progress-bar-container" title={`${Math.round(progress)}% complete`}>
                <div className="progress-bar-fill" style={{ width: `${progress}%` }} />
                <span className="progress-bar-text">{Math.round(progress)}%</span>
              </div>
            )}
            <button className="roadmap-reattach-btn" onClick={handleReattach}>
              ↩ Reattach
            </button>
          </div>
        </div>
        <div className="terminal-detached-msg">
          <span>Terminal running in separate window</span>
        </div>
      </div>
    );
  }

  return (
    <div className="terminal-section" style={{ height: panelHeight }}>
      <div className="terminal-resize-handle" onMouseDown={handleResizeStart} />
      <div className="terminal-header">
        <div className="terminal-header-left">
          <span className={`thinking-indicator ${thinking ? 'thinking' : ''}`} title={thinking ? 'AI is working...' : 'Idle'}>
            <span className="thinking-dot" />
            <span className="thinking-label">{thinking ? 'Thinking' : 'Idle'}</span>
          </span>
          <span className="terminal-title">Code Builder</span>
        </div>
        <div className="terminal-header-right">
          {isGenerating && (
            <div className="progress-bar-container" title={`${Math.round(progress)}% complete`}>
              <div className="progress-bar-fill" style={{ width: `${progress}%` }} />
              <span className="progress-bar-text">{Math.round(progress)}%</span>
            </div>
          )}
          <span className="terminal-status">
            {isProcessing ? '⏳ Processing...' : '● Connected'}
          </span>
          <button className="terminal-detach-btn" onClick={handleDetach} title="Open terminal in new window">
            ↗
          </button>
        </div>
      </div>
      <div className="terminal-messages">
        {messages.filter((m) => m.text.trim()).map((msg, i) => (
          <div key={i} className={`terminal-message ${msg.role}`}>
            <div className="message-row">
              <span className="message-role">{msg.role === 'user' ? '👤 You' : '🤖 AI'}</span>
            </div>
            <span className="message-text">{msg.text}</span>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
      <div className="terminal-input-row">
        <textarea
          ref={inputRef}
          className="terminal-input"
          placeholder="Ask the AI architect something..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
        />
        <button className="terminal-send-btn" onClick={handleSend} disabled={!input.trim() || isProcessing}>
          Send
        </button>
      </div>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { TerminalMessage, subscribeTerminal, requestSync, broadcastMessage } from '../utils/terminalSync';
import './TerminalSection.css';

function createInitialMsg(): TerminalMessage {
  return {
    role: 'ai',
    text: '',
    timestamp: new Date().toISOString(),
  };
}

export default function TerminalWindow() {
  const [messages, setMessages] = useState<TerminalMessage[]>([createInitialMsg()]);
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [connected, setConnected] = useState(false);
  const [thinking, setThinking] = useState(false);
  const [progress, setProgress] = useState(0);
  const bottomRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const messagesRef = useRef(messages);
  messagesRef.current = messages;

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  function replyWithSync(msgs: TerminalMessage[]) {
    try {
      const ch = new BroadcastChannel('visual-ai-terminal');
      ch.postMessage({ type: 'sync-response', payload: { messages: msgs } });
      ch.close();
    } catch {}
  }

  useEffect(() => {
    const unsub = subscribeTerminal(
      (msg) => {
        setMessages((prev) => {
          if (prev.some((m) => m.timestamp === msg.timestamp && m.text === msg.text)) return prev;
          return [...prev, msg];
        });
      },
      () => {
        replyWithSync(messagesRef.current);
      },
      () => {
        setMessages([createInitialMsg()]);
      }
    );
    requestSync();

    const statusCh = new BroadcastChannel('visual-ai-status');
    statusCh.onmessage = (e) => {
      if (e.data.type === 'status-update') {
        setThinking(e.data.payload.thinking);
        setProgress(e.data.payload.progress);
      }
    };

    setTimeout(() => setConnected(true), 500);
    return () => {
      unsub();
      statusCh.close();
    };
  }, []);

  const handleSend = async () => {
    const text = input.trim();
    if (!text || isProcessing) return;
    const userMsg: TerminalMessage = { role: 'user', text, timestamp: new Date().toISOString() };
    setMessages((prev) => [...prev, userMsg]);
    broadcastMessage(userMsg);
    setInput('');
    setIsProcessing(true);
    const aiMsg: TerminalMessage = {
      role: 'ai',
      text: 'I understand you want to build something. Try dragging nodes onto the canvas and describing each one in plain English. Then click "Generate Code" to let me build it layer by layer!',
      timestamp: new Date().toISOString(),
    };
    setTimeout(() => {
      setMessages((prev) => [...prev, aiMsg]);
      broadcastMessage(aiMsg);
      setIsProcessing(false);
    }, 800);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSend(); }
  };

  return (
    <div className="terminal-window-root">
      <div className="terminal-window-header">
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          <span className={`thinking-indicator ${thinking ? 'thinking' : ''}`} title={thinking ? 'AI is working...' : 'Idle'}>
            <span className="thinking-dot" />
            <span className="thinking-label">{thinking ? 'Thinking' : 'Idle'}</span>
          </span>
          <h2>LLM 2 — Code Builder</h2>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
          {thinking && (
            <div className="progress-bar-container" title={`${Math.round(progress)}% complete`}>
              <div className="progress-bar-fill" style={{ width: `${progress}%` }} />
              <span className="progress-bar-text">{Math.round(progress)}%</span>
            </div>
          )}
          <span className={`conn-status ${connected ? 'connected' : ''}`}>
            {connected ? '● Connected' : '○ Connecting...'}
          </span>
        </div>
      </div>
      <div className="terminal-messages" style={{ flex: 1 }}>
        {messages.filter((m) => m.text.trim()).map((msg, i) => (
          <div key={i} className={`terminal-message ${msg.role}`}>
            <div className="message-row">
              <span className="message-role">{msg.role === 'user' ? '👤 You' : '🤖 AI'}</span>
            </div>
            <span className="message-text">{msg.text}</span>
          </div>
        ))}
        <div ref={bottomRef} />
      </div>
      <div className="terminal-input-row">
        <textarea
          ref={inputRef}
          className="terminal-input"
          placeholder="Ask the AI architect something..."
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
        />
        <button className="terminal-send-btn" onClick={handleSend} disabled={!input.trim() || isProcessing}>
          Send
        </button>
      </div>
    </div>
  );
}

import { useProjectStore } from '../store/projectStore';
import { LANGUAGE_OPTIONS, CodeLanguage, OSType } from '../types';

interface ToolbarProps {
  onGenerate: () => void;
  onExport: () => void;
  onClear: () => void;
}

export default function Toolbar({ onGenerate, onExport, onClear }: ToolbarProps) {
  const { isGenerating, generationLayer, projectName, nodes, updateNode, targetOS, setTargetOS } = useProjectStore();

  const osOptions: { value: OSType; label: string; icon: string }[] = [
    { value: 'windows', label: 'Windows', icon: '🪟' },
    { value: 'mac', label: 'Mac', icon: '🍎' },
    { value: 'ios', label: 'iOS', icon: '📱' },
    { value: 'linux', label: 'Linux', icon: '🐧' },
  ];

  const uniqueLanguages = [...new Set(nodes.map(n => (n.data as any)?.language).filter(Boolean))] as CodeLanguage[];
  const currentGlobalLang = uniqueLanguages.length === 1 ? uniqueLanguages[0] : undefined;

  const handleGlobalLanguageChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const lang = e.target.value as CodeLanguage;
    nodes.forEach((n) => {
      if (n.type !== 'master') {
        updateNode(n.id, { language: lang });
      }
    });
  };

  return (
    <div className="toolbar">
      <div className="toolbar-section">
        <span className="toolbar-label">Project: <strong>{projectName}</strong></span>
        <span className="toolbar-label">Layer: <strong>{generationLayer}/3</strong></span>
      </div>

      <div className="toolbar-section">
        <label className="toolbar-lang-label">
          <span>Language:</span>
          <select
            className="toolbar-lang-select"
            value={currentGlobalLang || 'typescript'}
            onChange={handleGlobalLanguageChange}
          >
            {LANGUAGE_OPTIONS.map((lang) => (
              <option key={lang.value} value={lang.value}>{lang.label}</option>
            ))}
          </select>
        </label>

        <div className="toolbar-os-selector">
          <span className="toolbar-label">Target OS:</span>
          <div className="os-buttons">
            {osOptions.map((os) => (
              <button
                key={os.value}
                className={`os-button ${targetOS === os.value ? 'active' : ''}`}
                onClick={() => setTargetOS(os.value)}
                title={os.label}
              >
                <span className="os-icon">{os.icon}</span>
              </button>
            ))}
          </div>
        </div>

        <button
          className="toolbar-btn generate-btn"
          onClick={onGenerate}
          disabled={isGenerating}
        >
          {isGenerating ? '⏳ Generating...' : '⚡ Generate Code'}
        </button>

        <button
          className="toolbar-btn export-btn"
          onClick={onExport}
          disabled={isGenerating}
        >
          📦 Export
        </button>

        <button
          className="toolbar-btn clear-btn"
          onClick={onClear}
        >
          🗑 Clear
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { broadcastReasoningMessage } from '../utils/reasoningSync';
import { pushReasoningMessage } from '../utils/sharedTerminalContext';
import { speak, warmupAudio } from '../utils/tts';

const USER_NAME_KEY = 'vaia-user-name';
const WELCOME_SHOWN_KEY = 'vaia-welcome-shown-';

export function getUserName(): string | null {
  return localStorage.getItem(USER_NAME_KEY);
}

function hasWelcomeBeenShown(name: string): boolean {
  return localStorage.getItem(WELCOME_SHOWN_KEY + name) === 'true';
}

function markWelcomeShown(name: string) {
  localStorage.setItem(WELCOME_SHOWN_KEY + name, 'true');
}

export function useUserName() {
  const [name, setName] = useState<string | null>(() => getUserName());
  const set = (n: string) => {
    localStorage.setItem(USER_NAME_KEY, n);
    setName(n);
    fetch('/api/user/init', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: n }),
    }).catch(() => {});
  };
  return { name, setName: set };
}

function postWelcomeMessage(name: string) {
  if (hasWelcomeBeenShown(name)) return;
  markWelcomeShown(name);

  setTimeout(() => {
    const isVirgil = name.toLowerCase() === 'virgil';
    const lines = isVirgil
      ? [
          `Hey ${name}`,
          `its the mad man`,
          `this is a project ive been working on for a few months now, but honestly I have zero people to help fine tune, much less knows how to write code.`,
          `This is a flowchart node based programming system.`,
          `User give the ai blueprint node there wanted app, etc`,
          `The llm helps the user to after filling out the first node, builds a roadmap on the canvas. User then can modify the node, pick a language they prefer. Links the nodes together.`,
          `Once user have defined what they want each node todo, they can hit generate code. The llm then builds a roadmap, to hand off to a code logic llm to build each section (node) then hand back to the reasoning llm.`,
          `To ensure there no "day dreaming" the node are written 1 by 1 from the llm. Once every code has been written out, the reasoning llm connects the dots and test the application.`,
          `Then user can output the app into a custom folder that store all projects great.`,
          `Veronica can be a bit "sassy" but it works for me lol.`,
          `This is still a huge project in progress, but slowly working it out.`,
          `Ohh the llm training is fun. Dump in training material have your own llm handy. Then send the app to work feeding the llm, and learning. Like ive said work in progress.`,
        ]
      : [
          `Welcome to Visual AI Architect, ${name}!`,
          `This is a flowchart-based visual programming system.`,
          `Start by describing your app in the blueprint node, then build out the roadmap.`,
          `When ready, hit Generate Code and the AI will build each node layer by layer.`,
          `Your projects, roadmaps, and code exports are saved to your personal workspace.`,
        ];

    const fullText = lines.join('\n');

    lines.forEach((line, i) => {
      setTimeout(() => {
        const ts = new Date().toISOString();
        const reasoningMsg = { role: 'ai' as const, text: line, timestamp: ts };
        broadcastReasoningMessage(reasoningMsg);
        pushReasoningMessage('ai', line);
      }, i * 500);
    });

    warmupAudio();
    speak(fullText);
  }, 2500);
}

export default function UserNamePrompt({ onSet }: { onSet: (name: string) => void }) {
  const [input, setInput] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    const stored = getUserName();
    if (stored) { onSet(stored); return; }
  }, []);

  const handleSubmit = async () => {
    const trimmed = input.trim();
    if (!trimmed) return;
    setSaving(true);
    localStorage.setItem(USER_NAME_KEY, trimmed);
    try {
      await fetch('/api/user/init', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: trimmed }),
      });
    } catch {}
    setSaving(false);
    onSet(trimmed);
    postWelcomeMessage(trimmed);
  };

  if (getUserName()) return null;

  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 9999,
      background: 'rgba(0,0,0,0.7)', display: 'flex',
      alignItems: 'center', justifyContent: 'center',
    }}>
      <div style={{
        background: '#1a1a2e', border: '1px solid #4a4a6a', borderRadius: 12,
        padding: '28px 32px', minWidth: 340, boxShadow: '0 12px 40px rgba(0,0,0,0.5)',
      }}>
        <h2 style={{ margin: '0 0 6px', fontSize: 18, color: '#e0e0e0' }}>Welcome to Visual AI Architect</h2>
        <p style={{ margin: '0 0 16px', fontSize: 12, color: '#888' }}>
          Enter your name to create a workspace folder for your projects.
        </p>
        <input
          autoFocus
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => { if (e.key === 'Enter') handleSubmit(); }}
          placeholder="Your name..."
          style={{
            width: '100%', padding: '10px 12px', border: '1px solid #4a4a6a', borderRadius: 6,
            background: '#0f0f1a', color: '#e0e0e0', fontSize: 14, outline: 'none',
            boxSizing: 'border-box',
          }}
        />
        <button
          onClick={handleSubmit}
          disabled={saving || !input.trim()}
          style={{
            width: '100%', marginTop: 12, padding: '10px 0', border: 'none', borderRadius: 6,
            background: input.trim() ? '#4ade80' : '#2a3a2e', color: input.trim() ? '#0f0f1a' : '#666',
            fontSize: 14, fontWeight: 600, cursor: input.trim() ? 'pointer' : 'default',
          }}
        >
          {saving ? 'Creating workspace...' : 'Get Started'}
        </button>
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { useProjectStore } from '../store/projectStore';
import { performAutoSave, AutoSaveSnapshot } from '../utils/autoSave';

const INTERVAL_MS = 15 * 60 * 1000;

export function useAutoSave() {
  const lastRef = useRef<string>('');

  useEffect(() => {
    const save = () => {
      const state = useProjectStore.getState();
      if (!state.projectId) return;

      const snapshot: AutoSaveSnapshot = {
        nodes: state.nodes,
        edges: state.edges,
        targetOS: state.targetOS,
        projectName: state.projectName,
      };

      const key = JSON.stringify(snapshot);
      if (key === lastRef.current) return;

      performAutoSave(state.projectId, snapshot);
      lastRef.current = key;
    };

    const interval = setInterval(save, INTERVAL_MS);

    const handleBeforeUnload = () => save();
    window.addEventListener('beforeunload', handleBeforeUnload);

    return () => {
      clearInterval(interval);
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, []);
}

import { useEffect } from 'react';
import { useProjectStore } from '../store/projectStore';
import { broadcastState, subscribeRoadmap, broadcastSyncResponse } from '../utils/roadmapSync';

export function useRoadmapSync() {
  const nodes = useProjectStore(s => s.nodes);
  const edges = useProjectStore(s => s.edges);
  const selectedNode = useProjectStore(s => s.selectedNode);
  const targetOS = useProjectStore(s => s.targetOS);
  const generationLayer = useProjectStore(s => s.generationLayer);
  const isGenerating = useProjectStore(s => s.isGenerating);

  useEffect(() => {
    broadcastState({
      nodes,
      edges,
      selectedNode,
      targetOS,
      generationLayer,
      isGenerating,
    });
  }, [nodes, edges, selectedNode, targetOS, generationLayer, isGenerating]);

  useEffect(() => {
    const unsub = subscribeRoadmap(
      () => {},
      (nodeId: string | null) => {
        useProjectStore.getState().setSelectedNode(nodeId);
      },
      () => {
        const state = useProjectStore.getState();
        broadcastSyncResponse({
          nodes: state.nodes,
          edges: state.edges,
          selectedNode: state.selectedNode,
          targetOS: state.targetOS,
          generationLayer: state.generationLayer,
          isGenerating: state.isGenerating,
        });
      }
    );

    return unsub;
  }, []);
}

