export interface AutoSaveSnapshot {
  nodes: Node[];
  edges: Edge[];
  targetOS: OSType;
  projectName: string;
}

export interface AutoSaveEntry {
  id: string;
  projectId: string;
  snapshot: AutoSaveSnapshot;
  savedAt: string;
}

const STORAGE_KEY = 'vaia-autosaves';

function getAll(): Record<string, AutoSaveEntry[]> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function setAll(all: Record<string, AutoSaveEntry[]>) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(all));
  } catch {
    // storage full or unavailable
  }
}

function snapshotsEqual(a: AutoSaveSnapshot, b: AutoSaveSnapshot): boolean {
  return a.projectName === b.projectName
    && a.targetOS === b.targetOS
    && JSON.stringify(a.nodes) === JSON.stringify(b.nodes)
    && JSON.stringify(a.edges) === JSON.stringify(b.edges);
}

export function performAutoSave(
  projectId: string,
  current: AutoSaveSnapshot
): AutoSaveEntry | null {
  if (!projectId) return null;

  const all = getAll();
  const saves = all[projectId] || [];

  if (saves.length > 0 && snapshotsEqual(saves[0].snapshot, current)) {
    return null;
  }

  const entry: AutoSaveEntry = {
    id: `autosave_${Date.now()}`,
    projectId,
    snapshot: JSON.parse(JSON.stringify(current)),
    savedAt: new Date().toISOString(),
  };

  saves.unshift(entry);
  all[projectId] = saves.slice(0, 5);
  setAll(all);
  return entry;
}

export function getAutoSaves(projectId: string): AutoSaveEntry[] {
  const all = getAll();
  return all[projectId] || [];
}

export function clearAutoSaves(projectId: string) {
  const all = getAll();
  delete all[projectId];
  setAll(all);
}

import { Node, Edge } from 'reactflow';
import { OSType } from '../types';

const USER_NAME_KEY = 'vaia-user-name';
export const STORAGE_KEY = 'vaia-projects';

export interface SavedProject {
  id: string;
  name: string;
  targetOS: OSType;
  nodes: Node[];
  edges: Edge[];
  savedAt: string;
  version: number;
}

function getUserName(): string | null {
  return localStorage.getItem(USER_NAME_KEY);
}

function getStore(): SavedProject[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function setStore(projects: SavedProject[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(projects));
}

function syncToDisk(projects: SavedProject[]) {
  const name = getUserName();
  if (!name) return;
  fetch('/api/user/files/' + encodeURIComponent(name) + '/projects/projects.json', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ data: JSON.stringify(projects, null, 2) }),
  }).catch(() => {});
}

export function saveProject(data: {
  id: string;
  name: string;
  targetOS: OSType;
  nodes: Node[];
  edges: Edge[];
}): SavedProject {
  const store = getStore();
  const existing = store.findIndex((p) => p.id === data.id);

  const saved: SavedProject = {
    ...data,
    savedAt: new Date().toISOString(),
    version: existing >= 0 ? (store[existing].version || 0) + 1 : 1,
  };

  if (existing >= 0) {
    store[existing] = saved;
  } else {
    store.push(saved);
  }

  setStore(store);
  syncToDisk(store);
  return saved;
}

export function loadProject(id: string): SavedProject | null {
  const store = getStore();
  return store.find((p) => p.id === id) || null;
}

export function loadProjects(): SavedProject[] {
  return getStore().sort((a, b) =>
    new Date(b.savedAt).getTime() - new Date(a.savedAt).getTime()
  );
}

export function deleteProject(id: string): boolean {
  const store = getStore();
  const filtered = store.filter((p) => p.id !== id);
  if (filtered.length === store.length) return false;
  setStore(filtered);
  syncToDisk(filtered);
  return true;
}

export function exportProject(id: string): string | null {
  const project = loadProject(id);
  if (!project) return null;
  return JSON.stringify(project, null, 2);
}

export function importProject(json: string): SavedProject | null {
  try {
    const parsed = JSON.parse(json) as SavedProject;
    if (!parsed.id || !parsed.name || !Array.isArray(parsed.nodes)) return null;

    const dup: SavedProject = {
      ...parsed,
      id: `proj_${Date.now()}`,
      name: parsed.name,
      savedAt: new Date().toISOString(),
      version: 1,
    };

    const store = getStore();
    store.push(dup);
    setStore(store);
    syncToDisk(store);
    return dup;
  } catch {
    return null;
  }
}

export const REASONING_CHANNEL = 'visual-ai-reasoning';

export interface ReasoningMessage {
  role: 'user' | 'ai';
  text: string;
  timestamp: string;
}

export type ReasoningSyncMessage =
  | { type: 'new-message'; payload: ReasoningMessage }
  | { type: 'sync-request' }
  | { type: 'sync-response'; payload: { messages: ReasoningMessage[] } }
  | { type: 'clear' };

let channel: BroadcastChannel | null = null;

function getChannel() {
  if (!channel && typeof window !== 'undefined' && 'BroadcastChannel' in window) {
    channel = new BroadcastChannel(REASONING_CHANNEL);
  }
  return channel;
}

export function broadcastReasoningMessage(msg: ReasoningMessage) {
  const ch = getChannel();
  if (ch) ch.postMessage({ type: 'new-message', payload: msg });
}

export function broadcastReasoningClear() {
  const ch = getChannel();
  if (ch) ch.postMessage({ type: 'clear' });
}

export function requestReasoningSync() {
  const ch = getChannel();
  if (ch) ch.postMessage({ type: 'sync-request' });
}

export function sendReasoningSyncResponse(messages: ReasoningMessage[]) {
  const ch = getChannel();
  if (ch) ch.postMessage({ type: 'sync-response', payload: { messages } });
}

export function subscribeReasoning(
  onMessage: (msg: ReasoningMessage) => void,
  onSyncRequest: () => void,
  onClear: () => void,
) {
  const ch = getChannel();
  if (!ch) return () => {};

  ch.onmessage = (event: MessageEvent<ReasoningSyncMessage>) => {
    const data = event.data;
    if (data.type === 'new-message') onMessage(data.payload);
    else if (data.type === 'sync-request') onSyncRequest();
    else if (data.type === 'clear') onClear();
  };

  return () => {
    ch.close();
    channel = null;
  };
}

import { Node, Edge } from 'reactflow';
import { OSType } from '../types';

const USER_NAME_KEY = 'vaia-user-name';

interface RoadmapData {
  projectName: string;
  targetOS: OSType;
  nodes: Array<{
    id: string;
    type: string;
    label: string;
    description: string;
    language?: string;
    position: { x: number; y: number };
  }>;
  edges: Array<{ source: string; target: string }>;
  createdAt: string;
}

function getUserName(): string | null {
  return localStorage.getItem(USER_NAME_KEY);
}

export async function saveRoadmap(projectName: string, targetOS: OSType, nodes: Node[], edges: Edge[]) {
  const roadmap: RoadmapData = {
    projectName,
    targetOS,
    nodes: nodes
      .filter((n) => n.type !== 'master')
      .map((n) => ({
        id: n.id,
        type: n.type || 'logic',
        label: (n.data as any)?.label || n.type,
        description: (n.data as any)?.description || '',
        language: (n.data as any)?.language,
        position: n.position,
      })),
    edges: edges.map((e) => ({
      source: e.source,
      target: e.target,
    })),
    createdAt: new Date().toISOString(),
  };

  // Always save to localStorage as fallback
  const roadmaps = loadRoadmaps();
  roadmaps.push(roadmap);
  localStorage.setItem('ai-architect-roadmaps', JSON.stringify(roadmaps));

  // Save to disk via backend if user name is set
  const name = getUserName();
  if (name) {
    const filename = `${projectName.replace(/[^a-zA-Z0-9_-]/g, '_')}_${Date.now()}.json`;
    fetch('/api/user/files/' + encodeURIComponent(name) + '/roadmaps/' + filename, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ data: JSON.stringify(roadmap, null, 2) }),
    }).catch(() => {});
  }

  return roadmap;
}

export function loadRoadmaps(): RoadmapData[] {
  try {
    return JSON.parse(localStorage.getItem('ai-architect-roadmaps') || '[]');
  } catch {
    return [];
  }
}

export function getLatestRoadmap(): RoadmapData | null {
  const roadmaps = loadRoadmaps();
  return roadmaps.length > 0 ? roadmaps[roadmaps.length - 1] : null;
}

