    selectedNode: string | null;
    targetOS: OSType;
    generationLayer: number;
    isGenerating: boolean;
  };
} | {
  type: 'select-node';
  payload: { nodeId: string | null };
} | {
  type: 'sync-request';
  payload: Record<string, never>;
} | {
  type: 'sync-response';
  payload: {
    nodes: Node[];
    edges: Edge[];
    selectedNode: string | null;
    targetOS: OSType;
    generationLayer: number;
    isGenerating: boolean;
  };
} | {
  type: 'auto-save';
  payload: {
    nodes: Node[];
    edges: Edge[];
  };
};

let channel: BroadcastChannel | null = null;

function getChannel() {
  if (!channel && typeof window !== 'undefined' && 'BroadcastChannel' in window) {
    channel = new BroadcastChannel(ROADMAP_CHANNEL);
  }
  return channel;
}

export function broadcastState(state: RoadmapSyncMessage['payload']) {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'state-update', payload: state });
  }
}

export function broadcastSelectNode(nodeId: string | null) {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'select-node', payload: { nodeId } });
  }
}

export function subscribeRoadmap(
  onUpdate: (payload: RoadmapSyncMessage['payload']) => void,
  onSelect: (nodeId: string | null) => void,
  onSyncRequest: () => void
) {
  const ch = getChannel();
  if (!ch) return () => {};

  ch.onmessage = (event: MessageEvent<RoadmapSyncMessage>) => {
    if (event.data.type === 'state-update') {
      onUpdate(event.data.payload as RoadmapSyncMessage['payload']);
    } else if (event.data.type === 'select-node') {
      onSelect(event.data.payload.nodeId);
    } else if (event.data.type === 'sync-request') {
      onSyncRequest();
    } else if (event.data.type === 'sync-response') {
      onUpdate(event.data.payload as RoadmapSyncMessage['payload']);
    }
  };

  return () => {
    ch.close();
    channel = null;
  };
}

export function requestSync() {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'sync-request', payload: {} });
  }
}

export function broadcastSyncResponse(state: RoadmapSyncMessage['payload']) {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'sync-response', payload: state });
  }
}

export type TreeNode = {
  id: string;
  node?: { id: string; data?: { label?: string; status?: string; type?: string; subNodes?: { id: string }[] } };
  children: TreeNode[];
};

export function buildTrees(
  nodes: { id: string; data?: { label?: string; status?: string; type?: string; subNodes?: { id: string }[] } }[],
  edges: { source: string; target: string }[]
) {
  const childrenMap: Record<string, string[]> = {};
  const hasParent: Record<string, boolean> = {};

  nodes.forEach((n) => {
    childrenMap[n.id] = [];
    hasParent[n.id] = false;
  });

  edges.forEach((e) => {
    if (childrenMap[e.source]) {
      childrenMap[e.source].push(e.target);
    }
    hasParent[e.target] = true;
  });

  const roots = nodes.filter((n) => !hasParent[n.id]);

  return roots.map((root) => buildTree(root.id, childrenMap, nodes));
}

function buildTree(
  nodeId: string,
  childrenMap: Record<string, string[]>,
  allNodes: { id: string; data?: { label?: string; status?: string; type?: string; subNodes?: { id: string }[] } }[]
): TreeNode {
  const node = allNodes.find((n) => n.id === nodeId);
  const children: TreeNode[] = (childrenMap[nodeId] || []).map((childId) =>
    buildTree(childId, childrenMap, allNodes)
  );
  return { id: nodeId, node, children };
}

let codeMessages: { role: string; content: string }[] = [];
let reasoningMessages: { role: string; content: string }[] = [];
let codeListeners: Set<() => void> = new Set();
let reasoningListeners: Set<() => void> = new Set();

const MAX = 20;

export function pushCodeMessage(role: string, content: string) {
  codeMessages = [...codeMessages.slice(-(MAX - 1)), { role, content }];
  codeListeners.forEach((fn) => fn());
}

export function pushReasoningMessage(role: string, content: string) {
  reasoningMessages = [...reasoningMessages.slice(-(MAX - 1)), { role, content }];
  reasoningListeners.forEach((fn) => fn());
}

export function getCodeContext(): { role: string; content: string }[] {
  return codeMessages;
}

export function getReasoningContext(): { role: string; content: string }[] {
  return reasoningMessages;
}

const CONTEXT_SIZE = 6;

export function getCodeContextPrompt(): string {
  const msgs = codeMessages.slice(-CONTEXT_SIZE);
  if (msgs.length === 0) return '';
  return 'Recent LLM 2 (Code Builder) conversation:\n' + msgs.map((m) => `${m.role === 'user' ? 'User' : 'LLM 2'}: ${m.content}`).join('\n');
}

export function getReasoningContextPrompt(): string {
  const msgs = reasoningMessages.slice(-CONTEXT_SIZE);
  if (msgs.length === 0) return '';
  return 'Recent LLM 1 (Reasoning & Design) conversation:\n' + msgs.map((m) => `${m.role === 'user' ? 'User' : 'LLM 1'}: ${m.content}`).join('\n');
}

