export const STATUS_CHANNEL = 'visual-ai-status';

export function broadcastStatus(payload: { thinking: boolean; progress: number }) {
  try {
    const ch = new BroadcastChannel(STATUS_CHANNEL);
    ch.postMessage({ type: 'status-update', payload });
    ch.close();
  } catch {}
}

export const TERMINAL_CHANNEL = 'visual-ai-terminal';

export interface TerminalMessage {
  role: 'user' | 'ai';
  text: string;
  timestamp: string;
}

export type TerminalSyncMessage = {
  type: 'new-message';
  payload: TerminalMessage;
} | {
  type: 'sync-request';
} | {
  type: 'sync-response';
  payload: { messages: TerminalMessage[] };
} | {
  type: 'clear';
};

let channel: BroadcastChannel | null = null;

function getChannel() {
  if (!channel && typeof window !== 'undefined' && 'BroadcastChannel' in window) {
    channel = new BroadcastChannel(TERMINAL_CHANNEL);
  }
  return channel;
}

export function broadcastMessage(msg: TerminalMessage) {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'new-message', payload: msg });
  }
}

export function broadcastClear() {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'clear' });
  }
}

export function requestSync() {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'sync-request' });
  }
}

export function sendSyncResponse(messages: TerminalMessage[]) {
  const ch = getChannel();
  if (ch) {
    ch.postMessage({ type: 'sync-response', payload: { messages } });
  }
}

export function subscribeTerminal(
  onMessage: (msg: TerminalMessage) => void,
  onSyncRequest: () => void,
  onClear: () => void
) {
  const ch = getChannel();
  if (!ch) return () => {};

  ch.onmessage = (event: MessageEvent<TerminalSyncMessage>) => {
    const data = event.data;
    if (data.type === 'new-message') {
      onMessage(data.payload);
    } else if (data.type === 'sync-request') {
      onSyncRequest();
    } else if (data.type === 'clear') {
      onClear();
    }
  };

  return () => {
    ch.close();
    channel = null;
  };
}

let streamQueue: string[] = [];
let streamPlaying = false;
let streamStopped = false;
let streamFinished = false;
let streamOnEnd: (() => void) | null = null;

export function warmupAudio(): void {
  try {
    const ctx = new AudioContext();
    const src = ctx.createBufferSource();
    src.buffer = ctx.createBuffer(1, 1, ctx.sampleRate);
    src.connect(ctx.destination);
    src.start();
  } catch {}
}

export function stripEmoji(text: string): string {
  return text.replace(
    /[\u{1F000}-\u{1FFFF}]|[\u{2700}-\u{27BF}]|[\u{2600}-\u{26FF}]|[\u{FE00}-\u{FE0F}]|[\u{200D}]/gu,
    ''
  ).trim();
}

let ttsCtx: AudioContext | null = null;

function getTtsCtx(): AudioContext {
  if (!ttsCtx) ttsCtx = new AudioContext();
  if (ttsCtx.state === 'suspended') ttsCtx.resume();
  return ttsCtx;
}

function buildAudioGraph(ac: AudioContext, source: AudioBufferSourceNode): AudioNode {
  let tail: AudioNode = source;

  const bassVal = parseFloat(localStorage.getItem('tts-bass') || '0');
  const midVal = parseFloat(localStorage.getItem('tts-mid') || '0');
  const highVal = parseFloat(localStorage.getItem('tts-high') || '0');
  const echoVal = parseFloat(localStorage.getItem('tts-echo') || '0');
  const volumeVal = parseFloat(localStorage.getItem('tts-volume') || '1');

  if (bassVal !== 0) {
    const f = ac.createBiquadFilter();
    f.type = 'lowshelf';
    f.frequency.value = 300;
    f.Q.value = 1;
    f.gain.value = bassVal;
    tail.connect(f);
    tail = f;
  }

  if (midVal !== 0) {
    const f = ac.createBiquadFilter();
    f.type = 'peaking';
    f.frequency.value = 1000;
    f.Q.value = 1;
    f.gain.value = midVal;
    tail.connect(f);
    tail = f;
  }

  if (highVal !== 0) {
    const f = ac.createBiquadFilter();
    f.type = 'highshelf';
    f.frequency.value = 4000;
    f.Q.value = 1;
    f.gain.value = highVal;
    tail.connect(f);
    tail = f;
  }

  if (echoVal > 0) {
    const delay = ac.createDelay(1);
    delay.delayTime.value = echoVal * 0.3;
    const feedback = ac.createGain();
    feedback.gain.value = echoVal * 0.4;
    const dryGain = ac.createGain();
    dryGain.gain.value = 1;
    const wetGain = ac.createGain();
    wetGain.gain.value = echoVal * 0.6;
    const merger = ac.createGain();

    tail.connect(dryGain);
    dryGain.connect(merger);

    tail.connect(delay);
    delay.connect(feedback);
    feedback.connect(delay);
    delay.connect(wetGain);
    wetGain.connect(merger);

    tail = merger;
  }

  const vol = ac.createGain();
  vol.gain.value = Math.max(0, volumeVal);
  tail.connect(vol);
  return vol;
}

function playAudioBuffer(ac: AudioContext, buffer: AudioBuffer, onEnd?: () => void) {
  const source = ac.createBufferSource();
  source.buffer = buffer;
  const pitchVal = parseFloat(localStorage.getItem('tts-pitch') || '1');
  source.playbackRate.value = Math.max(0.1, pitchVal);
  const output = buildAudioGraph(ac, source);
  output.connect(ac.destination);
  source.start();
  source.onended = onEnd || null;
  return source;
}

export async function speak(text: string, onEnd?: () => void) {
  text = stripEmoji(text);
  if (!text) { onEnd?.(); return; }
  stopSpeechStream();

  try {
    const speedVal = parseFloat(localStorage.getItem('tts-speed') || '1');
    const voice = localStorage.getItem('tts-voice') || 'en-US-JennyNeural';
    const res = await fetch('/api/tts', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, voice, pitch: 1, rate: speedVal, volume: 1 }),
    });
    if (!res.ok) throw new Error(`TTS request failed (${res.status})`);
    const ac = getTtsCtx();
    const buf = await res.arrayBuffer();
    const buffer = await ac.decodeAudioData(buf);
    playAudioBuffer(ac, buffer, onEnd);
  } catch (e) {
    console.warn('TTS failed:', e);
    onEnd?.();
  }
}

export function stopSpeaking() {
  stopSpeechStream();
  if (ttsCtx) {
    ttsCtx.close().catch(() => {});
    ttsCtx = null;
  }
}

export function startSpeechStream(onEnd?: () => void) {
  stopSpeechStream();
  streamQueue = [];
  streamPlaying = false;
  streamStopped = false;
  streamFinished = false;
  streamOnEnd = onEnd ?? null;
}

export function enqueueSpeech(text: string) {
  text = stripEmoji(text);
  if (streamStopped || streamFinished || !text) return;
  streamQueue.push(text);
  if (!streamPlaying) processSpeechQueue();
}

export function finishSpeechStream() {
  streamFinished = true;
  if (!streamPlaying && streamQueue.length === 0) {
    streamOnEnd?.();
    streamOnEnd = null;
  }
}

export function stopSpeechStream() {
  streamStopped = true;
  streamQueue = [];
  streamPlaying = false;
}

async function processSpeechQueue() {
  while (!streamStopped && streamQueue.length > 0) {
    streamPlaying = true;
    const text = streamQueue.shift()!;
    try {
      const speedVal = parseFloat(localStorage.getItem('tts-speed') || '1');
      const voice = localStorage.getItem('tts-voice') || 'en-US-JennyNeural';
      const res = await fetch('/api/tts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text, voice, pitch: 1, rate: speedVal, volume: 1 }),
      });
      if (!res.ok) continue;
      const ac = getTtsCtx();
      const buf = await res.arrayBuffer();
      const buffer = await ac.decodeAudioData(buf);
      await new Promise<void>((resolve) => {
        playAudioBuffer(ac, buffer, resolve);
      });
    } catch {}
  }
  streamPlaying = false;
  if (streamFinished && streamQueue.length === 0) {
    streamOnEnd?.();
    streamOnEnd = null;
  }
}

