.tab:hover { color: var(--text); border-color: var(--text-dim); }
.tab.active { background: var(--primary); color: white; border-color: var(--primary); }
.tab-ready.active { background: var(--ready); border-color: var(--ready); color: #000; }
.tab-review.active { background: var(--review); border-color: var(--review); color: #000; }
.tab-unusable.active { background: var(--unusable); border-color: var(--unusable); color: #fff; }

.file-list { max-height: 300px; overflow-y: auto; display: flex; flex-direction: column; gap: 6px; }
