.file-item { display: flex; align-items: center; gap: 8px; padding: 8px 10px; background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-sm); cursor: grab; transition: all 0.15s; user-select: none; }
.file-item:hover { border-color: var(--primary); background: rgba(108,92,231,0.1); }
.file-item.dragging { opacity: 0.5; border-style: dashed; }
.file-icon { font-size: 16px; flex-shrink: 0; }
.file-info { flex: 1; min-width: 0; }
.file-name { font-size: 12px; font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.file-name.clickable { cursor: pointer; }
.file-name.clickable:hover { color: var(--primary); }
.file-meta { font-size: 10px; color: var(--text-dim); display: flex; gap: 8px; }
.file-category { font-size: 10px; padding: 1px 6px; border-radius: 8px; font-weight: 600; flex-shrink: 0; }
.cat-ready { background: #00cec920; color: var(--ready); }
.cat-review { background: #fdcb6e20; color: var(--review); }
.cat-unusable { background: #e1705520; color: var(--unusable); }

.empty-state { font-size: 12px; color: var(--text-dim); text-align: center; padding: 20px 0; }

.training-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid var(--border); }
.training-header h2 { margin-bottom: 0; padding-bottom: 0; border-bottom: none; }
.model-selector { display: flex; align-items: center; gap: 4px; }
.model-selector label { font-size: 11px; color: var(--text-dim); }
.model-dropdown { padding: 4px 8px; background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-sm); color: var(--text); font-size: 12px; max-width: 180px; }
.model-dropdown:focus { outline: none; border-color: var(--primary); }

.training-controls { display: flex; gap: 16px; margin-bottom: 12px; flex-wrap: wrap; }
.control-group { display: flex; align-items: center; gap: 6px; }
.control-group label { font-size: 12px; color: var(--text-dim); font-weight: 500; }
.epoch-input { width: 72px; padding: 4px 8px; background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--radius-sm); color: var(--text); font-size: 13px; text-align: center; }
.epoch-input:focus { outline: none; border-color: var(--primary); }

.training-buttons { display: flex; gap: 8px; margin-bottom: 12px; flex-wrap: wrap; }

.btn { padding: 8px 18px; font-size: 13px; font-weight: 600; border: none; border-radius: var(--radius-sm); cursor: pointer; transition: all 0.15s; display: inline-flex; align-items: center; gap: 4px; }
.btn:disabled { opacity: 0.4; cursor: not-allowed; }
.btn-sm { padding: 4px 10px; font-size: 11px; }
.btn-primary { background: var(--primary); color: white; }
.btn-primary:hover:not(:disabled) { background: #7c6df7; }
.btn-danger { background: var(--danger); color: white; }
.btn-danger:hover:not(:disabled) { background: #d63031; }
.btn-warning { background: var(--warning); color: #000; }
.btn-warning:hover:not(:disabled) { background: #f9ca24; }
.btn-secondary { background: var(--surface-2); color: var(--text); border: 1px solid var(--border); }
.btn-secondary:hover:not(:disabled) { border-color: var(--text-dim); }

.training-progress { margin-top: 8px; }
.progress-bar-container { height: 6px; background: var(--surface-2); border-radius: 3px; overflow: hidden; }
.progress-bar { height: 100%; width: 0%; background: linear-gradient(90deg, var(--primary), var(--success)); border-radius: 3px; transition: width 0.3s; }
.progress-info { display: flex; justify-content: space-between; margin-top: 6px; font-size: 11px; color: var(--text-dim); }

.metrics-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 16px; }
