export function getNodePrompt(type: NodeType, description: string, os: OSType): string {
  const typeInstructions: Record<NodeType, string> = {
    input: `Create an input handler that: ${description}. Accept external data and validate it.`,
    output: `Create an output handler that: ${description}. Format and display results.`,
    logic: `Create a logic/processing function that: ${description}. Include error handling.`,
    api: `Create an API client that: ${description}. Handle HTTP requests and responses.`,
    database: `Create a database operation that: ${description}. Include connection handling.`,
    ui: `Create a UI component that: ${description}. Follow platform-specific UI patterns.`,
    master: `Create the main application blueprint that: ${description}. Orchestrates all components.`,
  };

  return `${OS_PERSONAS[os]}\n\n${typeInstructions[type]}`;
}

export function getSassyNodePrompt(type: NodeType, description: string, os: OSType): string {
  const typeInstructions: Record<NodeType, string> = {
    input: `Create an input handler that: ${description}. Accept external data and validate it.`,
    output: `Create an output handler that: ${description}. Format and display results.`,
    logic: `Create a logic/processing function that: ${description}. Include error handling.`,
    api: `Create an API client that: ${description}. Handle HTTP requests and responses.`,
    database: `Create a database operation that: ${description}. Include connection handling.`,
    ui: `Create a UI component that: ${description}. Follow platform-specific UI patterns.`,
    master: `Create the main application blueprint that: ${description}. Orchestrates all components.`,
  };

  return `${SASSY_OS_PERSONAS[os]}\n\n${typeInstructions[type]}`;
}

