  private webViteConfig(isElectron: boolean): string {
    const config: Record<string, any> = {
      plugins: ['react()'],
      server: { port: 5173 },
    };

    // Electron loads from file:// protocol — use relative base path
    if (isElectron) {
      config.base = './';
    }

    const serialize = (obj: any, indent = 0): string => {
      const pad = '  '.repeat(indent);
      const innerPad = '  '.repeat(indent + 1);
      if (Array.isArray(obj)) {
        return `[\n${obj.map((v) => `${innerPad}${serialize(v, indent + 1)}`).join(',\n')}\n${pad}]`;
      }
      if (typeof obj === 'object' && obj !== null) {
        const entries = Object.entries(obj);
        if (entries.length === 0) return '{}';
        return `{\n${entries.map(([k, v]) => `${innerPad}${k}: ${serialize(v, indent + 1)}`).join(',\n')}\n${pad}}`;
      }
      if (typeof obj === 'string') {
        // Check if it looks like a function/expression reference
        if (obj.endsWith('()')) return obj;
        return `'${obj}'`;
      }
      return String(obj);
    };

    return (
      `import { defineConfig } from 'vite';\n` +
      `import react from '@vitejs/plugin-react';\n\n` +
      `// https://vitejs.dev/config/\n` +
      `export default defineConfig(${serialize(config, 0)});\n`
    );
  }

