  private webAppComponent(config: ScaffoldConfig): string {
    const { projectName, appGoal, nodes } = config;
    const nodeList = (nodes || [])
      .filter((n) => n.type !== 'master')
      .map((n) => `  <div className="node-card">\n    <h3>${n.data?.label || n.id}</h3>\n    <p className="node-type">${n.type}</p>\n    <p>${n.data?.description || ''}</p>\n  </div>`)
      .join('\n');

    return (
      `import { useEffect, useState, useRef } from 'react';\n\n` +
      `/**\n` +
      ` * ${projectName}\n` +
      ` * Generated by Visual AI Code Architect\n` +
      ` * Target: Web (React + Vite + TypeScript)\n` +
      ` *\n` +
      ` * The generated code from the AI is split into three layer files:\n` +
      ` *   - foundation.ts  — imports, setup, package configuration\n` +
      ` *   - functions.ts   — per-node business logic\n` +
      ` *   - integration.ts — wiring all nodes together\n` +
      ` *\n` +
      ` * These files are dynamically imported on mount. If the AI generated\n` +
      ` * them with no side-effect exports, they still execute their top-level\n` +
      ` * code. Edit those files to customize the app.\n` +
      ` */\n\n` +
      `function App() {\n` +
      `  const [status, setStatus] = useState('Initializing...');\n` +
      `  const [logs, setLogs] = useState<string[]>([]);\n` +
      `  const mounted = useRef(true);\n\n` +
      `  const addLog = (msg: string) => {\n` +
      `    if (mounted.current) {\n` +
      `      setLogs((prev) => [...prev, msg]);\n` +
      `    }\n` +
      `  };\n\n` +
      `  useEffect(() => {\n` +
      `    async function loadGeneratedLayers() {\n` +
      `      try {\n` +
      `        setStatus('Loading foundation...');\n` +
      `        addLog('📦 Loading Layer 1 (foundation)...');\n` +
      `        await import('./foundation');\n` +
      `        addLog('✅ Foundation loaded');\n\n` +
      `        setStatus('Loading functions...');\n` +
      `        addLog('🔧 Loading Layer 2 (functions)...');\n` +
      `        const fnModule = await import('./functions');\n` +
      `        const fnCount = Object.keys(fnModule).length;\n` +
      `        addLog('✅ Functions loaded — ' + fnCount + ' export(s) available');\n\n` +
      `        if (typeof (fnModule as any).runAll === 'function') {\n` +
      `          addLog('⚡ Running exported functions...');\n` +
      `          (fnModule as any).runAll();\n` +
      `          addLog('✅ Functions executed');\n` +
      `        }\n\n` +
      `        setStatus('Loading integration...');\n` +
      `        addLog('🔗 Loading Layer 3 (integration)...');\n` +
      `        const intModule = await import('./integration');\n` +
      `        if (typeof (intModule as any).run === 'function') {\n` +
      `          addLog('⚡ Running integration...');\n` +
      `          await (intModule as any).run();\n` +
      `          addLog('✅ Integration complete');\n` +
      `        } else if (typeof (intModule as any).default === 'function') {\n` +
      `          addLog('⚡ Running default export...');\n` +
      `          await (intModule as any).default();\n` +
      `          addLog('✅ Default export executed');\n` +
      `        } else {\n` +
      `          addLog('ℹ️ No default run function found — module loaded with side effects only');\n` +
      `        }\n\n` +
      `        setStatus('Ready');\n` +
      `        addLog('🎉 ${projectName} is ready!');\n` +
      `      } catch (err: any) {\n` +
      `        const msg = err?.message || String(err);\n` +
      `        // Ignore 'Failed to fetch dynamically imported module'\n` +
      `        // — this just means the layer file has no exports, which is fine.\n` +
      `        if (!msg.includes('dynamically imported')) {\n` +
      `          addLog('⚠️ ' + msg);\n` +
      `        }\n` +
      `        setStatus('Running');\n` +
      `        addLog('ℹ️ Layers loaded (modules may have been side-effect only)');\n` +
      `      }\n` +
      `    }\n` +
      `    loadGeneratedLayers().catch((err) => {\n` +
      `      addLog('❌ Fatal: ' + (err?.message || err));\n` +
      `      setStatus('Error');\n` +
      `    });\n` +
      `    return () => { mounted.current = false; };\n` +
      `  }, []);\n\n` +
      `  return (\n` +
      `    <div className="app">\n` +
      `      <header className="app-header">\n` +
      `        <h1>🚀 ${projectName}</h1>\n` +
      `        <p className="status">\n` +
      `          Status: <span className={\`badge badge-\${status.toLowerCase().replace(/\s+/g, '-')}\`}>{status}</span>\n` +
      `        </p>\n` +
      `        ${appGoal ? `<p className="goal">Goal: ${appGoal}</p>` : ''}\n` +
      `      </header>\n` +
      `      <main className="app-main">\n` +
      `        <section className="logs-section">\n` +
      `          <h2>Runtime Logs</h2>\n` +
      `          <div className="logs">\n` +
      `            {logs.length === 0 ? (\n` +
      `              <p className="log-empty">Waiting for layers to load...</p>\n` +
      `            ) : (\n` +
      `              logs.map((log, i) => (\n` +
      `                <p key={i} className="log-line">{log}</p>\n` +
      `              ))\n` +
      `            )}\n` +
      `          </div>\n` +
      `        </section>\n` +
      `        <section className="nodes-section">\n` +
      `          <h2>Node Architecture</h2>\n` +
      `          <div className="nodes-grid">\n` +
      `${nodeList || '  <p>No nodes defined</p>'}\n` +
      `          </div>\n` +
      `        </section>\n` +
      `      </main>\n` +
      `    </div>\n` +
      `  );\n` +
      `}\n\n` +
      `export default App;\n`
    );
  }

