async function fetchOllamaModels(baseUrl: string, signal?: AbortSignal): Promise<any[]> {
  const url = baseUrl.replace(/\/v1\/?$/, '').replace(/\/+$/, '') + '/api/tags';
  const response = await fetch(url, { signal: signal || AbortSignal.timeout(5000) });
  if (!response.ok) return [];
  const data = await response.json() as { models?: any[] };
  return (data.models || []).map((m: any) => ({
    name: m.name,
    size: m.size,
    modifiedAt: m.modified_at || m.modifiedAt,
    details: m.details || {},
  }));
}

async function fetchOllamaRunning(baseUrl: string, signal?: AbortSignal): Promise<any[]> {
  const url = baseUrl.replace(/\/v1\/?$/, '').replace(/\/+$/, '') + '/api/ps';
  const response = await fetch(url, { signal: signal || AbortSignal.timeout(5000) });
  if (!response.ok) return [];
  const data = await response.json() as { models?: any[] };
  return (data.models || []).map((m: any) => ({
    name: m.name,
    size: m.size,
    processor: m.processor || '',
    expiresAt: m.expires_at || '',
    details: m.details || {},
