    const pattern = args.includes('--pattern') ? new RegExp(args[args.indexOf('--pattern') + 1]) : undefined;
    console.log(`\n[dir] Scanning directory: ${dir}${pattern ? ` (pattern: ${pattern})` : ''}`);
    const count = await captureFromDirectory(dir, pattern);
