import { useCallback, useEffect, useState } from 'react';
import { NodeType } from './types';
import { useProjectStore } from './store/projectStore';
import { useRoadmapSync } from './hooks/useRoadmapSync';
import { useAutoSave } from './hooks/useAutoSave';
import { api } from './api/client';
import NodePalette from './components/NodePalette';
import Toolbar from './components/Toolbar';
import Canvas from './components/Canvas';
import RoadmapDocked from './components/RoadmapDocked';
import NodeLogicEditor from './components/NodeLogicEditor';
import TerminalSection from './components/TerminalSection';
import ReasoningPanel from './components/ReasoningPanel';
import ModelExplorer from './components/ModelExplorer';
import LLMConfig from './components/LLMConfig';
import ProjectManager from './components/ProjectManager';
import AutoSavePanel from './components/AutoSavePanel';
import ErrorBoundary from './components/ErrorBoundary';
import FileDropHandler from './components/FileDropHandler';
import GlobalShortcuts from './components/GlobalShortcuts';
import UserNamePrompt, { useUserName } from './components/UserNamePrompt';
import LearningDashboard from './components/LearningDashboard';
import { broadcastStatus } from './utils/statusSync';
import { broadcastMessage } from './utils/terminalSync';
import { saveRoadmap } from './utils/roadmapStorage';
import './App.css';


function App() {
  useRoadmapSync();
  useAutoSave();

  const { name: userName, setName: setUserName } = useUserName();
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [userMenuOpen, setUserMenuOpen] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);

  const handleLogout = () => {
    localStorage.removeItem('vaia-user-name');
    window.location.reload();
  };

  const state = useProjectStore();

  const {
    roadmapDetached,
    setRoadmapDetached,
    clearProject,
    setGenerating,
    setGenerationLayer,
    updateNodeStatus,
    nodes,
    projectName,
    targetOS,
    edges,
    saveProject,
    setProjectName,
    thinking,
    progress,
  } = state;

  useEffect(() => {
    broadcastStatus({ thinking, progress });
  }, [thinking, progress]);

  useEffect(() => {
    const masterNode = nodes.find((n) => n.type === 'master');
    const goal = masterNode?.data?.appGoal as string | undefined;
    if (goal && goal.trim()) {
      setProjectName(goal.trim());
    }
  }, [nodes, setProjectName]);

  const handleDragStart = (event: React.DragEvent, nodeType: NodeType) => {
    event.dataTransfer.setData('application/reactflow', nodeType);
    event.dataTransfer.effectAllowed = 'move';
  };

  const handleGenerate = useCallback(async () => {
    const codeNodes = nodes.filter((n) => n.type !== 'master');
    if (codeNodes.length === 0) {
      alert('Click "Build Node Setup" in the blueprint node first to create a starting architecture, then add descriptions before generating.');
      return;
    }

    setGenerating(true);
    setGenerationLayer(1);

    const saved = saveProject();
    if (!saved) {
      setGenerating(false);
      return;
    }

    broadcastMessage({ role: 'ai', text: '⚡ Starting code generation...', timestamp: new Date().toISOString() });

    try {
      const createRes = await api.createProject({ name: projectName, targetOS });
      const serverProjectId = createRes.data.id;
      await api.updateProject(serverProjectId, { nodes: codeNodes, edges });

      broadcastMessage({ role: 'ai', text: `🧠 Reasoning LLM planning ${codeNodes.length} nodes...`, timestamp: new Date().toISOString() });

      const masterNode = nodes.find((n) => n.type === 'master');
      const goal = masterNode?.data?.appGoal || '';
      const purpose = masterNode?.data?.appPurpose || '';

      const planPrompt = `Create a code generation plan for this app:
Goal: ${goal || projectName}
Purpose: ${purpose}
Target OS: ${targetOS}

Nodes to implement:
${codeNodes.map((n) => `- ${(n.data as any)?.label || n.id} (${n.type}, ${(n.data as any)?.language || 'typescript'}): ${(n.data as any)?.description || 'No description'}`).join('\n')}

For each node, specify the key functions, classes, or modules needed. Keep it brief.`;

      try {
        const planRes = await fetch('/api/reason', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ prompt: planPrompt, system: 'You are a code architecture planner. List what each node needs in terms of code. Be concise.', maxTokens: 512 }),
          signal: AbortSignal.timeout(15000),
        });
        if (planRes.ok) {
          const planData = await planRes.json();
          broadcastMessage({ role: 'ai', text: `📋 Generation Plan:\n${planData.response || 'Plan generated.'}`, timestamp: new Date().toISOString() });
        }
      } catch { /* plan is optional */ }

      setGenerationLayer(2);

      const res = await api.generateAll(serverProjectId);
      const results = res.data?.results || [];

      const totalNodes = codeNodes.length;
      for (let i = 0; i < totalNodes; i++) {
        const node = codeNodes[i];
        const nodeLabel = (node.data as any)?.label || node.id;
        const pct = Math.round(((i + 1) / totalNodes) * 100);
        useProjectStore.getState().setProgress(pct);
        broadcastMessage({ role: 'ai', text: `🔧 [${i + 1}/${totalNodes}] Code LLM generating: ${nodeLabel}...`, timestamp: new Date().toISOString() });

        const layerCode = results.map((r: any) => r.code || '').join('\n\n');
        updateNodeStatus(node.id, 'valid', undefined, layerCode || `// Generated code for ${nodeLabel}`);
      }

      setGenerationLayer(3);

      broadcastMessage({ role: 'ai', text: '✅ Code generation complete! Review the generated code in each node.', timestamp: new Date().toISOString() });

      saveRoadmap(projectName, targetOS, nodes, edges);
      broadcastMessage({ role: 'ai', text: '🗺️ Roadmap saved (design without code).', timestamp: new Date().toISOString() });

    } catch {
      console.warn('Backend unavailable — using simulated generation');
      broadcastMessage({ role: 'ai', text: '⚠️ Backend unavailable. Running simulated generation...', timestamp: new Date().toISOString() });

      for (let layer = 1; layer <= 3; layer++) {
        setGenerationLayer(layer);
        for (const node of codeNodes) {
          updateNodeStatus(node.id, 'generating');
          const nodeLabel = (node.data as any)?.label || node.id;
          broadcastMessage({ role: 'ai', text: `🔧 Generating ${nodeLabel} (layer ${layer}/3)...`, timestamp: new Date().toISOString() });
          await new Promise((resolve) => setTimeout(resolve, 800));
          updateNodeStatus(node.id, 'valid', undefined, `// Layer ${layer} code for ${nodeLabel}\nconsole.log("Generated code");`);
        }
      }

      broadcastMessage({ role: 'ai', text: '✅ Simulated code generation complete.', timestamp: new Date().toISOString() });
      saveRoadmap(projectName, targetOS, nodes, edges);
    }

    setGenerating(false);
  }, [nodes, edges, projectName, targetOS, saveProject, setGenerating, setGenerationLayer, updateNodeStatus]);

  const handleExport = useCallback(() => {
    alert('Export functionality coming soon!');
  }, []);

  const handleClear = useCallback(() => {
    if (confirm('Are you sure you want to clear the entire project?')) {
      clearProject();
    }
  }, [clearProject]);

  return (
    <ErrorBoundary>
    <div className="app">
      <header className="app-header">
        <h1 className="app-title">🚀 Visual AI Code Architect</h1>
        <span className="project-name">{projectName}</span>
        <Toolbar
          onGenerate={handleGenerate}
          onExport={handleExport}
          onClear={handleClear}
        />
        <AutoSavePanel />
        <ProjectManager />
        <button
          onClick={() => {
            fetch('/api/training/open', { method: 'POST' }).catch(() => {});
          }}
          style={{
            background: 'none',
            border: '1px solid #a855f7',
            borderRadius: 4,
            color: '#c4b5fd',
            cursor: 'pointer',
            fontSize: 12,
            padding: '2px 10px',
            lineHeight: '1.4',
            fontWeight: 500,
          }}
          title="Open LLM Training Studio folder"
        >
          <button onClick={() => setShowDashboard(!showDashboard)} style={{padding:"6px 10px",background:showDashboard?"#667eea":"rgba(255,255,255,0.1)",border:"none",borderRadius:"6px",color:"#fff",cursor:"pointer",fontSize:"0.85rem",fontWeight:600,marginRight:"4px",transition:"all 0.2s"}}>🧠 Dashboard</button><button onClick={() => fetch("/api/training/open", {method:"POST"}).catch(()=>{})} title="Open LLM Training Studio folder" style={{padding:"6px 10px",background:"rgba(255,255,255,0.1)",border:"none",borderRadius:"6px",color:"#fff",cursor:"pointer",fontSize:"0.85rem",fontWeight:600}}>🎓 LLM Training</button>
        </button>
        <div style={{ position: 'relative' }}>
          <button
            onClick={() => setSettingsOpen(!settingsOpen)}
            style={{
              background: settingsOpen ? '#00d9ff' : 'none',
              border: '1px solid #4a4a6a',
              borderRadius: 4,
              color: settingsOpen ? '#0f0f1a' : '#aaa',
              cursor: 'pointer',
              fontSize: 16,
              padding: '2px 8px',
              lineHeight: '1.4',
            }}
            title="LLM Settings"
          >
            ⚙
          </button>
          {settingsOpen && (
            <>
              <div
                style={{ position: 'fixed', inset: 0, zIndex: 99 }}
                onClick={() => setSettingsOpen(false)}
              />
              <div style={{
                position: 'fixed',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                zIndex: 100,
                background: '#1a1a2e',
                border: '1px solid #4a4a6a',
                borderRadius: 8,
                padding: 12,
                minWidth: 360,
                maxWidth: '90vw',
                maxHeight: '80vh',
                overflowY: 'auto',
                boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
                  <span style={{ fontSize: 13, fontWeight: 600, color: '#ccc' }}>LLM Settings</span>
                  <button
                    onClick={() => setSettingsOpen(false)}
                    style={{
                      background: 'none', border: 'none', color: '#888', cursor: 'pointer',
                      fontSize: 18, padding: '0 4px', lineHeight: 1,
                    }}
                    title="Close"
