                    ✕
                  </button>
                </div>
                <LLMConfig />
              </div>
            </>
          )}
        </div>

        {userName && (
          <div style={{ position: 'relative' }}>
            <button
              onClick={() => setUserMenuOpen(!userMenuOpen)}
              style={{
                background: userMenuOpen ? '#4ade80' : 'rgba(74,222,128,0.15)',
                border: '1px solid #4ade80',
                borderRadius: 4,
                color: userMenuOpen ? '#0f0f1a' : '#4ade80',
                cursor: 'pointer',
                fontSize: 12,
                padding: '2px 10px',
                lineHeight: '1.4',
                fontWeight: 600,
                whiteSpace: 'nowrap',
              }}
              title="User workspace folder"
            >
              👤 {userName}
            </button>
            {userMenuOpen && (
              <>
                <div
                  style={{ position: 'fixed', inset: 0, zIndex: 99 }}
                  onClick={() => setUserMenuOpen(false)}
                />
                <div style={{
                  position: 'absolute',
                  top: '100%',
                  right: 0,
                  marginTop: 4,
                  zIndex: 100,
                  background: '#1a1a2e',
                  border: '1px solid #4a4a6a',
                  borderRadius: 6,
                  padding: 10,
                  minWidth: 260,
                  boxShadow: '0 8px 24px rgba(0,0,0,0.4)',
                  fontSize: 12,
                }}>
                  <div style={{ fontWeight: 600, color: '#4ade80', marginBottom: 4 }}>📁 {userName}'s Workspace</div>
                  <div style={{ color: '#888', marginBottom: 8 }}>
                    All your projects, roadmaps, and code exports are saved here.
                  </div>
                  <div style={{ color: '#666', fontSize: 11, marginBottom: 6 }}>
                    <div><strong>Projects:</strong> backend/users/{userName}/projects/</div>
                    <div><strong>Roadmaps:</strong> backend/users/{userName}/roadmaps/</div>
                    <div><strong>Code Exports:</strong> backend/users/{userName}/code-exports/</div>
                  </div>
                  <button
                    onClick={handleLogout}
                    style={{
                      width: '100%',
                      marginTop: 8,
                      padding: '6px 10px',
                      border: '1px solid #ef4444',
                      borderRadius: 4,
                      background: 'rgba(239,68,68,0.1)',
