                      fontSize: 12,
                      fontWeight: 600,
                      cursor: 'pointer',
                    }}
                  >
                    🚪 Logout
                  </button>
                </div>
              </>
            )}
          </div>
        )}
      </header>

      <div className="app-main-container">
        <div className="canvas-area">
      {!roadmapDetached && <RoadmapDocked />}
      {roadmapDetached && (
        <div className="roadmap-reattach-bar">
          <span>Roadmap detached</span>
          <button className="roadmap-reattach-btn" onClick={() => setRoadmapDetached(false)}>
            ↩ Reattach
          </button>
        </div>
      )}
          <NodePalette onDragStart={handleDragStart} />
          <Canvas />
        </div>
        <ModelExplorer />

      </div>
