import React, { useCallback, useRef, useEffect, useState } from 'react';
import ReactFlow, {
  Node,
  Connection,
  addEdge,
  ReactFlowInstance,
  Controls,
  Background,
  MiniMap,
  applyNodeChanges,
  applyEdgeChanges,
} from 'reactflow';
import 'reactflow/dist/style.css';
import { NodeType } from '../types';
import CustomNode from './CustomNode';
import MasterNode from './MasterNode';
import { useProjectStore, getNextNodeId } from '../store/projectStore';
import './Canvas.css';

const nodeTypes = {
  master: MasterNode,
  input: CustomNode,
  output: CustomNode,
  logic: CustomNode,
  api: CustomNode,
  database: CustomNode,
  ui: CustomNode,
};

const typeColors: Record<string, string> = {
  master: '#f59e0b',
  input: '#4ade80',
  output: '#f87171',
  logic: '#60a5fa',
  api: '#a78bfa',
  database: '#fbbf24',
  ui: '#f472b6',
};

export default function Canvas() {
  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const reactFlowInstanceRef = useRef<ReactFlowInstance | null>(null);
  const store = useProjectStore();
  const { addNode, setSelectedNode, updateNodePosition, targetOS } = store;

  const [rfNodes, setRfNodes] = useState<Node[]>([]);
  const [rfEdges, setRfEdges] = useState<any[]>([]);
  const storeNodesRef = useRef(store.nodes);
  const storeEdgesRef = useRef(store.edges);

  storeNodesRef.current = store.nodes;
  storeEdgesRef.current = store.edges;

  const [pendingNode, setPendingNode] = useState<{ node: Node; index: number } | null>(null);
  const [nodeName, setNodeName] = useState('');
  const [nodeDesc, setNodeDesc] = useState('');

  const masterCreatedRef = useRef(false);

  useEffect(() => {
    if (masterCreatedRef.current) return;
    const hasMaster = store.nodes.some((n: Node) => n.type === 'master');
    if (!hasMaster && store.nodes.length === 0) {
      const masterNode: Node = {
        id: 'master-node',
        type: 'master',
        position: { x: 250, y: 50 },
        data: {
          label: 'App Blueprint',
          appGoal: '',
          appPurpose: '',
          selectedOS: targetOS || 'linux',
          status: 'pending',
        },
      };
      addNode(masterNode);
      masterCreatedRef.current = true;
    }
  }, []);

  useEffect(() => {
    setRfNodes(store.nodes);
    setRfEdges(store.edges);
  }, [store.nodes, store.edges]);

  const onNodesChange = useCallback(
    (changes: any) => {
      setRfNodes((nds) => applyNodeChanges(changes, nds));
    },
    []
  );

  const onEdgesChange = useCallback(
    (changes: any) => {
      setRfEdges((eds) => applyEdgeChanges(changes, eds));
    },
    []
  );

  const onNodeDragStop = useCallback(
    (_: React.MouseEvent, node: Node) => {
      setRfNodes((nds) => nds.map((n) => (n.id === node.id ? node : n)));
      updateNodePosition(node.id, node.position);
    },
    [updateNodePosition]
  );

  const onConnect = useCallback(
    (params: Connection) => {
      if (!params.source || !params.target) return;
      const newEdge = {
        id: `edge_${params.source}_${params.target}`,
        type: 'default' as const,
        source: params.source,
        target: params.target,
        sourceHandle: params.sourceHandle,
        targetHandle: params.targetHandle,
      };
      setRfEdges((eds) => addEdge(newEdge, eds));
      store.addEdge(newEdge);
    },
    [store]
  );

  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();

      const type = event.dataTransfer.getData('application/reactflow') as NodeType;
      if (!type) return;

      const instance = reactFlowInstanceRef.current;
      if (!instance) return;
      const position = instance.screenToFlowPosition({
        x: event.clientX,
        y: event.clientY,
      });

      const newNode: Node = {
        id: getNextNodeId(),
        type,
        position,
        data: {
          label: type,
          description: '',
          type,
          status: 'pending' as const,
        },
      };

      setRfNodes((nds) => [...nds, newNode]);
      setPendingNode({ node: newNode, index: 0 });
      setNodeName('');
      setNodeDesc('');
    },
    [setRfNodes]
  );

  const handleConfirmNode = useCallback(() => {
    if (!pendingNode) return;
    const name = nodeName.trim() || pendingNode.node.data.label as string;
    const updated = {
      ...pendingNode.node,
      data: {
        ...pendingNode.node.data,
        label: name,
        description: nodeDesc,
      },
    };
    addNode(updated);
    setPendingNode(null);
  }, [pendingNode, nodeName, nodeDesc, addNode]);

  const handleCancelNode = useCallback(() => {
    if (!pendingNode) return;
    setRfNodes((nds) => nds.filter((n) => n.id !== pendingNode.node.id));
    setPendingNode(null);
  }, [pendingNode]);

  const onNodeClick = useCallback(
    (_: React.MouseEvent, node: Node) => {
      setSelectedNode(node.id);
    },
    [setSelectedNode]
  );

  return (
    <div className="canvas-wrapper" ref={reactFlowWrapper}>
      <ReactFlow
        nodes={rfNodes}
        edges={rfEdges}
        onNodesChange={onNodesChange}
        onEdgesChange={onEdgesChange}
        onNodeDragStop={onNodeDragStop}
        onConnect={onConnect}
        onDrop={onDrop}
        onDragOver={onDragOver}
        onNodeClick={onNodeClick}
        onInit={(instance) => { reactFlowInstanceRef.current = instance; }}
        nodeTypes={nodeTypes}
        fitView
        snapToGrid
        snapGrid={[15, 15]}
      >
        <Controls />
        <MiniMap
          nodeColor={(node) => typeColors[node.type ?? 'logic'] || '#666'}
          maskColor="rgba(0, 0, 0, 0.6)"
        />
        <Background color="#4a4a6a" gap={20} />
      </ReactFlow>

      {pendingNode && (
        <div className="node-name-overlay" onClick={handleCancelNode}>
          <div className="node-name-dialog" onClick={(e) => e.stopPropagation()}>
            <div className="node-name-header">
              <span
                className="node-name-type-badge"
                style={{ background: typeColors[pendingNode.node.type || 'logic'] || '#666' }}
              >
                {pendingNode.node.type}
              </span>
              <span className="node-name-title">New Node</span>
            </div>
            <label className="node-name-field">
              <span>Name</span>
              <input
                value={nodeName}
                onChange={(e) => setNodeName(e.target.value)}
                placeholder={`New ${pendingNode.node.type} node`}
                autoFocus
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleConfirmNode();
                  if (e.key === 'Escape') handleCancelNode();
                }}
              />
            </label>
            <label className="node-name-field">
              <span>Description</span>
              <textarea
                value={nodeDesc}
                onChange={(e) => setNodeDesc(e.target.value)}
                placeholder="Describe what this node should do..."
                rows={3}
              />
            </label>
            <div className="node-name-actions">
              <button className="nn-btn nn-cancel" onClick={handleCancelNode}>Cancel</button>
              <button className="nn-btn nn-confirm" onClick={handleConfirmNode}>Add Node</button>
            </div>
          </div>
        </div>
      )}


    </div>
  );
}

