import { useState, useEffect, useCallback, useRef } from 'react';

interface Props {
  onChange?: (model: string, key: string) => void;
}

interface LLMState {
  provider: string;
  model: string;
  apiKey: string;
  baseUrl: string;
}

interface LLMProfile {
  name: string;
  primary: LLMState;
}

const PROVIDERS = [
  { id: 'openai', label: 'OpenAI', needsKey: true, needsBaseUrl: true, defaultModel: 'gpt-4', defaultBaseUrl: 'https://api.openai.com/v1' },
  { id: 'anthropic', label: 'Anthropic', needsKey: true, needsBaseUrl: false, defaultModel: 'claude-sonnet-4-20250514', defaultBaseUrl: '' },
  { id: 'ollama', label: 'Ollama (Local)', needsKey: false, needsBaseUrl: false, defaultModel: '', defaultBaseUrl: 'http://127.0.0.1:11434/v1' },
];

function useDebounce<T>(value: T, ms: number): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), ms);
    return () => clearTimeout(id);
  }, [value, ms]);
  return debounced;
}

const OPENAI_MODELS = ['gpt-4', 'gpt-4-turbo', 'gpt-4o', 'gpt-4o-mini', 'gpt-3.5-turbo'];
const ANTHROPIC_MODELS = ['claude-sonnet-4-20250514', 'claude-3-5-sonnet-latest', 'claude-3-opus-latest', 'claude-3-haiku-latest'];
const OLLAMA_CHAT_MODELS = ['llama3.2', 'llama3.1', 'llama3', 'mistral', 'gemma2', 'phi3', 'qwen2.5', 'deepseek-r1', 'deepseek-v3', 'deepseek-v4'];
const CODE_KEYWORDS = ['embed', 'codellama', 'codegemma', 'starcoder', 'codeqwen', 'deepseek-coder'];

const LS_KEYS = {
  primary: { provider: 'llm-provider', model: 'llm-model', key: 'llm-key', baseUrl: 'llm-base-url' },

};
const PROFILES_KEY = 'llm-profiles';

function loadPersistedLLM(keys: typeof LS_KEYS.primary): LLMState {
  return {
    provider: localStorage.getItem(keys.provider) || 'ollama',
    model: localStorage.getItem(keys.model) || '',
    apiKey: localStorage.getItem(keys.key) || '',
    baseUrl: localStorage.getItem(keys.baseUrl) || '',
  };
}

function persistToServer(primary: LLMState) {
  localStorage.setItem(LS_KEYS.primary.provider, primary.provider);
  localStorage.setItem(LS_KEYS.primary.model, primary.model);
  localStorage.setItem(LS_KEYS.primary.key, primary.apiKey);
  localStorage.setItem(LS_KEYS.primary.baseUrl, primary.baseUrl);
  fetch('/api/config/llm', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      primary: { provider: primary.provider, apiKey: primary.apiKey, model: primary.model, baseUrl: primary.baseUrl },
    }),
  }).catch(() => {});
}

function loadProfiles(): LLMProfile[] {
  try {
    return JSON.parse(localStorage.getItem(PROFILES_KEY) || '[]');
  } catch { return []; }
}

function saveProfiles(profiles: LLMProfile[]) {
  localStorage.setItem(PROFILES_KEY, JSON.stringify(profiles));
}

function LLMConfigSection({
  state,
  onChange,
  ollamaModels,
  ollamaScanning,
  onDetectOllama,
}: {
  state: LLMState;
  onChange: (s: LLMState) => void;
  ollamaModels: string[];
  ollamaScanning: boolean;
  onDetectOllama: () => void;
}) {
  const providerCfg = PROVIDERS.find(p => p.id === state.provider);
  const modelOptions = state.provider === 'ollama'
    ? (ollamaModels.length > 0 ? ollamaModels : OLLAMA_CHAT_MODELS)
    : state.provider === 'anthropic'
    ? ANTHROPIC_MODELS
    : OPENAI_MODELS;

  const set = (partial: Partial<LLMState>) => onChange({ ...state, ...partial });

  const handleProviderChange = (p: string) => {
    if (p === 'ollama') {
      set({ provider: p, apiKey: '', model: '', baseUrl: 'http://127.0.0.1:11434/v1' });
      onDetectOllama();
    } else if (p === 'openai') {
      set({ provider: p, model: OPENAI_MODELS[0], baseUrl: 'https://api.openai.com/v1' });
    } else if (p === 'anthropic') {
      set({ provider: p, model: ANTHROPIC_MODELS[0], baseUrl: '' });
    }
  };

  return (
    <div className="llm-config-section">
      <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
        <label style={{ fontSize: 11 }}>
          Provider:
          <select value={state.provider} onChange={(e) => handleProviderChange(e.target.value)}>
            {PROVIDERS.map(p => (
              <option key={p.id} value={p.id}>{p.label}</option>
            ))}
          </select>
        </label>

        {state.provider === 'ollama' && (
          <label style={{ fontSize: 11 }}>
            <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
              Model:
              <button onClick={onDetectOllama} disabled={ollamaScanning} style={{ fontSize: 11, padding: '1px 6px' }}>
                {ollamaScanning ? 'Scanning...' : '🔄'}
              </button>
            </span>
            <select value={state.model} onChange={(e) => set({ model: e.target.value })}>
              {modelOptions.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </label>
        )}

        {state.provider !== 'ollama' && (
          <label style={{ fontSize: 11 }}>
            Model:
            <select value={state.model} onChange={(e) => set({ model: e.target.value })}>
              {modelOptions.map(m => <option key={m} value={m}>{m}</option>)}
            </select>
          </label>
        )}

        {providerCfg?.needsKey && (
          <label style={{ fontSize: 11 }}>
            API Key:
            <input
              type="password"
              value={state.apiKey}
              onChange={(e) => set({ apiKey: e.target.value })}
              placeholder={state.provider === 'openai' ? 'sk-...' : 'Enter your Anthropic key'}
            />
          </label>
        )}

        {state.provider === 'ollama' && (
          <label style={{ fontSize: 11 }}>
            Host:
            <input
              type="text"
              value={state.baseUrl}
              onChange={(e) => set({ baseUrl: e.target.value })}
              placeholder="http://127.0.0.1:11434/v1"
            />
          </label>
        )}

        {state.provider === 'openai' && (
          <label style={{ fontSize: 11 }}>
            API Base URL:
            <input
              type="text"
              value={state.baseUrl}
              onChange={(e) => set({ baseUrl: e.target.value })}
              placeholder="https://api.openai.com/v1"
            />
          </label>
        )}
      </div>
    </div>
  );
}

const btnStyle: React.CSSProperties = {
  fontSize: 10,
  padding: '2px 6px',
  border: '1px solid #4a4a6a',
  borderRadius: 3,
  background: '#2a2a3e',
  color: '#ccc',
  cursor: 'pointer',
};

const LLMConfig: React.FC<Props> = ({ onChange }) => {
  const [primary, setPrimary] = useState<LLMState>(() => loadPersistedLLM(LS_KEYS.primary));
  const [ollamaModels, setOllamaModels] = useState<string[]>([]);
  const [ollamaScanning, setOllamaScanning] = useState(false);
  const [profiles, setProfiles] = useState<LLMProfile[]>(() => loadProfiles());
  const [selectedProfile, setSelectedProfile] = useState('');
  const [profileNameInput, setProfileNameInput] = useState('');
  const [showNewProfile, setShowNewProfile] = useState(false);
  const [saveStatus, setSaveStatus] = useState<'idle' | 'saving' | 'saved' | 'error'>('idle');
  const importRef = useRef<HTMLInputElement>(null);

  const detectOllama = useCallback(async () => {
    setOllamaScanning(true);
    const tagUrls = [
      'http://127.0.0.1:11434/api/tags',
      'http://localhost:11434/api/tags',
      '/api/config/ollama-models',
    ];
    for (const tagUrl of tagUrls) {
      try {
        const res = await fetch(tagUrl, { signal: AbortSignal.timeout(3000) });
        if (res.ok) {
          const data = await res.json();
          const names: string[] = (data.models || []).map((m: any) => m.name);
          const chatModels = names.filter(n => !CODE_KEYWORDS.some(k => n.toLowerCase().includes(k)));
          if (chatModels.length > 0) {
            setOllamaModels(chatModels);
            setOllamaScanning(false);
            return;
          }
        }
      } catch {}
    }
    setOllamaModels(OLLAMA_CHAT_MODELS);
    setOllamaScanning(false);
  }, []);

  useEffect(() => {
    detectOllama();
  }, []);

  const debouncedPrimary = useDebounce(primary, 500);

  useEffect(() => {
    if (debouncedPrimary.model) {
      persistToServer(debouncedPrimary);
      onChange?.(debouncedPrimary.model, debouncedPrimary.apiKey);
    }
  }, [debouncedPrimary]);

  const getCurrentSnapshot = (): LLMProfile => ({
    name: selectedProfile || 'current',
    primary: { ...primary },
  });

  const handleSave = () => {
    const name = profileNameInput.trim();
    if (!name) return;
    const updated = [...profiles.filter(p => p.name !== name)];
    updated.push({ name, primary: { ...primary } });
    updated.sort((a, b) => a.name.localeCompare(b.name));
    saveProfiles(updated);
    setProfiles(updated);
    setSelectedProfile(name);
    setShowNewProfile(false);
    setProfileNameInput('');
  };

  const handleLoad = () => {
    const profile = profiles.find(p => p.name === selectedProfile);
    if (!profile) return;
    setPrimary(profile.primary);
  };

  const handleNew = () => {
    setSelectedProfile('');
    setProfileNameInput('');
    setShowNewProfile(true);
  };

  const handleExport = () => {
    const snapshot = getCurrentSnapshot();
    const blob = new Blob([JSON.stringify(snapshot, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${snapshot.name.replace(/\s+/g, '_')}_llm_config.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = () => {
    importRef.current?.click();
  };

  const handlePersistToDisk = async () => {
    setSaveStatus('saving');
    try {
      const res = await fetch('/api/config/llm/save', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          primary: { provider: primary.provider, apiKey: primary.apiKey, model: primary.model, baseUrl: primary.baseUrl },
        }),
      });
      if (res.ok) {
        setSaveStatus('saved');
        setTimeout(() => setSaveStatus('idle'), 2000);
      } else {
        setSaveStatus('error');
        setTimeout(() => setSaveStatus('idle'), 3000);
      }
    } catch {
      setSaveStatus('error');
      setTimeout(() => setSaveStatus('idle'), 3000);
    }
  };

  const handleImportFile = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const profile: LLMProfile = JSON.parse(ev.target?.result as string);
        if (profile.primary) {
          setPrimary(profile.primary);

          if (profile.name) setSelectedProfile(profile.name);
        }
      } catch {}
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  return (
    <div className="llm-config" style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
      <input
        ref={importRef}
        type="file"
        accept=".json"
        style={{ display: 'none' }}
        onChange={handleImportFile}
      />

      <div style={{ display: 'flex', alignItems: 'center', gap: 4, flexWrap: 'wrap' }}>
        <select
          value={selectedProfile}
          onChange={(e) => setSelectedProfile(e.target.value)}
          style={{ flex: 1, fontSize: 11, minWidth: 100 }}
        >
          <option value="">-- Select Profile --</option>
          {profiles.map(p => (
            <option key={p.name} value={p.name}>{p.name}</option>
          ))}
        </select>
        <button style={btnStyle} onClick={handleNew} title="New profile">New</button>
        {showNewProfile ? (
          <>
            <input
              type="text"
              value={profileNameInput}
              onChange={(e) => setProfileNameInput(e.target.value)}
              placeholder="Profile name"
              style={{ fontSize: 10, width: 90, padding: '1px 4px' }}
              onKeyDown={(e) => { if (e.key === 'Enter') handleSave(); }}
            />
            <button style={btnStyle} onClick={handleSave}>Save</button>
          </>
        ) : (
          <button style={btnStyle} onClick={handleSave} title="Save current as">Save</button>
        )}
        <button style={btnStyle} onClick={handleLoad} title="Load selected profile" disabled={!selectedProfile}>Load</button>
        <button style={btnStyle} onClick={handleExport} title="Export as JSON">Export</button>
        <button style={btnStyle} onClick={handleImport} title="Import from JSON">Import</button>
      </div>

      <div style={{
        border: '1px solid #4a9eff',
        borderRadius: 6,
        padding: 10,
        background: 'rgba(74, 158, 255, 0.05)'
      }}>
        <div style={{ fontSize: 13, fontWeight: 'bold', color: '#4a9eff', marginBottom: 6 }}>
          LLM 1 — Reasoning & Design
        </div>
        <div style={{ fontSize: 10, color: '#888', marginBottom: 8 }}>
          Handles reasoning, blueprints, roadmap, and code design
        </div>
        <LLMConfigSection
          state={primary}
          onChange={setPrimary}
          ollamaModels={ollamaModels}
          ollamaScanning={ollamaScanning}
          onDetectOllama={detectOllama}
        />
      </div>



      <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'flex-end' }}>
        <span style={{ fontSize: 10, color: saveStatus === 'saved' ? '#4ade80' : saveStatus === 'error' ? '#f87171' : '#888' }}>
          {saveStatus === 'saving' ? 'Saving...' : saveStatus === 'saved' ? 'Saved to disk' : saveStatus === 'error' ? 'Save failed' : ''}
        </span>
        <button
          onClick={handlePersistToDisk}
          disabled={saveStatus === 'saving'}
          style={{
            fontSize: 11, padding: '5px 14px', border: '1px solid #4ade80', borderRadius: 4,
            background: 'rgba(74, 222, 128, 0.1)', color: '#4ade80', cursor: 'pointer', fontWeight: 500,
          }}
        >
          {saveStatus === 'saving' ? 'Saving...' : '💾 Save to Disk'}
        </button>
      </div>
    </div>
  );
};

export default LLMConfig;

import React, { useState, useEffect } from 'react';
import axios from 'axios';

interface DashboardStats {
  patterns: {
    total: number;
    byLanguage: Record<string, number>;
    byNodeType: Record<string, number>;
    byTag: Record<string, number>;
    averageQuality: number;
  };
  neural: {
    loss: number | null;
    iterations: number;
    trainedChars: number;
  } | null;
}

interface LearningDashboardProps {
  onClose?: () => void;
}

const LearningDashboard: React.FC<LearningDashboardProps> = ({ onClose }) => {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedSection, setSelectedSection] = useState<'overview' | 'patterns' | 'neural'>('overview');

  useEffect(() => {
    fetchStats();
    const interval = setInterval(fetchStats, 10000);
    return () => clearInterval(interval);
  }, []);

  const fetchStats = async () => {
    try {
      const res = await axios.get('/api/knowledge/stats');
      setStats(res.data);
      setLoading(false);
    } catch (err) {
      console.error('Failed to load dashboard stats:', err);
      setError('Could not connect to learning system');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div style={{ padding: '20px', color: '#888', textAlign: 'center' }}>
        Loading learning dashboard...
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ padding: '20px', color: '#e74c3c', textAlign: 'center' }}>
        {error}
      </div>
    );
  }

  if (!stats) return null;

  const totalPatterns = stats.patterns.total;
  const neuralStatus = stats.neural;
  const understandingScore = neuralStatus?.loss != null
    ? Math.max(0, Math.min(100, ((Math.exp(Math.log(95)) - Math.exp(neuralStatus.loss / 64)) / Math.exp(Math.log(95))) * 100)).toFixed(1)
    : 'N/A';

  return (
    <div style={{
      background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
      borderRadius: '16px',
      padding: '24px',
      color: '#e0e0e0',
      fontFamily: 'system-ui, sans-serif',
      maxWidth: '600px',
      margin: '0',
      boxShadow: '0 8px 32px rgba(0,0,0,0.4)',
      position: 'relative',
      border: '1px solid rgba(255,255,255,0.1)',
    }}>
      {/* Header */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
        <h2 style={{ margin: 0, fontSize: '1.5rem', color: '#fff' }}>🧠 Learning Dashboard</h2>
        {onClose && (
          <button onClick={onClose} style={{
            background: 'rgba(255,255,255,0.1)',
            border: 'none',
            color: '#aaa',
            borderRadius: '8px',
            padding: '4px 12px',
            cursor: 'pointer',
            fontSize: '1.2rem',
            fontWeight: 600,
          }}>✕</button>
        )}
        <div style={{ display: 'flex', gap: '8px' }}>
          {(['overview', 'patterns', 'neural'] as const).map(section => (
            <button key={section}
              onClick={() => setSelectedSection(section)}
              style={{
                padding: '6px 14px',
                borderRadius: '8px',
                border: 'none',
                cursor: 'pointer',
                fontSize: '0.85rem',
                fontWeight: 600,
                background: selectedSection === section ? '#667eea' : 'rgba(255,255,255,0.1)',
                color: selectedSection === section ? '#fff' : '#aaa',
                transition: 'all 0.2s',
              }}>
              {section.charAt(0).toUpperCase() + section.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Overview Tab */}
      {selectedSection === 'overview' && (
        <div>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '12px', marginBottom: '20px' }}>
            <StatCard label="Patterns Learned" value={totalPatterns.toString()} color="#667eea" />
            <StatCard label="Understanding" value={`${understandingScore}%`} color="#a8e6cf" />
            <StatCard label="Chars Trained" value={(neuralStatus?.trainedChars || 0).toLocaleString()} color="#ffd93d" />
            <StatCard label="Iterations" value={(neuralStatus?.iterations || 0).toLocaleString()} color="#ff6b6b" />
          </div>

          {/* Neural training progress bar */}
          <div style={{ background: 'rgba(255,255,255,0.05)', borderRadius: '12px', padding: '16px', marginBottom: '16px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px', fontSize: '0.9rem' }}>
              <span>Neural Network Training</span>
              <span style={{ color: '#a8e6cf' }}>Loss: {neuralStatus?.loss?.toFixed(2) || 'N/A'}</span>
            </div>
            <div style={{
              height: '8px',
              background: 'rgba(255,255,255,0.1)',
              borderRadius: '4px',
              overflow: 'hidden',
            }}>
              <div style={{
                height: '100%',
                width: `${Math.min(100, (parseFloat(understandingScore as string) || 0))}%`,
                background: 'linear-gradient(90deg, #667eea, #764ba2)',
                borderRadius: '4px',
                transition: 'width 1s ease',
              }} />
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '6px', fontSize: '0.75rem', color: '#888' }}>
              <span>Understanding Score</span>
              <span>{understandingScore}%</span>
            </div>
          </div>

          {/* Auto-training status */}
          <div style={{ background: 'rgba(102,126,234,0.1)', borderRadius: '8px', padding: '10px 14px', fontSize: '0.85rem', color: '#aab' }}>
            ⚡ Auto-training active — RNN learns after each project build
          </div>
        </div>
      )}

      {/* Patterns Tab */}
      {selectedSection === 'patterns' && (
        <div>
          <div style={{ marginBottom: '16px' }}>
            <h3 style={{ margin: '0 0 12px 0', fontSize: '1.1rem', color: '#ccc' }}>By Language</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {Object.entries(stats.patterns.byLanguage).map(([lang, count]) => (
                <span key={lang} style={{
