                  fontSize: '0.85rem',
                }}>
                  {lang}: {count}
                </span>
              ))}
            </div>
          </div>
          <div style={{ marginBottom: '16px' }}>
            <h3 style={{ margin: '0 0 12px 0', fontSize: '1.1rem', color: '#ccc' }}>By Node Type</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {Object.entries(stats.patterns.byNodeType).map(([type, count]) => (
                <span key={type} style={{
                  padding: '4px 12px',
                  borderRadius: '12px',
                  background: 'rgba(255,217,61,0.15)',
                  color: '#fd3',
                  fontSize: '0.85rem',
                }}>
                  {type}: {count}
                </span>
              ))}
            </div>
          </div>
          <div>
            <h3 style={{ margin: '0 0 12px 0', fontSize: '1.1rem', color: '#ccc' }}>Top Tags</h3>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
              {Object.entries(stats.patterns.byTag)
                .sort(([,a], [,b]) => b - a)
                .slice(0, 10)
                .map(([tag, count]) => (
                <span key={tag} style={{
                  padding: '4px 12px',
                  borderRadius: '12px',
                  background: 'rgba(168,230,207,0.15)',
                  color: '#8ec',
                  fontSize: '0.85rem',
                }}>
                  {tag}: {count}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Neural Tab */}
      {selectedSection === 'neural' && (
        <div>
          <div style={{ background: 'rgba(255,255,255,0.05)', borderRadius: '12px', padding: '16px' }}>
            <h3 style={{ margin: '0 0 16px 0', fontSize: '1.1rem', color: '#ccc' }}>Model Status</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
              <DetailRow label="Initialized" value={neuralStatus ? 'Yes' : 'No'} />
              <DetailRow label="Loss" value={neuralStatus?.loss?.toFixed(4) || 'N/A'} />
              <DetailRow label="Iterations" value={neuralStatus?.iterations?.toLocaleString() || '0'} />
              <DetailRow label="Characters Trained" value={neuralStatus?.trainedChars?.toLocaleString() || '0'} />
            </div>
          </div>
          <div style={{ marginTop: '16px', display: 'flex', gap: '10px', justifyContent: 'center' }}>
            <a href="/api/knowledge" target="_blank" rel="noopener noreferrer" style={{
              padding: '8px 20px',
              borderRadius: '8px',
              background: 'rgba(102,126,234,0.2)',
              color: '#8be',
              textDecoration: 'none',
              fontSize: '0.85rem',
              fontWeight: 600,
            }}>
              View All Patterns
            </a>
            <a href="/api/neural" target="_blank" rel="noopener noreferrer" style={{
              padding: '8px 20px',
              borderRadius: '8px',
              background: 'rgba(168,230,207,0.15)',
              color: '#8ec',
              textDecoration: 'none',
              fontSize: '0.85rem',
              fontWeight: 600,
            }}>
              Neural Model Status
            </a>
          </div>
        </div>
      )}
    </div>
  );
};

