export default function NodeLogicEditor() {
  const {
    nodes,
    selectedNode,
    logicEditorOpen,
    setLogicEditorOpen,
    addSubNode,
    deleteSubNode,
    addSubNodeEdge,
  } = useProjectStore();

  const parentNode = nodes.find((n) => n.id === selectedNode);
  const subNodes = (parentNode?.data?.subNodes as SubNodeData[]) || [];
  const subEdges = (parentNode?.data?.subNodeEdges || []) as Array<{ id: string; source: string; target: string }>;

  const [reactFlowNodes, setReactFlowNodes, onNodesChange] = useNodesState([]);
  const [reactFlowEdges, setReactFlowEdges, onEdgesChange] = useEdgesState([]);
  const reactFlowWrapper = useRef<HTMLDivElement>(null);
  const reactFlowInstanceRef = useRef<ReactFlowInstance | null>(null);

  useEffect(() => {
    if (logicEditorOpen && parentNode) {
      setReactFlowNodes(
        subNodes.map((sn) => ({
          id: sn.id,
          type: sn.type,
          position: sn.position,
          data: sn,
        }))
      );
      setReactFlowEdges(subEdges);
    }
  }, [nodes, selectedNode, logicEditorOpen]);

  const onConnect = useCallback(
    (params: Connection) => {
      if (!params.source || !params.target) return;
      if (!selectedNode) return;
      const newEdge = {
        id: `sub_edge_${params.source}_${params.target}`,
        type: 'default',
        source: params.source,
        target: params.target,
        sourceHandle: params.sourceHandle,
        targetHandle: params.targetHandle,
      };
      setReactFlowEdges((eds) => addEdge(newEdge, eds));
      addSubNodeEdge(selectedNode, newEdge);
    },
    [selectedNode, setReactFlowEdges, addSubNodeEdge]
  );

  const onDragOver = useCallback((event: React.DragEvent) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = 'move';
  }, []);

  const onDrop = useCallback(
    (event: React.DragEvent) => {
      event.preventDefault();

      const type = event.dataTransfer.getData('application/reactflow') as NodeType;
      if (!type || !selectedNode) return;

      const instance = reactFlowInstanceRef.current;
      if (!instance) return;
      const position = instance.screenToFlowPosition({
        x: event.clientX,
        y: event.clientY,
      });

      const newSubNode: SubNodeData = {
        id: getNextSubNodeId(),
        label: type,
        description: '',
        type,
        status: 'pending',
        position,
      };

      setReactFlowNodes((nds) => [
        ...nds,
        { id: newSubNode.id, type, position, data: newSubNode },
      ]);
      addSubNode(selectedNode, newSubNode);
    },
    [selectedNode, setReactFlowNodes, addSubNode]
  );

  const handleDeleteSubNode = useCallback(
    (nodeId: string) => {
      if (!selectedNode) return;
      setReactFlowNodes((nds) => nds.filter((n) => n.id !== nodeId));
      deleteSubNode(selectedNode, nodeId);
    },
    [selectedNode, setReactFlowNodes, deleteSubNode]
  );

  if (!logicEditorOpen || !parentNode) return null;

  return (
    <div className="node-logic-overlay">
      <div className="node-logic-panel">
        <div className="logic-header">
          <div className="logic-header-info">
            <span className="logic-parent-label">{parentNode.data?.label}</span>
            <span className="logic-parent-id">{parentNode.id}</span>
          </div>
          <button className="logic-close-btn" onClick={() => setLogicEditorOpen(false)}>
            ✕
          </button>
        </div>

        <div className="logic-toolbar">
          <span className="logic-toolbar-label">Drag sub-nodes here:</span>
          <div className="logic-node-palette">
            {(['input', 'output', 'logic', 'api', 'database', 'ui'] as NodeType[]).map((type) => (
              <div
                key={type}
                className="logic-palette-item"
                draggable
                onDragStart={(e) => {
                  e.dataTransfer.setData('application/reactflow', type);
                  e.dataTransfer.effectAllowed = 'move';
                }}
              >
                <span className={`logic-dot logic-dot-${type}`} />
                <span className="logic-palette-label">{type}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="logic-canvas-wrapper" ref={reactFlowWrapper}>
          <ReactFlow
            nodes={reactFlowNodes}
            edges={reactFlowEdges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={onConnect}
            onDrop={onDrop}
            onDragOver={onDragOver}
            onInit={(instance) => { reactFlowInstanceRef.current = instance; }}
            nodeTypes={nodeTypes}
            fitView
            snapToGrid
            snapGrid={[15, 15]}
          >
            <Controls />
            <Background color="#4a4a6a" gap={20} />
          </ReactFlow>
        </div>

        <div className="logic-subnode-list">
          <span className="logic-list-label">Sub-nodes ({subNodes.length})</span>
          {subNodes.length === 0 ? (
            <p className="logic-empty">Drag nodes from the palette above</p>
          ) : (
            <div className="logic-subnode-items">
              {subNodes.map((sn) => (
                <div key={sn.id} className="logic-subnode-item">
                  <span className={`logic-subnode-dot logic-dot-${sn.type}`} />
                  <span className="logic-subnode-name">{sn.label}</span>
                  <span className="logic-subnode-id">{sn.id}</span>
                  <button
                    className="logic-subnode-delete"
                    onClick={() => handleDeleteSubNode(sn.id)}
                  >
                    ✕
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React from 'react';
import { NodeType } from '../types';
import { useProjectStore } from '../store/projectStore';

interface NodePaletteProps {
  onDragStart: (event: React.DragEvent, nodeType: NodeType) => void;
}

const nodeTypes: { type: NodeType; label: string; icon: string; description: string }[] = [
  { type: 'input', label: 'Input', icon: '⬅', description: 'Data entry point' },
  { type: 'output', label: 'Output', icon: '➡', description: 'Result display' },
  { type: 'logic', label: 'Logic', icon: '⚙', description: 'Processing/conditions' },
  { type: 'api', label: 'API', icon: '🌐', description: 'External service call' },
  { type: 'database', label: 'Database', icon: '📦', description: 'Data storage' },
  { type: 'ui', label: 'UI', icon: '🖥', description: 'User interface element' },
];

export default function NodePalette({ onDragStart }: NodePaletteProps) {
  const { nodes, selectedNode, setSelectedNode, deleteNode } = useProjectStore();

  const handleDeleteSelected = () => {
    if (!selectedNode || selectedNode === 'master-node') return;
    deleteNode(selectedNode);
    setSelectedNode(null);
  };

  const handleClearAll = () => {
    const nonMaster = nodes.filter((n) => n.id !== 'master-node');
    if (nonMaster.length === 0) return;
    if (confirm('Clear all nodes from the canvas? The blueprint node will be kept.')) {
      nonMaster.forEach((n) => deleteNode(n.id));
      setSelectedNode(null);
    }
  };

  return (
    <div className="node-palette">
      <h3>Nodes</h3>
      <p className="palette-hint">Drag nodes to the canvas</p>

      <div className="node-list">
        {nodeTypes.map((node) => (
          <div
            key={node.type}
            className="node-item"
            draggable
            onDragStart={(e) => { onDragStart(e, node.type); } }
          >
            <span className="node-item-icon">{node.icon}</span>
            <div className="node-item-info">
              <span className="node-item-label">{node.label}</span>
              <span className="node-item-desc">{node.description}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="palette-divider" />

      <div className="palette-actions">
        <div className="placed-nodes-header">
          <span>On Canvas ({nodes.length})</span>
        </div>
        <div className="placed-nodes-list">
          {nodes.length === 0 ? (
            <p className="placed-nodes-empty">No nodes placed</p>
          ) : (
            nodes.map((n) => (
              <div
                key={n.id}
                className={`placed-node-item ${selectedNode === n.id ? 'selected' : ''}`}
                onClick={() => setSelectedNode(n.id === selectedNode ? null : n.id)}
              >
                <span className="placed-node-type">{n.data?.type || '?'}</span>
                <span className="placed-node-label">{n.data?.label || n.id}</span>
              </div>
            ))
          )}
        </div>
        <button
          className="palette-btn delete-btn"
          onClick={handleDeleteSelected}
          disabled={!selectedNode}
        >
          Delete Selected
        </button>
        <button
          className="palette-btn clear-btn"
          onClick={handleClearAll}
          disabled={nodes.length === 0}
        >
          Clear All
        </button>
      </div>
    </div>
  );
}

