  display: flex;
  flex-direction: column;
  transition: all 0.3s ease;
  z-index: 10;
}

.roadmap-panel.docked {
  width: 320px;
  position: relative;
}

.roadmap-panel.expanded {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: 450px;
  z-index: 1001;
  border-left: 1px solid #00d9ff;
  box-shadow: -10px 0 40px rgba(0, 0, 0, 0.5);
}

.roadmap-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.5);
  z-index: 1000;
}

.roadmap-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 14px 16px 10px;
  border-bottom: 1px solid #2a2a4a;
  background: #0f0f1a;
}

.roadmap-header-left {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.roadmap-header-actions {
  display: flex;
  gap: 4px;
}

.roadmap-action-btn {
  background: none;
  border: 1px solid #4a4a6a;
  color: #aaa;
  font-size: 14px;
  width: 32px;
  height: 32px;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.15s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.roadmap-action-btn:hover {
  border-color: #00d9ff;
  color: #00d9ff;
  background: rgba(0, 217, 255, 0.1);
}

.roadmap-title {
  font-size: 18px;
  color: #00d9ff;
  margin: 0;
}

.roadmap-subtitle {
